"use client";
import React, { useState, useCallback } from 'react';
import Cropper from 'react-easy-crop';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Crop, Check, ZoomIn, ZoomOut, RotateCcw } from 'lucide-react';

interface ImageCropperModalProps {
    isOpen: boolean;
    onClose: () => void;
    imageSrc: string;
    onCropComplete: (croppedImage: string) => void;
}

import { createPortal } from 'react-dom';

const ImageCropperModal = ({ isOpen, onClose, imageSrc, onCropComplete }: ImageCropperModalProps) => {
    const [crop, setCrop] = useState({ x: 0, y: 0 });
    const [zoom, setZoom] = useState(1);
    const [rotation, setRotation] = useState(0);
    const [croppedAreaPixels, setCroppedAreaPixels] = useState<any>(null);
    const [mounted, setMounted] = useState(false);

    React.useEffect(() => {
        setMounted(true);
        if (isOpen) {
            document.body.classList.add('scroll-locked');
        } else {
            document.body.classList.remove('scroll-locked');
        }
        return () => document.body.classList.remove('scroll-locked');
    }, [isOpen]);

    const onCropChange = (crop: any) => {
        setCrop(crop);
    };

    const onZoomChange = (zoom: number) => {
        setZoom(zoom);
    };

    const onCropAreaComplete = useCallback((_croppedArea: any, croppedAreaPixels: any) => {
        setCroppedAreaPixels(croppedAreaPixels);
    }, []);

    const createImage = (url: string): Promise<HTMLImageElement> =>
        new Promise((resolve, reject) => {
            const image = new Image();
            image.addEventListener('load', () => resolve(image));
            image.addEventListener('error', (error) => reject(error));
            image.setAttribute('crossOrigin', 'anonymous');
            image.src = url;
        });

    const getCroppedImg = async (imageSrc: string, pixelCrop: any, rotation = 0): Promise<string> => {
        const image = await createImage(imageSrc);
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        if (!ctx) return '';

        const rotateRad = (rotation * Math.PI) / 180;
        const { width: bBoxWidth, height: bBoxHeight } = {
            width: Math.abs(Math.cos(rotateRad) * image.width) + Math.abs(Math.sin(rotateRad) * image.height),
            height: Math.abs(Math.sin(rotateRad) * image.width) + Math.abs(Math.cos(rotateRad) * image.height),
        };

        canvas.width = bBoxWidth;
        canvas.height = bBoxHeight;

        ctx.translate(bBoxWidth / 2, bBoxHeight / 2);
        ctx.rotate(rotateRad);
        ctx.translate(-image.width / 2, -image.height / 2);

        ctx.drawImage(image, 0, 0);

        const data = ctx.getImageData(pixelCrop.x, pixelCrop.y, pixelCrop.width, pixelCrop.height);

        canvas.width = pixelCrop.width;
        canvas.height = pixelCrop.height;

        ctx.putImageData(data, 0, 0);

        return new Promise((resolve) => {
            canvas.toBlob((blob) => {
                if (!blob) return;
                const reader = new FileReader();
                reader.readAsDataURL(blob);
                reader.onloadend = () => {
                    resolve(reader.result as string);
                };
            }, 'image/jpeg');
        });
    };

    const handleConfirm = async () => {
        try {
            const croppedImage = await getCroppedImg(imageSrc, croppedAreaPixels, rotation);
            onCropComplete(croppedImage);
            onClose();
        } catch (e) {
            console.error(e);
        }
    };

    if (!mounted) return null;

    return createPortal(
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0 bg-black/80"
                        onClick={onClose}
                    />
                    <motion.div
                        initial={{ scale: 0.9, opacity: 0, y: 20 }}
                        animate={{ scale: 1, opacity: 1, y: 0 }}
                        exit={{ scale: 0.9, opacity: 0, y: 20 }}
                        className="relative w-full max-w-4xl bg-white border border-slate-100 rounded-[32px] overflow-hidden shadow-2xl flex flex-col h-[80vh]"
                    >
                        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-primary/10 rounded-xl text-primary font-black">
                                    <Crop size={20} />
                                </div>
                                <div>
                                    <h3 className="text-xl font-black text-primary uppercase tracking-tight">Crop & Potong Gambar</h3>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-none mt-1">Sesuaikan tampilan gambar sesuai keinginan</p>
                                </div>
                            </div>
                            <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                                <X size={24} />
                            </button>
                        </div>

                        <div className="relative flex-1 bg-slate-100 overflow-hidden">
                            <Cropper
                                image={imageSrc}
                                crop={crop}
                                zoom={zoom}
                                rotation={rotation}
                                aspect={undefined} // Free aspect ratio
                                onCropChange={onCropChange}
                                onCropComplete={onCropAreaComplete}
                                onZoomChange={onZoomChange}
                                onRotationChange={setRotation}
                            />
                        </div>

                        <div className="p-8 space-y-6 bg-white border-t border-slate-100">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-4">
                                    <label className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                        <span>Zoom</span>
                                        <span className="text-primary">{Math.round(zoom * 100)}%</span>
                                    </label>
                                    <div className="flex items-center gap-4">
                                        <ZoomOut size={16} className="text-slate-400" />
                                        <input
                                            type="range"
                                            value={zoom}
                                            min={1}
                                            max={3}
                                            step={0.1}
                                            aria-labelledby="Zoom"
                                            onChange={(e) => onZoomChange(Number(e.target.value))}
                                            className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-primary"
                                        />
                                        <ZoomIn size={16} className="text-slate-400" />
                                    </div>
                                </div>

                                <div className="space-y-4">
                                    <label className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                        <span>Rotation</span>
                                        <span className="text-primary">{rotation}°</span>
                                    </label>
                                    <div className="flex items-center gap-4">
                                        <RotateCcw size={16} className="text-slate-400" />
                                        <input
                                            type="range"
                                            value={rotation}
                                            min={0}
                                            max={360}
                                            step={1}
                                            aria-labelledby="Rotation"
                                            onChange={(e) => setRotation(Number(e.target.value))}
                                            className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-primary"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex justify-end gap-4 pt-4 border-t border-slate-50">
                                <button
                                    onClick={onClose}
                                    className="px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 transition-all border border-transparent"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={handleConfirm}
                                    className="px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest bg-primary text-white flex items-center gap-2 hover:bg-primary-light transition-all shadow-xl shadow-primary/20 active:scale-95"
                                >
                                    <Check size={16} /> Potong & Gunakan
                                </button>
                            </div>
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>,
        document.body
    );
};

export default ImageCropperModal;

"use client";

import { usePathname } from 'next/navigation';
import React, { useEffect, useState } from 'react';
import { AlertCircle } from 'lucide-react';
import { Plus_Jakarta_Sans } from 'next/font/google';

const jakarta = Plus_Jakarta_Sans({ subsets: ['latin'], weight: ['400', '600', '800'] });

export default function MaintenanceProvider({ 
    isMaintenance, 
    children 
}: { 
    isMaintenance: boolean, 
    children: React.ReactNode 
}) {
    const pathname = usePathname() || '';
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    // Prevent hydration mismatch by returning empty or children until mounted
    if (!mounted) {
        return <>{children}</>;
    }

    // Allow admins to login and access settings to turn off maintenance mode
    const isBypassRoute = pathname.startsWith('/dashboard/admin') || 
                          pathname === '/' || 
                          pathname.startsWith('/update-password') ||
                          pathname.startsWith('/api') ||
                          pathname.startsWith('/dashboard/settings'); // just in case

    if (isMaintenance && !isBypassRoute) {
        return (
            <div className={`min-h-screen flex items-center justify-center bg-[#f1f5f9] p-4 ${jakarta.className}`}>
                <div className="bg-white rounded-3xl shadow-xl p-10 max-w-lg w-full text-center border border-[#e2e8f0]">
                    <div className="w-20 h-20 bg-rose-50 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-inner">
                        <AlertCircle className="w-10 h-10 text-rose-500" />
                    </div>
                    <h1 className="text-3xl font-extrabold text-[#030C4D] mb-4">Under Maintenance</h1>
                    <p className="text-slate-500 mb-8 leading-relaxed">
                        Sistem kami saat ini sedang dalam pemeliharaan rutin untuk meningkatkan layanan. Silakan kembali beberapa saat lagi.
                    </p>
                    
                    <div className="w-full bg-slate-50 rounded-xl p-4 text-xs font-semibold text-slate-400 border border-slate-100 flex items-center justify-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></div>
                        Mohon maaf atas ketidaknyamanan ini
                    </div>
                </div>
            </div>
        );
    }

    return <>{children}</>;
}

"use client";
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, ZoomIn, Play, Pause, Maximize2 } from 'lucide-react';

interface MediaViewerProps {
    src: string;
    type: 'image' | 'video';
    alt?: string;
    className?: string;
}

export function MediaViewer({ src, type, alt = '', className = '' }: MediaViewerProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [isPlaying, setIsPlaying] = useState(true);

    if (type === 'image') {
        return (
            <>
                <div className={`relative inline-block cursor-zoom-in group ${className}`} onClick={() => setIsOpen(true)}>
                    <img
                        src={src}
                        alt={alt}
                        className="max-w-full h-auto rounded-lg border border-slate-200 hover:opacity-90 transition-opacity"
                    />
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/20 rounded-lg">
                        <ZoomIn className="w-6 h-6 text-white drop-shadow-lg" />
                    </div>
                </div>

                <AnimatePresence>
                    {isOpen && (
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="fixed inset-0 z-[200] bg-black/90 flex items-center justify-center p-4"
                            onClick={() => setIsOpen(false)}
                        >
                            <button
                                className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors"
                                onClick={() => setIsOpen(false)}
                            >
                                <X size={24} />
                            </button>
                            <motion.img
                                initial={{ scale: 0.9, opacity: 0 }}
                                animate={{ scale: 1, opacity: 1 }}
                                exit={{ scale: 0.9, opacity: 0 }}
                                src={src}
                                alt={alt}
                                className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
                                onClick={(e) => e.stopPropagation()}
                            />
                        </motion.div>
                    )}
                </AnimatePresence>
            </>
        );
    }

    // Video
    return (
        <>
            <div className={`relative inline-block group ${className}`}>
                <video
                    src={src}
                    controls
                    className="max-w-full h-auto rounded-lg border border-slate-200"
                    onPlay={() => setIsPlaying(true)}
                    onPause={() => setIsPlaying(false)}
                />
                <button
                    className="absolute top-2 right-2 p-1.5 bg-black/50 hover:bg-black/70 rounded-lg text-white transition-colors"
                    onClick={() => setIsOpen(true)}
                >
                    <Maximize2 size={16} />
                </button>
            </div>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[200] bg-black flex items-center justify-center p-4"
                        onClick={() => setIsOpen(false)}
                    >
                        <button
                            className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors z-10"
                            onClick={() => setIsOpen(false)}
                        >
                            <X size={24} />
                        </button>
                        <video
                            src={src}
                            controls
                            autoPlay
                            className="max-w-full max-h-full object-contain"
                            onClick={(e) => e.stopPropagation()}
                        />
                    </motion.div>
                )}
            </AnimatePresence>
        </>
    );
}

// Helper to render media from HTML content
export function parseMediaContent(html: string): React.ReactNode[] {
    const result: React.ReactNode[] = [];

    // Parse images
    const imgRegex = /<img[^>]+src=["']([^"']+)["'][^>]*alt=["']([^"']*)["'][^>]*>/gi;
    let imgMatch;
    const processedHtml = html.replace(imgRegex, (match, src, alt) => {
        result.push(
            <MediaViewer key={`img-${result.length}`} src={src} alt={alt} type="image" className="my-2" />
        );
        return '';
    });

    // Parse videos
    const videoRegex = /<video[^>]+src=["']([^"']+)["'][^>]*>/gi;
    const processedHtml2 = processedHtml.replace(videoRegex, (match, src) => {
        result.push(
            <MediaViewer key={`video-${result.length}`} src={src} type="video" className="my-2" />
        );
        return '';
    });

    // Return parsed content plus remaining HTML
    if (processedHtml2.trim()) {
        result.push(<span key="text" dangerouslySetInnerHTML={{ __html: processedHtml2 }} />);
    }

    return result;
}

"use client";
import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { motion } from 'framer-motion';
import {
    LayoutDashboard,
    ClipboardCheck,
    Activity,
    Settings,
    BookOpen,
    Users,
    BarChart3,
    Calendar,
    Bell
} from 'lucide-react';

const MobileNav = () => {
    const pathname = usePathname();

    const getRole = () => {
        if (pathname.includes('/admin')) return 'Admin';
        if (pathname.includes('/proktor')) return 'Proktor';
        if (pathname.includes('/guru')) return 'Guru';
        if (pathname.includes('/pengawas')) return 'Pengawas';
        if (pathname.includes('/siswa')) return 'Siswa';
        return 'User';
    };

    const role = getRole();

    // Setiap href di bawah menunjuk halaman yang benar-benar ada.
    //
    // Sebelumnya menu ini diwarisi dari produk asalnya dan separuh tautannya
    // mati — yang terburuk /dashboard/settings, yang muncul di SETIAP peran,
    // sehingga tombol "Set" tidak pernah berfungsi untuk siapa pun.
    const navConfig: Record<string, any[]> = {
        'Admin': [
            { icon: LayoutDashboard, label: 'Dash', href: '/dashboard/admin' },
            { icon: ClipboardCheck, label: 'Ujian', href: '/dashboard/admin/exams' },
            { icon: Activity, label: 'Monitor', href: '/dashboard/admin/monitoring' },
            { icon: BookOpen, label: 'Bank', href: '/dashboard/admin/questions' },
            { icon: Users, label: 'Kelas', href: '/dashboard/admin/classes' },
        ],
        'Proktor': [
            { icon: LayoutDashboard, label: 'Dash', href: '/dashboard/proktor' },
            { icon: ClipboardCheck, label: 'Ujian', href: '/dashboard/proktor/exams' },
            { icon: Activity, label: 'Monitor', href: '/dashboard/proktor/monitoring' },
            { icon: BookOpen, label: 'Bank', href: '/dashboard/proktor/questions' },
            { icon: Users, label: 'Kelas', href: '/dashboard/proktor/classes' },
        ],
        'Guru': [
            { icon: LayoutDashboard, label: 'Dash', href: '/dashboard/guru' },
            { icon: ClipboardCheck, label: 'Ujian', href: '/dashboard/guru/exams' },
            { icon: Activity, label: 'Monitor', href: '/dashboard/guru/monitoring' },
            { icon: BarChart3, label: 'Nilai', href: '/dashboard/guru/grading' },
            { icon: BookOpen, label: 'Bank', href: '/dashboard/guru/questions' },
        ],
        'Pengawas': [
            { icon: LayoutDashboard, label: 'Dash', href: '/dashboard/pengawas' },
            { icon: Activity, label: 'Monitor', href: '/dashboard/pengawas/monitoring' },
            { icon: Bell, label: 'Notif', href: '/dashboard/notifications' },
