            <div>
              <p className="font-bold text-amber-800 text-sm">Soal Diperbarui</p>
              <p className="text-amber-700 text-xs mt-0.5">Soal ini baru saja diperbarui oleh guru. Silakan baca ulang sebelum menjawab.</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

