"use client";
/**
 * AnswerOptionCard — Elegant MCQ option editor with insert toolbar.
 */
import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Check, Trash2, Image as ImageIcon, Plus, Minus, Upload } from 'lucide-react';
import { RichInput } from './RichInput';
import { MathToolbar } from '../MathToolbar';
import { renderLatex, sanitizeLatex } from '../math-utils';
import { uploadToHosting } from '@/lib/uploader';

// ─── Equation Dialog (with MathToolbar) ────────────────────────────────────

interface EquationDialogProps {
    isOpen: boolean;
    onClose: () => void;
    onInsert: (latex: string) => void;
}

export function EquationDialog({ isOpen, onClose, onInsert }: EquationDialogProps) {
    const [input, setInput] = useState('');
    const [previewHtml, setPreviewHtml] = useState('');
    const [editorMode, setEditorMode] = useState<'visual' | 'latex'>('visual');

    useEffect(() => {
        if (input.trim()) {
            const r = renderLatex(sanitizeLatex(input), false);
            setPreviewHtml(r.error ? '' : r.html);
        } else {
            setPreviewHtml('');
        }
    }, [input]);

    const handleInsert = () => {
        if (input.trim()) {
            onInsert(input.trim());
            setInput('');
            onClose();
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-black/60 p-4" onClick={onClose}>
            <div className="bg-white rounded-lg shadow-xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
                {/* Title */}
                <div className="px-6 pt-5 pb-0 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-amber-100 rounded-lg flex items-center justify-center">
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#d97706" strokeWidth="2.5">
                                <path d="M4 4h6v6H4z"/><path d="M14 4h6v6h-6z"/><path d="M4 14h6v6H4z"/><path d="M17 14v3h3"/>
                            </svg>
                        </div>
                        <div>
                            <h3 className="text-base font-semibold text-slate-800">Sisipkan Rumus</h3>
                            <p className="text-[10px] text-slate-400">Klik template atau ketik langsung</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
                        </svg>
                    </button>
                </div>

                {/* Editor Mode Toggle */}
                <div className="px-6 pt-4">
                    <div className="flex gap-2 mb-2">
                        <button onClick={() => setEditorMode('visual')} className={`flex-1 py-1.5 rounded-lg text-xs font-semibold border transition-all ${editorMode === 'visual' ? 'bg-[#030C4D] text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`}>Visual (Word)</button>
                        <button onClick={() => setEditorMode('latex')} className={`flex-1 py-1.5 rounded-lg text-xs font-semibold border transition-all ${editorMode === 'latex' ? 'bg-[#030C4D] text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`}>Kode LaTeX</button>
                    </div>
                </div>

                {/* Input */}
                <div className="px-6 pt-2">
                    {editorMode === 'visual' ? (
                        <div className="w-full min-h-[80px] p-2.5 border border-slate-200 rounded-lg outline-none focus-within:border-slate-400 bg-white">
                            <style>{`
                              math-field::part(menu-toggle) { display: none !important; }
                              math-field::part(virtual-keyboard-toggle) { display: none !important; }
                              math-field {
                                --placeholder-color: #cbd5e1;
                                --placeholder-opacity: 0.6;
                              }
                            `}</style>
                            {/* @ts-ignore */}
                            <math-field 
                                id="mf-option-editor"
                                style={{ width: '100%', minHeight: '80px', fontSize: '1.25rem', padding: '12px', outline: 'none' }}
                                onInput={(e: any) => {
                                    let val = e.target.value;
                                    const originalVal = val;
                                    // Force placeholders for extensible accents that natively drop them when empty
                                    val = val.replace(/\\overrightarrow\{\}/g, '\\overrightarrow{\\placeholder{}}')
                                             .replace(/\\widehat\{\}/g, '\\widehat{\\placeholder{}}')
                                             .replace(/\\overline\{\}/g, '\\overline{\\placeholder{}}')
                                             .replace(/\\wideparen\{\}/g, '\\wideparen{\\placeholder{}}')
                                             .replace(/\\underline\{\}/g, '\\underline{\\placeholder{}}');
                                    
                                    if (val !== originalVal) {
                                      e.target.value = val;
                                      e.target.executeCommand(['moveToNextPlaceholder']);
                                    }
                                    setInput(val);
                                }}
                                ref={(el: any) => {
                                  if (el && el.value !== input) {
                                    el.value = input;
                                  }
                                }}
                            >
                            {/* @ts-ignore */}
                            </math-field>
                        </div>
                    ) : (
                        <textarea
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Ketik rumus LaTeX, contoh: \frac{a}{b}"
                            rows={3}
                            className="w-full p-4 bg-slate-50 border border-slate-200 rounded-lg text-sm font-mono text-slate-700 outline-none focus:border-amber-400 focus:ring-2 focus:ring-amber-100 transition-all resize-none"
                            autoFocus
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); handleInsert(); }
                            }}
                        />
                    )}
                </div>

                {/* Live Preview for LaTeX mode */}
                {editorMode === 'latex' && previewHtml && (
                    <div className="px-6 pt-2">
                        <p className="text-[10px] font-medium text-slate-400 mb-1">Pratinjau:</p>
                        <div className="bg-slate-50 rounded-lg px-4 py-3 text-center">
                            <span dangerouslySetInnerHTML={{ __html: previewHtml }} />
                        </div>
                    </div>
                )}

                {/* MathToolbar */}
                <div className="px-6 pt-3 pb-2">
                    <p className="text-[11px] font-medium text-slate-400 mb-2">Template</p>
                    <MathToolbar
                        onInsert={(template) => {
                            if (editorMode === 'visual') {
                                const mf = document.getElementById('mf-option-editor') as any;
                                if (mf) {
                                    let liveLatex = template.replace(/\?/g, '#?');
                                    mf.executeCommand(['insert', liveLatex]);
                                    setInput(mf.value);
                                }
                            } else {
                                const plainLatex = template.replace(/\?/g, ' ');
                                const ta = document.querySelector('textarea[placeholder="Ketik rumus LaTeX, contoh: \\frac{a}{b}"]') as HTMLTextAreaElement;
                                if (ta) {
                                    const pos = ta.selectionStart;
                                    const newVal = input.slice(0, pos) + plainLatex + input.slice(pos);
                                    setInput(newVal);
                                    const firstPlaceholderIdx = plainLatex.indexOf(' ');
                                    const jumpPos = firstPlaceholderIdx !== -1 ? pos + firstPlaceholderIdx : pos + plainLatex.length;
                                    setTimeout(() => { ta.selectionStart = ta.selectionEnd = jumpPos; ta.focus(); }, 0);
                                } else {
                                    setInput(prev => prev + plainLatex);
                                }
                            }
                        }}
                        visible={true}
                        className="bg-slate-50 rounded-lg p-3 max-h-48 overflow-y-auto"
                    />
                </div>

                {/* Footer */}
                <div className="px-6 py-4 flex justify-end gap-2 border-t border-slate-100 mt-2">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-500 hover:text-slate-700 rounded-lg transition-colors">
                        Batal
                    </button>
                    <button onClick={handleInsert} disabled={!input.trim()}
                        className="px-5 py-2 text-sm font-semibold bg-[#030C4D] text-white rounded-lg hover:bg-[#020735] disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-sm">
                        Sisipkan
                    </button>
                </div>
            </div>
        </div>
    );
}

// ─── Table Dialog ─────────────────────────────────────────────────────────────

interface TableDialogProps {
    isOpen: boolean;
    onClose: () => void;
    onInsert: (rows: number, cols: number) => void;
}

export function TableDialog({ isOpen, onClose, onInsert }: TableDialogProps) {
    const [rows, setRows] = useState(2);
    const [cols, setCols] = useState(2);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-black/60 p-4" onClick={onClose}>
            <div className="bg-white rounded-lg shadow-xl w-full max-w-sm overflow-hidden" onClick={e => e.stopPropagation()}>
                {/* Title */}
                <div className="px-6 pt-5 pb-0 flex items-center justify-between">
                    <h3 className="text-base font-semibold text-slate-800">Sisipkan Tabel</h3>
                    <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
                        </svg>
                    </button>
                </div>

                {/* Preview */}
                <div className="px-6 pt-4">
                    <div className="bg-slate-50 rounded-lg p-4 flex items-center justify-center">
                        <table style={{ borderCollapse: 'collapse' }}>
                            <tbody>
                                {Array.from({ length: Math.min(rows, 4) }).map((_, r) => (
                                    <tr key={r}>
                                        {Array.from({ length: Math.min(cols, 5) }).map((_, c) => (
                                            <td key={c} style={{ border: '1px solid #e2e8f0', padding: '8px 12px' }}>
                                                <span className="text-[10px] text-slate-400">{r + 1},{c + 1}</span>
                                            </td>
                                        ))}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Controls - Side by side */}
                <div className="px-6 pt-4 pb-2">
                    <div className="flex gap-4">
                        {/* Rows */}
                        <div className="flex-1">
                            <label className="text-[11px] font-medium text-slate-400 block mb-2">Baris</label>
                            <div className="flex items-center gap-2">
                                <button onClick={() => setRows(Math.max(1, rows - 1))} className="w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 flex items-center justify-center text-slate-600 transition-colors">
                                    <Minus size={14} />
                                </button>
                                <div className="flex-1 text-center text-lg font-semibold text-slate-800">{rows}</div>
                                <button onClick={() => setRows(Math.min(10, rows + 1))} className="w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 flex items-center justify-center text-slate-600 transition-colors">
                                    <Plus size={14} />
                                </button>
                            </div>
                        </div>

                        {/* Columns */}
                        <div className="flex-1">
                            <label className="text-[11px] font-medium text-slate-400 block mb-2">Kolom</label>
                            <div className="flex items-center gap-2">
                                <button onClick={() => setCols(Math.max(1, cols - 1))} className="w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 flex items-center justify-center text-slate-600 transition-colors">
                                    <Minus size={14} />
                                </button>
                                <div className="flex-1 text-center text-lg font-semibold text-slate-800">{cols}</div>
                                <button onClick={() => setCols(Math.min(10, cols + 1))} className="w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 flex items-center justify-center text-slate-600 transition-colors">
                                    <Plus size={14} />
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="px-6 py-4 flex justify-end gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-500 hover:text-slate-700 rounded-lg transition-colors">
                        Batal
                    </button>
                    <button onClick={() => { onInsert(rows, cols); onClose(); }}
                        className="px-5 py-2 text-sm font-semibold bg-primary text-white rounded-lg hover:bg-primary-hover transition-all">
                        Sisipkan
                    </button>
                </div>
            </div>
        </div>
    );
}

// ─── BulkAddModal ─────────────────────────────────────────────────────────────

interface BulkAddModalProps {
    isOpen: boolean;
    onClose: () => void;
    onAdd: (lines: string[]) => void;
    title?: string;
    placeholder?: string;
}

export function BulkAddModal({ isOpen, onClose, onAdd, title = "Tambah Banyak Opsi", placeholder = "Ketik atau tempel beberapa opsi di sini...\nGunakan baris baru untuk memisahkan opsi." }: BulkAddModalProps) {
    const [text, setText] = useState('');

    if (!isOpen) return null;

    const handleAdd = () => {
        const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);
        if (lines.length > 0) {
            onAdd(lines);
            setText('');
            onClose();
        }
    };

    return (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-black/60 p-4" onClick={onClose}>
            <div className="bg-white rounded-lg shadow-xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
                <div className="px-6 pt-5 pb-0 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center text-blue-600">
                            <Plus size={16} strokeWidth={3} />
                        </div>
                        <h3 className="text-base font-semibold text-slate-800">{title}</h3>
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                    </button>
                </div>
                <div className="p-6">
                    <textarea
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder={placeholder}
                        rows={8}
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-lg text-sm text-slate-700 outline-none focus:border-blue-400 focus:ring-2 focus:ring-blue-100 transition-all resize-none font-medium"
                        autoFocus
                    />
                    <div className="mt-4 flex justify-end gap-2">
                        <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-500 hover:bg-slate-100 rounded-lg transition-colors">
                            Batal
                        </button>
                        <button onClick={handleAdd} disabled={!text.trim()}
                            className="px-6 py-2 text-sm font-bold bg-slate-800 text-white rounded-lg hover:bg-slate-700 disabled:opacity-40 transition-all shadow-lg shadow-slate-800/10">
                            Tambah {text.split('\n').filter(l => l.trim()).length || ''} Opsi
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

// ─── AnswerOptionCard ──────────────────────────────────────────────────────────

interface AnswerOptionCardProps {
    label: string;
    value: string;
    isCorrect?: boolean;
    isMultiSelect?: boolean;
    onChange: (text: string) => void;
    onCorrectToggle?: () => void;
    onDelete?: () => void;
    placeholder?: string;
    canDelete?: boolean;
    className?: string;
    hideCorrectToggle?: boolean;
    hideRichTools?: boolean;
}

export const AnswerOptionCard = React.memo(({
    label,
    value,
    isCorrect = false,
    isMultiSelect = false,
    onChange,
    onCorrectToggle = () => {},
    onDelete,
    placeholder = 'Ketik jawaban...',
    canDelete = true,
    className = '',
    hideCorrectToggle = false,
    hideRichTools = false,
}: AnswerOptionCardProps) => {
    const [isFocused, setIsFocused] = useState(false);
    const [showEquation, setShowEquation] = useState(false);
    const [showTable, setShowTable] = useState(false);
    const [imageUploading, setImageUploading] = useState(false);
    const [showToolsMenu, setShowToolsMenu] = useState(false);
    const inputRef = useRef<HTMLTextAreaElement>(null);

    // Menutup menu saat klik di luar
    useEffect(() => {
        const handleClickOutside = () => setShowToolsMenu(false);
        if (showToolsMenu) {
            document.addEventListener('click', handleClickOutside);
            return () => document.removeEventListener('click', handleClickOutside);
        }
    }, [showToolsMenu]);

    const insertAtCursor = (text: string) => {
        const ta = inputRef.current;
        if (!ta) return;
        const start = ta.selectionStart;
        const end = ta.selectionEnd;
        const newValue = value.slice(0, start) + text + value.slice(end);
        onChange(newValue);
        // Set cursor position after insert
        setTimeout(() => {
            ta.selectionStart = ta.selectionEnd = start + text.length;
            ta.focus();
        }, 0);
    };

    const handleImageUpload = async (file: File) => {
        setImageUploading(true);
        try {
            const res = await uploadToHosting(file, 'questions');
            const url = res.success ? res.url : '';
            if (url) {
                insertAtCursor(`\n<img src="${url}" alt="${file.name}" style="max-width:100%;height:auto;border-radius:8px;display:block;margin:4px 0;" />\n`);
            }
        } catch (err) {
            console.error('Image upload failed:', err);
        } finally {
            setImageUploading(false);
        }
    };

    const handlePaste = useCallback(async (e: React.ClipboardEvent) => {
        const items = e.clipboardData?.items;
        if (!items) return;
        for (const item of Array.from(items)) {
            if (item.type.startsWith('image/')) {
                e.preventDefault();
                const file = item.getAsFile();
                if (file) {
                    setImageUploading(true);
                    try {
                        const res = await uploadToHosting(file, 'questions');
                        const url = res.success ? res.url : '';
                        if (url) {
                            insertAtCursor(`\n<img src="${url}" alt="Pasted image" style="max-width:100%;height:auto;border-radius:8px;display:block;margin:4px 0;" />\n`);
                        }
                    } catch (err) {
                        console.error('Paste image upload failed:', err);
                    } finally {
                        setImageUploading(false);
                    }
                }
                break;
            }
        }
    }, [insertAtCursor]);

    const handleInsertEquation = (latex: string) => {
        insertAtCursor(`$${latex}$`);
    };

    const handleInsertTable = (rows: number, cols: number) => {
        let table = '\n';
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                table += (c > 0 ? '\t' : '') + `Cell ${r + 1},${c + 1}`;
            }
            table += '\n';
        }
        insertAtCursor(table);
    };

    return (
        <div className={`group relative ${className}`} suppressHydrationWarning>
            <div className={`flex items-start sm:items-center gap-1.5 sm:gap-2`}>
                {/* Letter Badge */}
                <div className={`
                    mt-1 sm:mt-0 shrink-0 flex items-center justify-center
                    w-8 h-8 rounded-lg
                    text-sm font-black select-none
                    transition-all duration-200
                    ${isCorrect
                        ? 'bg-emerald-500 text-white'
                        : isFocused
                            ? 'bg-slate-800 text-white'
                            : 'bg-slate-100 text-slate-500'
                    }
                `}>
                    {label}
                </div>

                {/* Input Card */}
                <div className={`
                    flex-1 flex flex-col sm:flex-row items-stretch sm:items-center
                    rounded-lg border-2 transition-all duration-200
                    ${isFocused
                        ? 'border-slate-800 bg-white shadow-sm'
                        : isCorrect
                            ? 'border-emerald-300 bg-emerald-50/50'
                            : 'border-slate-200 bg-white hover:border-slate-300'
                    }
                `}>
                    {/* Text Input Wrapper */}
                    <div className="flex flex-1 min-w-0">
                        {/* Text Input */}
                        <div className="flex-1 min-w-0">
                            <RichInput
                            inputRef={inputRef}
                            value={value}
                            onChange={onChange}
                            onFocus={() => setIsFocused(true)}
                            onBlur={() => setIsFocused(false)}
                            onPaste={handlePaste}
                            placeholder={placeholder}
                        />
                        </div>
                    </div>

                    {/* Toolbar - Inside card */}
                    {!hideRichTools && (
                    <div className="relative shrink-0 px-2 py-1.5 sm:py-2 flex items-center justify-end sm:justify-start">
                        {/* Toggle Button */}
                        <button
                            type="button"
                            onClick={(e) => { e.stopPropagation(); setShowToolsMenu(!showToolsMenu); }}
                            className={`w-7 h-7 flex items-center justify-center rounded-md transition-all ${showToolsMenu ? 'bg-slate-800 text-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}
                            title="Sisipkan media / rumus"
                        >
                            <Plus size={14} className={`transition-transform duration-200 ${showToolsMenu ? 'rotate-45' : ''}`} />
                        </button>

                        {/* Dropdown Menu */}
                        {showToolsMenu && (
                            <div 
                                className="absolute right-2 sm:right-auto sm:left-2 top-full mt-1 p-1 bg-white border border-slate-200 shadow-xl rounded-lg flex items-center gap-1 z-50 animate-in fade-in slide-in-from-top-2"
                                onClick={(e) => e.stopPropagation()}
                            >
                                {/* Image Upload */}
                                <label className={`
                                    w-8 h-8 flex items-center justify-center rounded-md cursor-pointer transition-all
                                    ${imageUploading ? 'opacity-50 cursor-not-allowed' : 'text-slate-500 hover:text-blue-600 hover:bg-blue-50'}
                                `} title="Unggah Gambar">
                                    {imageUploading ? (
                                        <span className="animate-spin text-sm">⟳</span>
                                    ) : (
                                        <ImageIcon size={14} />
                                    )}
                                    <input type="file" accept="image/*" className="hidden" disabled={imageUploading}
                                        onChange={(e) => { const f = e.target.files?.[0]; if (f) { handleImageUpload(f); setShowToolsMenu(false); } e.target.value = ''; }} />
                                </label>

                                {/* Equation */}
                                <button type="button"
                                    onClick={(e) => { setShowEquation(true); setShowToolsMenu(false); }}
                                    className="w-8 h-8 flex items-center justify-center rounded-md text-slate-500 hover:text-amber-600 hover:bg-amber-50 transition-all"
                                    title="Sisipkan Rumus">
                                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                                        <path d="M4 4h6v6H4z"/><path d="M14 4h6v6h-6z"/><path d="M4 14h6v6H4z"/><path d="M17 14v3h3"/>
                                    </svg>
                                </button>

                                {/* Table */}
                                <button type="button"
                                    onClick={(e) => { setShowTable(true); setShowToolsMenu(false); }}
                                    className="w-8 h-8 flex items-center justify-center rounded-md text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 transition-all"
                                    title="Sisipkan Tabel">
                                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                                        <rect x="3" y="3" width="18" height="18" rx="2"/>
                                        <line x1="3" y1="9" x2="21" y2="9"/>
                                        <line x1="9" y1="3" x2="9" y2="21"/>
                                    </svg>
                                </button>
                            </div>
                        )}
                    </div>
                    )}
                </div>

                {/* Correct toggle */}
                {!hideCorrectToggle && (
                    <button
                        type="button"
                        onClick={onCorrectToggle}
                        title={isMultiSelect ? 'Pilih sebagai jawaban benar' : 'Tetapkan sebagai jawaban benar'}
                        className={`
                            mt-1 sm:mt-0 shrink-0 flex items-center justify-center
                            w-8 h-8 rounded-lg border-2
                            transition-all duration-200
                            ${isCorrect
                                ? 'bg-emerald-500 border-emerald-500 text-white'
                                : 'border-slate-200 text-transparent group-hover:border-emerald-400 group-hover:text-emerald-500'
                            }
                        `}
                    >
                        <Check size={14} strokeWidth={3} />
                    </button>
                )}

                {/* Delete */}
                {canDelete && onDelete && (
                    <button
                        type="button"
                        onClick={onDelete}
                        className={`
                            mt-1 sm:mt-0 shrink-0 flex items-center justify-center
                            w-8 h-8 rounded-lg
                            transition-all duration-200
                            text-slate-300 hover:text-rose-500 hover:bg-rose-50
                            ${isFocused || isCorrect ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}
                        `}
                        title="Hapus Opsi"
                    >
                        <Trash2 size={14} />
                    </button>
                )}
            </div>

            {/* Dialogs */}
            <EquationDialog
                isOpen={showEquation}
                onClose={() => setShowEquation(false)}
                onInsert={handleInsertEquation}
            />
            <TableDialog
                isOpen={showTable}
                onClose={() => setShowTable(false)}
                onInsert={handleInsertTable}
            />
        </div>
    );
});

AnswerOptionCard.displayName = 'AnswerOptionCard';

// ─── OptionList ────────────────────────────────────────────────────────────────

interface OptionListProps {
    children: React.ReactNode;
    onAdd?: () => void;
    onBulkAdd?: (lines: string[]) => void;
    addLabel?: string;
    maxItems?: number;
    className?: string;
}

export const OptionList = React.memo(({
    children,
    onAdd,
    onBulkAdd,
    addLabel = 'Tambah Opsi',
    maxItems,
    className = '',
}: OptionListProps) => {
    const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);

    return (
        <div className={`space-y-2 ${className}`}>
            {children}
            <div className="flex gap-2">
                {onAdd && (
                    <button type="button" onClick={onAdd} disabled={!!maxItems && React.Children.count(children) >= maxItems}
                        className={`
                            flex-1 flex items-center justify-center gap-2 py-2.5
                            text-xs font-semibold rounded-lg border-2 border-dashed
                            transition-all duration-200
                            ${(!!maxItems && React.Children.count(children) >= maxItems)
                                ? 'opacity-40 cursor-not-allowed border-slate-200 text-slate-400'
                                : 'border-slate-200 text-slate-400 hover:border-slate-400 hover:text-slate-600 hover:bg-slate-50'
                            }
                        `}>
                        <Plus size={14} />
                        {addLabel}
                    </button>
                )}
                {onBulkAdd && (
                    <button type="button" onClick={() => setIsBulkModalOpen(true)}
                        className="px-4 flex items-center justify-center gap-2 py-2.5 text-xs font-semibold rounded-lg border-2 border-slate-200 text-slate-400 hover:border-slate-400 hover:text-slate-600 hover:bg-slate-50 transition-all">
                        <Upload size={14} />
                        Banyak
                    </button>
                )}
            </div>

            {onBulkAdd && (
                <BulkAddModal
                    isOpen={isBulkModalOpen}
                    onClose={() => setIsBulkModalOpen(false)}
                    onAdd={onBulkAdd}
                    title={`Tambah ${addLabel} Sekaligus`}
                />
            )}
        </div>
    );
});

OptionList.displayName = 'OptionList';

"use client";
/**
 * CategorizationForm — Kategorisasi
 * Clean table-style editor for assigning items to categories.
 */
import React, { useState, useRef, useEffect } from 'react';
import { Trash2, Plus, Image as ImageIcon, Upload } from 'lucide-react';
import { BaseOption } from '../schema';
import { RichInput } from './RichInput';
import { EquationDialog, TableDialog, BulkAddModal, OptionList } from './AnswerOptionCard';
import { uploadToHosting } from '@/lib/uploader';
import { motion, AnimatePresence } from 'framer-motion';

interface CategorizationFormProps {
  options: BaseOption[];
  categories: string[];
  onAddItem: () => void;
  onBulkAdd?: (texts: string[]) => void;
  onInsertItem: (index: number) => void;
  onRemoveItem: (index: number) => void;
  onUpdateItem: (index: number, text: string) => void;
  onSetCategories: (categories: string[]) => void;
  onSetItemCategory: (optIndex: number, categories: string[]) => void;
}

const CATEGORY_COLORS = [
  { bg: 'bg-violet-500', light: 'bg-violet-100', border: 'border-violet-200', text: 'text-violet-600', ring: 'ring-violet-400' },
  { bg: 'bg-blue-500', light: 'bg-blue-100', border: 'border-blue-200', text: 'text-blue-600', ring: 'ring-blue-400' },
  { bg: 'bg-teal-500', light: 'bg-teal-100', border: 'border-teal-200', text: 'text-teal-600', ring: 'ring-teal-400' },
  { bg: 'bg-emerald-500', light: 'bg-emerald-100', border: 'border-emerald-200', text: 'text-emerald-600', ring: 'ring-emerald-400' },
  { bg: 'bg-amber-500', light: 'bg-amber-100', border: 'border-amber-200', text: 'text-amber-600', ring: 'ring-amber-400' },
  { bg: 'bg-rose-500', light: 'bg-rose-100', border: 'border-rose-200', text: 'text-rose-600', ring: 'ring-rose-400' },
  { bg: 'bg-indigo-500', light: 'bg-indigo-100', border: 'border-indigo-200', text: 'text-indigo-600', ring: 'ring-indigo-400' },
  { bg: 'bg-cyan-500', light: 'bg-cyan-100', border: 'border-cyan-200', text: 'text-cyan-600', ring: 'ring-cyan-400' },
];// Category edit modal
function CategoryEditModal({
  categories,
  onSave,
  onClose,
}: {
  categories: string[];
  onSave: (cats: string[]) => void;
  onClose: () => void;
}) {
  const [draft, setDraft] = useState(categories.join(', '));

  return (
    <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-black/60" onClick={onClose}>
      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 10 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 10 }}
        onClick={(e: React.MouseEvent) => e.stopPropagation()}
        className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden border border-slate-200"
      >
        <div className="px-6 py-4 bg-slate-50/50 border-b border-slate-100 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-primary flex items-center justify-center text-white shadow-lg shadow-primary/20">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                <path d="M4 6h16M4 12h16M4 18h10"/>
              </svg>
            </div>
            <div>
              <h3 className="text-[15px] font-black text-primary uppercase tracking-tight">Edit Kategori</h3>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Pisahkan dengan koma</p>
            </div>
          </div>
          <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-slate-200 text-slate-400 transition-colors">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
              <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
          </button>
        </div>
        <div className="p-6 space-y-4">
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Kategori 1, Kategori 2, Kategori 3..."
            rows={3}
            className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-lg text-sm text-slate-700 outline-none focus:border-primary/30 focus:bg-white focus:ring-4 focus:ring-primary/5 transition-all resize-none"
          />
          {draft.trim() && (
            <div className="flex flex-wrap gap-1.5 pt-2">
              {draft.split(',').map(s => s.trim()).filter(Boolean).map((cat, idx) => {
                const c = CATEGORY_COLORS[idx % CATEGORY_COLORS.length];
                return (
                  <span key={idx} className={`inline-flex items-center gap-1 px-3 py-1.5 rounded-full text-[11px] font-bold ${c.light} ${c.text} border ${c.border} shadow-sm`}>
                    {cat}
                  </span>
                );
              })}
            </div>
          )}
        </div>
        <div className="px-6 py-4 border-t border-slate-100 flex justify-end gap-3 bg-slate-50/50">
          <button onClick={onClose} className="px-5 py-2.5 text-xs font-bold text-slate-500 hover:text-primary transition-colors rounded-lg hover:bg-primary/5">
            Batal
          </button>
          <button
            onClick={() => {
              onSave(draft.split(',').map(s => s.trim()).filter(Boolean));
              onClose();
            }}
            className="px-6 py-2.5 text-xs font-black bg-primary text-white rounded-lg hover:bg-primary-hover shadow-lg shadow-primary/20 transition-all transform hover:-translate-y-0.5 active:translate-y-0"
          >
            Simpan Kategori
          </button>
        </div>
      </motion.div>
    </div>
  );
}

export const CategorizationForm = React.memo(({
  options,
  categories,
  onAddItem,
  onBulkAdd,
  onInsertItem,
  onRemoveItem,
  onUpdateItem,
  onSetCategories,
  onSetItemCategory,
}: CategorizationFormProps) => {
  const [showCategoryEdit, setShowCategoryEdit] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);

  return (
    <div className="space-y-4">
      {/* Category header bar */}
      <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-lg border border-slate-100 overflow-x-auto scrollbar-hide">
        <div className="flex items-center gap-2 shrink-0 pl-1">
          <div className="w-7 h-7 rounded-lg bg-primary text-white flex items-center justify-center shadow-lg shadow-primary/10">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
              <path d="M4 6h16M4 12h16M4 18h10"/>
            </svg>
          </div>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] whitespace-nowrap">Kategori</span>
        </div>

        {categories.length > 0 ? (
          <div className="flex items-center gap-2 flex-1 min-w-0">
            {categories.map((cat, idx) => {
              const c = CATEGORY_COLORS[idx % CATEGORY_COLORS.length];
              return (
                <span
                  key={cat}
                  className={`inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-[11px] font-black ${c.light} ${c.text} border ${c.border} shrink-0 shadow-sm`}
                >
                  {cat}
                </span>
              );
            })}
            <button
              onClick={() => setShowCategoryEdit(true)}
              className="shrink-0 w-8 h-8 flex items-center justify-center rounded-lg bg-white hover:bg-primary hover:text-white text-slate-400 transition-all border-2 border-dashed border-slate-200 hover:border-primary/50 shadow-sm"
              title="Edit kategori"
            >
              <Plus size={14} />
            </button>
          </div>
        ) : (
          <button
            onClick={() => setShowCategoryEdit(true)}
            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-primary text-white text-[11px] font-black uppercase tracking-wider shadow-lg shadow-primary/20 hover:bg-primary-hover transition-all"
          >
            <Plus size={14} />
            Tambah Kategori
          </button>
        )}
      </div>

      {/* Table — only show if categories exist */}
      {categories.length > 0 && (
        <div className="overflow-x-auto -mx-1 scrollbar-thin scrollbar-thumb-slate-200">
          <table className="w-full min-w-[700px] border-separate border-spacing-y-1">
            {/* Header row */}
            <thead>
              <tr>
                <th className="w-[50%] min-w-[350px] px-1">
                  <div className="px-3 text-left">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Item Pertanyaan</span>
                  </div>
                </th>
                {categories.map((cat, catIdx) => {
                  const c = CATEGORY_COLORS[catIdx % CATEGORY_COLORS.length];
                  return (
                    <th key={cat} className="w-20 min-w-[80px] px-1">
                      <div className={`rounded-full ${c.bg} text-white px-3 py-1.5 text-center shadow-sm`}>
                        <span className="text-[9px] font-black uppercase tracking-widest truncate block">{cat}</span>
                      </div>
                    </th>
                  );
                })}
                <th className="w-10 px-1"></th>
              </tr>
            </thead>
            <tbody className="before:block before:h-1">
              {options.map((opt, idx) => {
                const assignedCats = opt.category_names || [];
                return (
                  <React.Fragment key={opt.id || idx}>
                    {/* Insert Between - Categorization */}
                    {idx > 0 && (
                      <tr className="h-2 group/insert">
                        <td colSpan={categories.length + 2} className="relative p-0">
                          <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 flex items-center justify-center opacity-0 group-hover/insert:opacity-100 transition-opacity z-10">
                            <button
                              type="button"
                              onClick={() => onInsertItem(idx)}
                              className="bg-white border-2 border-slate-200 text-slate-400 hover:text-primary hover:border-primary w-6 h-6 rounded-full flex items-center justify-center shadow-sm transition-all"
                              title="Sisipkan Item di sini"
                            >
                              <Plus size={12} strokeWidth={3} />
                            </button>
                          </div>
                          <div className="absolute inset-x-10 top-1/2 border-t border-dashed border-slate-100 opacity-0 group-hover/insert:opacity-100 transition-opacity" />
                        </td>
                      </tr>
                    )}
                    <tr className="group">
                      <td className="px-1 py-1">
                        <CategorizationItemRow
                          index={idx + 1}
                          value={opt.text}
                          onChange={(text) => onUpdateItem(idx, text)}
                        />
                      </td>
                      {categories.map((cat, catIdx) => {
                        const c = CATEGORY_COLORS[catIdx % CATEGORY_COLORS.length];
                        const selected = assignedCats.includes(cat);
                        return (
                          <td key={cat} className="px-1 text-center">
                            <div className="flex justify-center">
                              <button
                                type="button"
                                onClick={() => {
                                  const next = selected
                                    ? assignedCats.filter((c) => c !== cat)
                                    : [...assignedCats, cat];
                                  onSetItemCategory(idx, next);
                                }}
                                className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-all transform active:scale-90
                                  ${selected
                                    ? `${c.bg} border-transparent text-white shadow-sm scale-110`
                                    : `bg-white border-slate-200 text-slate-300 hover:border-slate-300 hover:bg-slate-50`
                                  }`}
                              >
                                {selected ? (
                                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="5">
                                    <polyline points="20,6 9,17 4,12"/>
                                  </svg>
                                ) : (
                                    <div className="w-1.5 h-1.5 rounded-full bg-slate-200" />
                                )}
                              </button>
                            </div>
                          </td>
                        );
                      })}
                      <td className="px-1">
                        {options.length > 1 && (
                          <button
