"use client";
/**
 * QuestionFormsWrapper — demonstrates integration of the new schema-driven
 * question forms with the existing QuestionEditorModal.
 *
 * This wrapper:
 * 1. Uses useReducer for all option/metadata state (schema.ts)
 * 2. Renders the correct form via QuestionForms orchestrator
 * 3. Syncs back to the parent's props via callbacks
 *
 * Usage: Replace the inline form conditionals in QuestionEditorModal
 * with this wrapper component.
 */
import React, { useCallback } from 'react';
import {
  QuestionForms,
  useQuestionForms,
} from './QuestionForms';
import {
  type QuestionType,
  type BaseOption,
} from '../schema';

interface QuestionFormsWrapperProps {
  selectedType: QuestionType;
  options: BaseOption[];
  metadata: Record<string, unknown>;
  categories: string[];
  scoreDefault: number;
  kisiKisi: string;
  pembahasan: string;
  // Setters (from parent state)
  setOptions: (opts: BaseOption[]) => void;
  setMetadata: (meta: Record<string, unknown>) => void;
  setCategories: (cats: string[]) => void;
  setScoreDefault: (score: number) => void;
  setKisiKisi: (kisi: string) => void;
  setPembahasan: (p: string) => void;
}

export const QuestionFormsWrapper = React.memo(({
  selectedType,
  options,
  metadata,
  categories,
  scoreDefault,
  kisiKisi,
  pembahasan,
  setOptions,
  setMetadata,
  setCategories,
  setScoreDefault,
  setKisiKisi,
  setPembahasan,
}: QuestionFormsWrapperProps) => {
  // Initialize reducer state from props
  const { state, dispatch } = useQuestionForms({
    type: selectedType,
    options,
    metadata: metadata as any,
    categories,
    scoreDefault,
    kisiKisi,
    pembahasan,
  });

  // Dispatch wrapper that syncs to parent
  const reducer = useCallback(
    (action: Parameters<typeof dispatch>[0]) => {
      dispatch(action);
      // Note: sync happens via useEffect in the parent,
      // or you can use useEffect here to call syncToParent(state)
    },
    [dispatch]
  );

  return (
    <QuestionForms
      state={state}
      dispatch={reducer}
    />
  );
});

QuestionFormsWrapper.displayName = 'QuestionFormsWrapper';

/**
 * USE_QUESTION_FORMS — custom hook version for pages that manage
 * their own question state. Provides state + dispatch + type-safe setters.
 *
 * Example usage in a page:
 *
 *   const { state, dispatch, setters } = useQuestionFormState({
 *     type: 'mcq',
 *     scoreDefault: 1,
 *   });
 *
 *   // Then in JSX:
 *   <QuestionForms state={state} dispatch={dispatch} />
 *
 *   // And for saving:
 *   const handleSave = async () => {
 *     const payload = {
 *       type: state.type,
 *       questionText,
 *       options: state.options,
 *       metadata: state.metadata,
 *       categories: state.categories,
 *       scoreDefault: state.scoreDefault,
 *     };
 *     await saveQuestionAction(payload);
 *   };
 */
export function useQuestionFormState(initial?: {
  type?: QuestionType;
  scoreDefault?: number;
}) {
  const { state, dispatch } = useQuestionForms({
    type: initial?.type ?? 'mcq',
    scoreDefault: initial?.scoreDefault ?? 1,
  });

  const setters = {
    setType: useCallback(
      (t: QuestionType) => dispatch({ type: 'SET_TYPE', payload: t }),
      [dispatch]
    ),
    setOptions: useCallback(
      (opts: BaseOption[]) => dispatch({ type: 'SET_OPTIONS', payload: opts }),
      [dispatch]
    ),
    addOption: useCallback(
      (extra?: Partial<BaseOption>) => dispatch({ type: 'ADD_OPTION', payload: extra }),
      [dispatch]
    ),
    removeOption: useCallback(
      (idx: number) => dispatch({ type: 'REMOVE_OPTION', payload: idx }),
      [dispatch]
    ),
    updateOption: useCallback(
      (idx: number, fields: Partial<BaseOption>) =>
        dispatch({ type: 'UPDATE_OPTION', payload: { index: idx, fields } }),
      [dispatch]
    ),
    setMetadata: useCallback(
      (meta: Record<string, unknown>) =>
        dispatch({ type: 'SET_METADATA', payload: meta as any }),
      [dispatch]
    ),
    setCategories: useCallback(
      (cats: string[]) => dispatch({ type: 'SET_CATEGORIES', payload: cats }),
      [dispatch]
    ),
    setScore: useCallback(
      (s: number) => dispatch({ type: 'SET_SCORE', payload: s }),
      [dispatch]
    ),
    setKisiKisi: useCallback(
      (k: string) => dispatch({ type: 'SET_KISI_KISI', payload: k }),
      [dispatch]
    ),
    setPembahasan: useCallback(
      (p: string) => dispatch({ type: 'SET_PEMBAHASAN', payload: p }),
      [dispatch]
    ),
    resetForType: useCallback(
      (t: QuestionType) => dispatch({ type: 'RESET_FOR_TYPE', payload: t }),
      [dispatch]
    ),
    loadQuestion: useCallback(
      (q: typeof state) => dispatch({ type: 'LOAD_QUESTION', payload: q }),
      [dispatch]
    ),
  };

  return { state, dispatch, setters };
}

/**
 * CBT Professional Math Utilities — Reconstruction Version
 *
 * Supports synchronous rendering, LRU caching, and thorough delimiter parsing.
 */
import katex from 'katex';
import 'katex/dist/katex.min.css';

export interface MathExpression {
  latex: string;
  start: number;
  end: number;
  displayMode: boolean;
  original: string;
}

export interface RenderResult {
  html: string;
  error: boolean;
}

const CACHE_MAX = 500;
const cache = new Map<string, string>();

function cacheKey(math: string, display: boolean): string {
  return `${display ? 'D' : 'I'}#${math}`;
}

export function getCachedMath(math: string, display: boolean): string | null {
  return cache.get(cacheKey(math, display)) ?? null;
}

export function setCachedMath(math: string, display: boolean, html: string): void {
  if (cache.size > CACHE_MAX) {
    const first = cache.keys().next().value;
    if (first !== undefined) cache.delete(first);
  }
  cache.set(cacheKey(math, display), html);
}

export function normalizeLatex(input: string): string {
  if (!input) return '';
  return input
    .replace(/&sol;/g, '/')
    .replace(/&#47;/g, '/')
    .replace(/&bsol;/g, '\\')
    .replace(/&#92;/g, '\\')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"');
}

export function renderLatex(math: string, displayMode = false): RenderResult {
  if (!math || !math.trim()) return { html: '', error: false };

  const norm = normalizeLatex(math);
  const cached = getCachedMath(norm, displayMode);
  if (cached !== null) return { html: cached, error: false };

  try {
    const html = katex.renderToString(norm, {
      displayMode,
      throwOnError: false,
      errorColor: '#cc0000',
      // Restrict trusted commands: only allow \href / \url with safe protocols.
      // Blocks javascript:/data: URLs and disables \htmlStyle/\htmlClass/
      // \includegraphics injection that `trust: true` would otherwise permit.
      trust: (context) => {
        if (context.command === '\\href' || context.command === '\\url') {
          return /^(https?:|mailto:|\/|#)/i.test(context.url || '');
        }
        return false;
      },
      strict: 'ignore',
      output: 'html',
    });

    setCachedMath(norm, displayMode, html);
    return { html, error: false };
  } catch (err) {
    return { html: `<span style="color:#cc0000;font-family:monospace">${norm}</span>`, error: true };
  }
}

export function extractMathExpressions(text: string): MathExpression[] {
  if (!text) return [];
  const results: MathExpression[] = [];
  const regex = /(\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\begin\{(?:equation|aligned|array|pmatrix|bmatrix|cases)\}[\s\S]*?\\end\{(?:equation|aligned|array|pmatrix|bmatrix|cases)\}|\\\(.*?\\\)|\[%.*?%\]|\$(?:[^$\n\\]|\\.)+\$)/g;

  let match: RegExpExecArray | null;
  while ((match = regex.exec(text)) !== null) {
    const original = match[0];
    const start = match.index;
    const end = regex.lastIndex;

    const isBlock = original.startsWith('$$') ||
                    original.startsWith('\\[') ||
                    original.startsWith('\\begin{');

    let latex = original;
    if (original.startsWith('$$') && original.endsWith('$$')) {
      latex = original.slice(2, -2);
    } else if (original.startsWith('\\[') && original.endsWith('\\]')) {
      latex = original.slice(2, -2);
    } else if (original.startsWith('\\begin{') && original.endsWith('}')) {
      latex = original;
    } else if (original.startsWith('\\(') && original.endsWith('\\)')) {
      latex = original.slice(2, -2);
    } else if (original.startsWith('[%') && original.endsWith('%]')) {
      latex = original.slice(2, -2);
    } else if (original.startsWith('$') && original.endsWith('$')) {
      latex = original.slice(1, -1);
    }

    results.push({
      latex: latex.trim(),
      start,
      end,
      displayMode: isBlock,
      original,
    });
  }

  return results;
}

export function sanitizeLatex(input: string): string {
  if (!input || typeof input !== 'string') return '';
  if (typeof document !== 'undefined') {
    const el = document.createElement('textarea');
    el.innerHTML = input;
    return el.value.trim();
  }
  return input.trim();
}

