}

// ─── Simple Bar Chart ────────────────────────────────────────

interface BarChartData {
  label: string;
  value: number;
  color?: string;
}

interface BarChartProps {
  data: BarChartData[];
  maxValue?: number;
  height?: number;
  showLabels?: boolean;
  className?: string;
}

export function BarChart({
  data,
  maxValue,
  height = 200,
  showLabels = true,
  className = '',
}: BarChartProps) {
  const max = maxValue ?? Math.max(...data.map(d => d.value), 1);

  return (
    <div className={`space-y-2 ${className}`}>
      {data.map((item, index) => {
        const percentage = (item.value / max) * 100;
        return (
          <div key={index} className="space-y-1">
            {showLabels && (
              <div className="flex justify-between text-xs">
                <span className="text-slate-600">{item.label}</span>
                <span className="text-slate-400 font-medium">{item.value}</span>
              </div>
            )}
            <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
              <div
                className={`h-full rounded-full transition-all duration-500 ${
                  item.color ?? 'bg-primary'
                }`}
                style={{ width: `${percentage}%` }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── Horizontal Bar Chart (for score distribution) ──────────

interface HorizontalBarChartProps {
  data: { range: string; count: number; percentage: number }[];
  className?: string;
}

export function HorizontalBarChart({ data, className = '' }: HorizontalBarChartProps) {
  const maxCount = Math.max(...data.map(d => d.count), 1);

  return (
    <div className={`space-y-2 ${className}`}>
      {data.map((item, i) => (
        <div key={i} className="flex items-center gap-3">
          <div className="w-12 text-xs text-slate-500 font-medium">{item.range}</div>
          <div className="flex-1 h-6 bg-slate-100 rounded-lg overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-primary to-primary/70 rounded-lg transition-all duration-500 flex items-center justify-end pr-2"
              style={{ width: `${(item.count / maxCount) * 100}%` }}
            >
              <span className="text-xs text-white font-medium">{item.count}</span>
            </div>
          </div>
          <div className="w-12 text-xs text-slate-400 text-right">{item.percentage}%</div>
        </div>
      ))}
    </div>
  );
}

// ─── Pie Chart (Simple) ─────────────────────────────────────

interface PieChartData {
  label: string;
  value: number;
  color: string;
}

interface PieChartProps {
  data: PieChartData[];
  size?: number;
  className?: string;
}

export function PieChart({ data, size = 200, className = '' }: PieChartProps) {
  const total = data.reduce((sum, d) => sum + d.value, 0);
  let currentAngle = -90;

  const getCoordinatesForAngle = (angle: number, radius: number) => {
    const rad = (angle * Math.PI) / 180;
    return {
      x: radius * Math.cos(rad) + radius,
      y: radius * Math.sin(rad) + radius,
    };
  };

  return (
    <div className={`flex flex-col items-center ${className}`}>
      <svg width={size * 2} height={size * 2} className="transform -rotate-90">
        {data.map((item, i) => {
          const percentage = item.value / total;
          const angle = percentage * 360;
          const startAngle = currentAngle;
          const endAngle = currentAngle + angle;

          const start = getCoordinatesForAngle(startAngle, size);
          const end = getCoordinatesForAngle(endAngle, size);

          const largeArcFlag = angle > 180 ? 1 : 0;

          const pathD = [
            `M ${size} ${size}`,
            `L ${start.x} ${start.y}`,
            `A ${size} ${size} 0 ${largeArcFlag} 1 ${end.x} ${end.y}`,
            'Z',
          ].join(' ');

          currentAngle = endAngle;

          return (
            <path
              key={i}
              d={pathD}
              fill={item.color}
              className="transition-all duration-300 hover:opacity-80 cursor-pointer"
            >
              <title>{item.label}: {item.value} ({Math.round(percentage * 100)}%)</title>
            </path>
          );
        })}
      </svg>
      <div className="flex flex-wrap gap-4 mt-4 justify-center">
        {data.map((item, i) => (
          <div key={i} className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
            <span className="text-xs text-slate-600">{item.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── Score Distribution Chart ────────────────────────────────

interface ScoreDistributionChartProps {
  data: {
    range: string;
    count: number;
    percentage: number;
  }[];
  className?: string;
}

export function ScoreDistributionChart({ data, className = '' }: ScoreDistributionChartProps) {
  const maxCount = Math.max(...data.map(d => d.count), 1);

  return (
    <div className={`space-y-1 ${className}`}>
      <div className="h-40 flex items-end gap-1">
        {data.map((item, i) => (
          <div key={i} className="flex-1 flex flex-col items-center gap-1">
            <div
              className="w-full bg-gradient-to-t from-primary to-primary/60 rounded-t transition-all duration-500 hover:from-primary/80"
              style={{ height: `${(item.count / maxCount) * 100}%`, minHeight: item.count > 0 ? '4px' : '0' }}
              title={`${item.range}: ${item.count} siswa (${item.percentage}%)`}
            />
            <span className="text-[10px] text-slate-400">{item.range}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── Progress Ring ──────────────────────────────────────────

interface ProgressRingProps {
  value: number;
  max?: number;
  size?: number;
  strokeWidth?: number;
  color?: string;
  bgColor?: string;
  showLabel?: boolean;
  className?: string;
}

export function ProgressRing({
  value,
  max = 100,
  size = 80,
  strokeWidth = 8,
  color = '#6366f1',
  bgColor = '#e2e8f0',
  showLabel = true,
  className = '',
}: ProgressRingProps) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const percentage = Math.min((value / max) * 100, 100);
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className={`relative inline-flex items-center justify-center ${className}`}>
      <svg width={size} height={size} className="transform -rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={bgColor}
          strokeWidth={strokeWidth}
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          className="transition-all duration-500"
        />
      </svg>
      {showLabel && (
        <span className="absolute text-sm font-bold text-slate-800">
          {Math.round(percentage)}%
        </span>
      )}
    </div>
  );
}

// ─── Legend Component ────────────────────────────────────────

interface LegendItem {
  label: string;
  color: string;
  value?: number;
}

interface LegendProps {
  items: LegendItem[];
  className?: string;
}

export function Legend({ items, className = '' }: LegendProps) {
  return (
    <div className={`flex flex-wrap gap-4 ${className}`}>
      {items.map((item, i) => (
        <div key={i} className="flex items-center gap-2">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: item.color }} />
          <span className="text-xs text-slate-600">
            {item.label}
            {item.value !== undefined && <span className="text-slate-400 ml-1">({item.value})</span>}
          </span>
        </div>
      ))}
    </div>
  );
}

"use client";
import React, { Component, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Home, Mail } from 'lucide-react';

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// ─── Error Fallback Component ───────────────────────────

interface FallbackProps {
  error: Error;
  resetError: () => void;
}

export function ErrorFallback({ error, resetError }: FallbackProps) {
  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-lg border border-slate-200 overflow-hidden">
        {/* Header with icon */}
        <div className="bg-red-50 px-6 py-8 text-center border-b border-red-100">
          <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <AlertTriangle size={28} className="text-red-500" />
          </div>
          <h2 className="text-xl font-bold text-slate-800">Terjadi Kesalahan</h2>
          <p className="text-sm text-slate-500 mt-1">Mohon maaf, terjadi kesalahan yang tidak terduga.</p>
        </div>

        {/* Error details (collapsible) */}
        <div className="px-6 py-4">
          <details className="group">
            <summary className="flex items-center gap-2 text-sm text-slate-500 cursor-pointer hover:text-slate-700">
              <span>Detail Error</span>
              <span className="text-xs text-slate-400 group-open:hidden">(klik untuk lihat)</span>
              <span className="text-xs text-slate-400 hidden group-open:block">(sembunyikan)</span>
            </summary>
            <div className="mt-3 p-3 bg-slate-50 rounded-lg text-xs font-mono text-slate-600 overflow-x-auto whitespace-pre-wrap break-all">
              {error.message || 'Unknown error'}
            </div>
          </details>
        </div>

        {/* Actions */}
        <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex gap-3">
          <button
            onClick={resetError}
            className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-primary text-white rounded-xl font-medium text-sm hover:opacity-90 transition-all"
          >
            <RefreshCw size={16} />
            Coba Lagi
          </button>
          <a
            href="/dashboard"
            className="flex items-center justify-center gap-2 px-4 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl font-medium text-sm hover:bg-slate-50 transition-all"
          >
            <Home size={16} />
            Beranda
          </a>
        </div>

        {/* Footer */}
        <div className="px-6 py-3 bg-slate-50 border-t border-slate-100 text-center">
          <p className="text-xs text-slate-400">
            Jika masalah persists, hubungi administrator.
          </p>
        </div>
      </div>
    </div>
  );
}

// ─── Error Boundary Component ─────────────────────────────

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    // Log error (can integrate with Sentry, LogRocket, etc.)
    console.error('ErrorBoundary caught an error:', error, errorInfo);

    // Call custom error handler if provided
    this.props.onError?.(error, errorInfo);
  }

  resetError = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError && this.state.error) {
      if (this.props.fallback) {
        return this.props.fallback;
      }
      return (
        <ErrorFallback
          error={this.state.error}
          resetError={this.resetError}
        />
      );
    }

    return this.props.children;
  }
}

// ─── Simple Error Display (for inline use) ───────────────

interface InlineErrorProps {
  message?: string;
  onRetry?: () => void;
}

export function InlineError({ message = 'Terjadi kesalahan', onRetry }: InlineErrorProps) {
  return (
    <div className="flex flex-col items-center justify-center p-6 text-center">
      <div className="w-12 h-12 bg-red-50 rounded-xl flex items-center justify-center mb-3">
        <AlertTriangle size={20} className="text-red-400" />
      </div>
      <p className="text-sm text-slate-500 mb-3">{message}</p>
      {onRetry && (
        <button
          onClick={onRetry}
          className="px-4 py-2 text-sm font-medium text-primary hover:bg-slate-50 rounded-lg transition-colors"
        >
          Coba Lagi
        </button>
      )}
    </div>
  );
}

// ─── Loading Error State ─────────────────────────────────

export function LoadingError() {
  return (
    <div className="min-h-[200px] flex items-center justify-center">
      <div className="text-center">
        <div className="w-10 h-10 border-2 border-slate-200 border-t-red-500 rounded-full animate-spin mx-auto mb-3" />
        <p className="text-sm text-slate-400">Memuat...</p>
      </div>
    </div>
  );
}

// ─── Network Error State ──────────────────────────────────

export function NetworkError({ onRetry }: { onRetry?: () => void }) {
  return (
    <div className="min-h-[200px] flex items-center justify-center">
      <div className="text-center max-w-xs">
        <div className="w-12 h-12 bg-slate-100 rounded-xl flex items-center justify-center mx-auto mb-3">
          <svg className="w-6 h-6 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 5.636a9 9 0 010 12.728m0 0l-2.829-2.829m2.829 2.829L21 21M15.536 8.464a5 5 0 010 7.072m0 0l-2.829-2.829m-4.243 2.829a4.978 4.978 0 01-1.414-2.83m-1.414 5.658a9 9 0 01-2.167-9.238m7.824 2.167a1 1 0 111.414 1.414m-1.414-1.414L3 3m8.293 8.293l1.414 1.414" />
          </svg>
        </div>
        <p className="text-sm font-medium text-slate-700 mb-1">Koneksi Terputus</p>
        <p className="text-xs text-slate-400 mb-4">Periksa koneksi internet Anda dan coba lagi.</p>
        {onRetry && (
          <button
            onClick={onRetry}
            className="px-4 py-2 bg-primary text-white text-sm font-medium rounded-lg hover:opacity-90 transition-all"
          >
            Coba Lagi
          </button>
        )}
      </div>
    </div>
  );
}

