"use client";
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Bell,
    Check,
    CheckCheck,
    Trash2,
    X,
    Clock,
    Settings,
    ChevronRight,
    Loader2
} from 'lucide-react';
import {
    getUserNotifications,
    getUnreadNotificationCount,
    markNotificationRead,
    markAllNotificationsRead,
    deleteNotification
} from '@/lib/api/notifications';
import type { Notification } from '@/app/types/notification';
import { NOTIFICATION_TYPE_LABELS, getNotificationTimeAgo } from '@/app/types/notification';
import { REFRESH_INTERVAL } from '@/lib/useAutoRefresh';

interface NotificationBellProps {
    userId: string;
}

export function NotificationBell({ userId }: NotificationBellProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [isMarkingAllRead, setIsMarkingAllRead] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // Fetch notifications
    const fetchNotifications = useCallback(async () => {
        setIsLoading(true);
        try {
            const [notifs, count] = await Promise.all([
                getUserNotifications({ limit: 10 }),
                getUnreadNotificationCount()
            ]);
            setNotifications(notifs);
            setUnreadCount(count);
        } catch (error) {
            console.error('[NotificationBell] Fetch error:', error);
        }
        setIsLoading(false);
    }, [userId]);

    // Initial fetch + Supabase Realtime subscription
    // Notifikasi dimuat ulang berkala. Dulu perubahannya didorong langganan
    // realtime Supabase, yang sudah tidak ada — dan langganan itu pun sudah mati
    // lebih dulu karena menyebut tabel `notifications`, bukan `cbt_notifications`.
    useEffect(() => {
        fetchNotifications();
        const interval = setInterval(fetchNotifications, REFRESH_INTERVAL.notifications);
        return () => clearInterval(interval);
    }, [userId, fetchNotifications]);

    // Close dropdown when clicking outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        }

        if (isOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }

        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen]);

    // Handle mark as read
    const handleMarkAsRead = async (notificationId: string) => {
        await markNotificationRead(notificationId);
        fetchNotifications();
    };

    // Handle mark all as read
    const handleMarkAllAsRead = async () => {
        setIsMarkingAllRead(true);
        await markAllNotificationsRead();
        fetchNotifications();
        setIsMarkingAllRead(false);
    };

    // Handle delete
    const handleDelete = async (notificationId: string) => {
        await deleteNotification(notificationId);
        fetchNotifications();
    };

    // Get notification icon based on type
    const getNotificationIcon = (type: string) => {
        switch (type) {
            case 'exam_reminder': return '🔔';
            case 'exam_result': return '📊';
            case 'exam_available': return '✅';
            case 'class_invite': return '👋';
            case 'achievement': return '🏆';
            default: return '📌';
        }
    };

    return (
        <div className="relative" ref={dropdownRef}>
            {/* Bell Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2 rounded-xl hover:bg-slate-100 transition-colors"
            >
                <Bell size={22} className="text-slate-600" />
                <AnimatePresence>
                    {unreadCount > 0 && (
                        <motion.span
                            initial={{ scale: 0 }}
                            animate={{ scale: 1 }}
                            exit={{ scale: 0 }}
                            className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center min-w-[20px] h-[20px]"
                        >
                            {unreadCount > 9 ? '9+' : unreadCount}
                        </motion.span>
                    )}
                </AnimatePresence>
            </button>

            {/* Dropdown */}
            <AnimatePresence>
                {isOpen && (
                    <>
                        {/* Backdrop */}
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="fixed inset-0 z-40"
                            onClick={() => setIsOpen(false)}
                        />

                        {/* Dropdown Panel */}
                        <motion.div
                            initial={{ opacity: 0, y: -10, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, y: -10, scale: 0.95 }}
                            transition={{ duration: 0.15 }}
                            className="absolute right-0 top-full mt-2 w-80 md:w-96 bg-white rounded-2xl shadow-2xl border border-slate-200 z-50 overflow-hidden"
                        >
                            {/* Header */}
                            <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100 bg-slate-50">
                                <div>
                                    <h3 className="font-bold text-slate-800">Notifikasi</h3>
                                    <p className="text-xs text-slate-500">
                                        {unreadCount > 0 ? `${unreadCount} belum dibaca` : 'Semua sudah dibaca'}
                                    </p>
                                </div>
                                <div className="flex items-center gap-1">
                                    {unreadCount > 0 && (
                                        <button
                                            onClick={handleMarkAllAsRead}
                                            disabled={isMarkingAllRead}
                                            className="p-2 rounded-lg hover:bg-slate-200 text-slate-500 transition-colors"
                                            title="Tandai semua sudah dibaca"
                                        >
                                            {isMarkingAllRead ? (
                                                <Loader2 size={16} className="animate-spin" />
                                            ) : (
                                                <CheckCheck size={16} />
                                            )}
                                        </button>
                                    )}
                                    <button
                                        onClick={() => setIsOpen(false)}
                                        className="p-2 rounded-lg hover:bg-slate-200 text-slate-500 transition-colors"
                                    >
                                        <X size={16} />
                                    </button>
                                </div>
                            </div>

                            {/* Notification List */}
                            <div className="max-h-[400px] overflow-y-auto">
                                {isLoading ? (
                                    <div className="flex items-center justify-center py-12">
                                        <Loader2 size={24} className="animate-spin text-slate-400" />
                                    </div>
                                ) : notifications.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center py-12 px-4">
                                        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                                            <Bell size={24} className="text-slate-400" />
                                        </div>
                                        <p className="text-slate-600 font-medium text-center">Tidak ada notifikasi</p>
                                        <p className="text-xs text-slate-400 text-center mt-1">
                                            Notifikasi akan muncul di sini
                                        </p>
                                    </div>
                                ) : (
                                    <div className="divide-y divide-slate-100">
                                        {notifications.map((notif) => (
                                            <div
                                                key={notif.id}
                                                className={`px-4 py-3 hover:bg-slate-50 transition-colors ${
                                                    !notif.is_read ? 'bg-primary/5' : ''
                                                }`}
                                            >
                                                <div className="flex items-start gap-3">
                                                    {/* Icon */}
                                                    <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-lg shrink-0">
                                                        {getNotificationIcon(notif.type)}
                                                    </div>

                                                    {/* Content */}
                                                    <div className="flex-1 min-w-0">
                                                        <div className="flex items-start justify-between gap-2">
                                                            <p className={`text-sm ${!notif.is_read ? 'font-semibold text-slate-800' : 'text-slate-600'}`}>
                                                                {notif.title}
                                                            </p>
                                                            {!notif.is_read && (
                                                                <span className="w-2 h-2 bg-primary rounded-full shrink-0 mt-1" />
                                                            )}
                                                        </div>
                                                        {notif.message && (
                                                            <p className="text-xs text-slate-500 mt-0.5 line-clamp-2">
                                                                {notif.message}
                                                            </p>
                                                        )}
                                                        <div className="flex items-center gap-2 mt-1.5">
                                                            <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                                                <Clock size={10} />
                                                                {getNotificationTimeAgo(notif.created_at)}
                                                            </span>
                                                        </div>
                                                    </div>

                                                    {/* Actions */}
                                                    <div className="flex items-center gap-1 shrink-0">
                                                        {!notif.is_read && (
                                                            <button
                                                                onClick={() => handleMarkAsRead(notif.id)}
                                                                className="p-1.5 rounded-lg hover:bg-slate-200 text-slate-400 transition-colors"
                                                                title="Tandai sudah dibaca"
                                                            >
                                                                <Check size={14} />
                                                            </button>
                                                        )}
                                                        <button
                                                            onClick={() => handleDelete(notif.id)}
                                                            className="p-1.5 rounded-lg hover:bg-red-50 text-slate-400 hover:text-red-500 transition-colors"
                                                            title="Hapus"
                                                        >
                                                            <Trash2 size={14} />
                                                        </button>
                                                    </div>
                                                </div>

                                                {/* Action Link */}
                                                {notif.action_url && (
                                                    <button
                                                        onClick={() => {
                                                            window.location.href = notif.action_url!;
                                                            setIsOpen(false);
                                                        }}
                                                        className="mt-2 w-full flex items-center justify-center gap-1 py-1.5 bg-slate-100 hover:bg-slate-200 rounded-lg text-xs font-medium text-slate-600 transition-colors"
                                                    >
                                                        Lihat Detail <ChevronRight size={12} />
                                                    </button>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>

                            {/* Footer */}
                            {notifications.length > 0 && (
                                <div className="px-4 py-3 border-t border-slate-100 bg-slate-50">
                                    <button
                                        onClick={() => {
                                            window.location.href = '/dashboard/notifications';
                                            setIsOpen(false);
                                        }}
                                        className="w-full py-2 text-sm font-medium text-primary hover:bg-primary/10 rounded-lg transition-colors"
                                    >
                                        Lihat Semua Notifikasi
                                    </button>
                                </div>
                            )}
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";
import React from 'react';
import { motion } from 'framer-motion';

// ─── Base Skeleton Component ───────────────────────────────

interface SkeletonProps {
  className?: string;
  variant?: 'text' | 'circular' | 'rectangular' | 'rounded';
  width?: string | number;
  height?: string | number;
  animation?: 'pulse' | 'wave' | 'none';
}

const variantClasses = {
  text: 'rounded',
  circular: 'rounded-full',
  rectangular: 'rounded-none',
  rounded: 'rounded-xl',
};

export function Skeleton({
  className = '',
  variant = 'rounded',
  width,
  height,
  animation = 'pulse',
}: SkeletonProps) {
  const animationClass = animation === 'pulse'
    ? 'animate-pulse bg-slate-200'
    : animation === 'wave'
    ? 'skeleton-wave'
    : 'bg-slate-200';

  return (
    <div
      className={`${variantClasses[variant]} ${animationClass} ${className}`}
      style={{
        width: width ?? undefined,
        height: height ?? undefined,
      }}
    />
  );
}

// ─── Skeleton with Animation Variants ─────────────────────

export function SkeletonPulse({ className = '', ...props }: SkeletonProps) {
  return <Skeleton {...props} className={`animate-pulse bg-slate-200 ${className}`} />;
}

export function SkeletonWave({ className = '', ...props }: SkeletonProps) {
  return (
    <div className={`relative overflow-hidden ${className}`} {...props}>
      <Skeleton />
      <div className="absolute inset-0 -translate-x-full animate-[shimmer_2s_infinite] bg-gradient-to-r from-transparent via-white/40 to-transparent" />
      <style jsx>{`
        @keyframes shimmer {
          100% { transform: translateX(100%); }
        }
        .animate-\[shimmer_2s_infinite\] {
          animation: shimmer 2s infinite;
        }
      `}</style>
    </div>
  );
}

// ─── Text Skeleton Lines ──────────────────────────────────

interface SkeletonTextProps {
  lines?: number;
  className?: string;
  lastLineWidth?: string;
}

export function SkeletonText({ lines = 3, className = '', lastLineWidth = '60%' }: SkeletonTextProps) {
  return (
    <div className={`space-y-2 ${className}`}>
      {Array.from({ length: lines }).map((_, i) => (
        <Skeleton
          key={i}
          variant="text"
          height={16}
          className={i === lines - 1 ? lastLineWidth : 'w-full'}
        />
      ))}
    </div>
  );
}

// ─── Utility Components ─────────────────────────────────────

export function SkeletonAvatar({ size = 40 }: { size?: number }) {
  return <Skeleton variant="circular" width={size} height={size} />;
}

export function SkeletonButton({ className = '' }: { className?: string }) {
  return <Skeleton variant="rounded" height={40} className={`w-24 ${className}`} />;
}

export function SkeletonBadge({ className = '' }: { className?: string }) {
  return <Skeleton variant="rounded" height={24} className={`w-16 ${className}`} />;
}

'use client';

import React, { useState, useEffect } from 'react';
import { Activity, Loader2, X } from 'lucide-react';
import { getRecentLogins } from '@/lib/api/proctor';

interface LoginUser {
    id: string;
    userId: string;
    fullName: string;
    role: string;
    isActive: boolean; // refers to account status
    lastLoginAt: string;
}

export function RecentLoginsCard({ initialLogins, orgId }: { initialLogins: LoginUser[], orgId: string }) {
    const [logins, setLogins] = useState<LoginUser[]>(initialLogins);
    const [showAllModal, setShowAllModal] = useState(false);
    const [allLogins, setAllLogins] = useState<LoginUser[]>([]);
    const [allLoading, setAllLoading] = useState(false);
    const [searchAll, setSearchAll] = useState('');

    useEffect(() => {
        setLogins(initialLogins);
    }, [initialLogins]);

    // Helper to format time ago for offline users
    const getTimeAgo = (dateString: string) => {
        const now = new Date();
        const past = new Date(dateString);
        const diffMs = now.getTime() - past.getTime();
        const diffMins = Math.floor(diffMs / 60000);

        if (diffMins < 1) return 'baru saja';
        if (diffMins < 60) return `${diffMins} mnt lalu`;

        const diffHours = Math.floor(diffMins / 60);
        if (diffHours < 24) return `${diffHours} jam lalu`;

        const diffDays = Math.floor(diffHours / 24);
        return `${diffDays} hari lalu`;
    };

    // Yang paling baru masuk di atas.
    //
    // Dulu pengguna yang SEDANG online diletakkan lebih dulu, memakai presence
    // realtime Supabase. Sumber itu sudah tidak ada, dan satu-satunya penanda
    // aktivitas yang tersisa adalah `last_sign_in_at` — waktu MASUK, bukan waktu
    // aktif. Menyebutnya "online" akan keliru, jadi yang ditampilkan hanya kapan
    // seseorang terakhir masuk.
    const sortByRecent = (list: LoginUser[]) =>
        [...list].sort((a, b) => {
            const ta = a.lastLoginAt ? new Date(a.lastLoginAt).getTime() : 0;
            const tb = b.lastLoginAt ? new Date(b.lastLoginAt).getTime() : 0;
            return tb - ta;
        });

    const openAllModal = async () => {
        setShowAllModal(true);
        setAllLoading(true);
        try {
            const all = await getRecentLogins(orgId, 1000);
            setAllLogins((all || []).filter((m: any) => m.lastLoginAt) as LoginUser[]);
        } catch (e) {
            console.error('Load all logins error:', e);
            setAllLogins([]);
        } finally {
            setAllLoading(false);
        }
    };

    const sortedLogins = sortByRecent(logins);
    const filteredAll = sortByRecent(allLogins).filter(l =>
        !searchAll.trim() || l.fullName.toLowerCase().includes(searchAll.trim().toLowerCase())
    );

    const renderRow = (login: LoginUser) => {
        return (
            <div
                key={login.id}
                className="flex items-center gap-3 p-2 rounded-lg hover:bg-slate-50 transition-colors"
            >
                {/* Avatar */}
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
                    login.isActive ? 'bg-[#030C4D]/10' : 'bg-slate-100'
                }`}>
                    <span className={`text-xs font-bold ${
                        login.isActive ? 'text-[#030C4D]' : 'text-slate-400'
                    }`}>
                        {login.fullName.charAt(0).toUpperCase()}
                    </span>
                </div>
                {/* Info */}
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-semibold text-slate-800 truncate">{login.fullName}</p>
                    <p className="text-[10px] text-slate-400">{login.role}</p>
                </div>
                {/* Status & Waktu */}
                <div className="shrink-0 text-right flex flex-col items-end">
                    {login.lastLoginAt ? (
                        <span className="inline-flex items-center justify-center px-2 py-0.5 rounded-lg text-[10px] font-bold border bg-slate-100 text-slate-500 border-slate-200">
                            {getTimeAgo(login.lastLoginAt)}
                        </span>
                    ) : (
                        <span className="text-[10px] text-slate-400">Belum pernah masuk</span>
                    )}
                </div>
            </div>
        );
    };

    return (
        <div className="bg-white rounded-lg border border-[#0038A8]/30 overflow-hidden shadow-sm">
            <div className="px-5 py-4 border-b border-[#0038A8]/20 bg-gradient-to-r from-[#030C4D]/[.02] to-transparent flex items-center justify-between">
                <h2 className="text-sm font-bold text-slate-900">Aktivitas Login</h2>
                <button
                    onClick={openAllModal}
                    className="text-[11px] font-bold text-[#0038A8] hover:text-[#030C4D] px-2.5 py-1 rounded-lg border border-[#0038A8]/30 hover:bg-[#0038A8]/5 transition-colors"
                >
                    Lihat Semua
                </button>
            </div>
            <div className="p-3 max-h-72 overflow-y-auto">
                {sortedLogins.length > 0 ? (
                    <div className="space-y-2">
                        {sortedLogins.map(renderRow)}
                    </div>
                ) : (
                    <div className="py-8 text-center">
                        <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-3">
                            <Activity size={20} className="text-slate-400" />
                        </div>
                        <p className="text-xs text-slate-500">Belum ada aktivitas login</p>
                    </div>
                )}
            </div>

            {/* MODAL: semua pengguna yang pernah login, terbaru paling atas */}
            {showAllModal && (
                <div
                    className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4"
                    onClick={() => setShowAllModal(false)}
                >
                    <div
                        className="bg-white rounded-xl shadow-2xl max-w-lg w-full overflow-hidden flex flex-col max-h-[85dvh]"
                        onClick={e => e.stopPropagation()}
                    >
                        <div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                            <div>
                                <h3 className="font-bold text-slate-800">Semua Aktivitas Login</h3>
                                {!allLoading && (
                                    <p className="text-[11px] text-slate-500 mt-0.5">
                                        {allLogins.length} pernah login
                                    </p>
                                )}
                            </div>
                            <button onClick={() => setShowAllModal(false)} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:bg-slate-200 rounded-lg transition-colors">
                                <X size={16} />
                            </button>
                        </div>
                        <div className="px-4 pt-3">
                            <input
                                type="text"
                                value={searchAll}
                                onChange={(e) => setSearchAll(e.target.value)}
                                placeholder="Cari nama..."
                                className="w-full bg-white border border-slate-200 text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-[#0038A8]/40 outline-none px-3 py-2 rounded-lg text-sm"
                            />
                        </div>
                        <div className="p-3 overflow-y-auto flex-1">
                            {allLoading ? (
                                <div className="py-10 flex items-center justify-center">
                                    <Loader2 size={24} className="text-[#0038A8] animate-spin" />
                                </div>
                            ) : filteredAll.length > 0 ? (
                                <div className="space-y-1.5">
                                    {filteredAll.map(renderRow)}
                                </div>
                            ) : (
                                <p className="py-8 text-center text-xs text-slate-400">Tidak ada data yang cocok</p>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

