                            className="w-full appearance-none bg-white border border-[#030C4D]/30 rounded-lg pl-4 pr-10 py-3 text-sm focus:ring-2 focus:ring-[#030C4D]/20 outline-none text-slate-600 cursor-pointer"
                        >
