                            </div>

                            {/* Summary */}
                            <div className="mt-4 pt-4 border-t border-[#030C4D]/20">
                                {assignData.classIds.length === 0 ? (
                                    <div className="text-xs text-red-600 bg-red-50 border border-red-200 p-3 rounded-xl">
