"use client";
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    ArrowLeft, Loader2, Plus, X, Check, Trash2,
    Calendar, Clock, BookOpen, Users, Lock,
    AlertTriangle, Settings, Zap
} from 'lucide-react';
import { getProctorOrganization } from '@/lib/api/proctor';
import {
    getPASPeriod,
    listOrganizationClasses,
    addPASScheduleAction,
    removePASScheduleAction,
    generateExamsFromSchedulesAction,
    listSubjects,
    listPASSessions,
} from '@/lib/api/pas';
import { listQuestionBanks } from '@/lib/api/questions';
import { getSessionUser } from '@/lib/session';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { useMemoryState } from '@/lib/useMemoryState';
import BulkScheduleGrid from './BulkScheduleGrid';
import RoomManagementModal from '@/app/dashboard/admin/pas/RoomManagementModal';

type TabId = 'schedules' | 'live_today' | 'detail';

export default function ProctorPASDetailPage() {
    const router = useRouter();
    const params = useParams();
    const periodId = params.id as string;

    const [period, setPeriod] = useState<any>(null);
    const [classes, setClasses] = useMemoryState<any[]>('proktor_exams_pas__id__classes', []);
    const [subjects, setSubjects] = useMemoryState<any[]>('proktor_exams_pas__id__subjects', []);
    const [qBanks, setQBanks] = useMemoryState<any[]>('proktor_exams_pas__id__qBanks', []);
    const [sessions, setSessions] = useMemoryState<any[]>('proktor_exams_pas__id__sessions', []);
    const [orgId, setOrgId] = useMemoryState<string>('proktor_exams_pas__id__orgId', '');
    const [isLoading, setIsLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<TabId>('schedules');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isAddScheduleOpen, setIsAddScheduleOpen] = useState(false);
    const [isBulkInputOpen, setIsBulkInputOpen] = useState(false);
    const [isRoomManagementOpen, setIsRoomManagementOpen] = useState(false);
    const [selectedScheduleIds, setSelectedScheduleIds] = useMemoryState<string[]>('proktor_exams_pas__id__selectedScheduleIds', []);
    const [isGenerating, setIsGenerating] = useState(false);

    const [scheduleForm, setScheduleForm] = useState({
        bank_id: '',
        subject_id: '',
        class_ids: [] as string[],
        scheduled_date: '',
        session_id: '',
        duration_minutes: 90,
        room: '',
    });

    useEffect(() => { loadData();
        // Auto-injected smart sync (Window Focus)
        const handleFocus = () => { if (typeof loadData === 'function') loadData(); };
        window.addEventListener('focus', handleFocus);
        return () => window.removeEventListener('focus', handleFocus); }, [periodId]);

    const loadData = async () => {
        const authUser = await getSessionUser();
        if (authUser) {
            const orgData = await getProctorOrganization();
            if (orgData) {
                const [periodData, bankList, classList, subjectList, sessionList] = await Promise.all([
                    getPASPeriod(periodId),
                    listQuestionBanks(orgData.id, true),
                    listOrganizationClasses(orgData.id, { activeYearOnly: true }),
                    listSubjects(orgData.id),
                    listPASSessions(periodId),
                ]);
                setPeriod(periodData);
                setQBanks(bankList || []);
                setClasses(classList || []);
                setSubjects(subjectList || []);
                setSessions(sessionList || []);
                setOrgId(orgData.id);
            }
        }
        setIsLoading(false);
    };

    const toggleClass = (classId: string) => {
        setScheduleForm(prev => ({
            ...prev,
            class_ids: prev.class_ids.includes(classId)
                ? prev.class_ids.filter(id => id !== classId)
                : [...prev.class_ids, classId]
        }));
    };

    const handleAddSchedule = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!scheduleForm.bank_id || !scheduleForm.subject_id || scheduleForm.class_ids.length === 0 || !scheduleForm.scheduled_date || !scheduleForm.session_id) {
            alert('Lengkapi bank soal, mata pelajaran, minimal satu kelas, tanggal, dan sesi.');
            return;
        }
        setIsSubmitting(true);
        for (const classId of scheduleForm.class_ids) {
            const result = await addPASScheduleAction({
                pas_period_id: periodId,
                bank_id: scheduleForm.bank_id,
                subject_id: scheduleForm.subject_id,
                class_id: classId,
                scheduled_date: scheduleForm.scheduled_date,
                session_id: scheduleForm.session_id,
                duration_override: scheduleForm.duration_minutes,
                room: scheduleForm.room || undefined,
            });
            if (!result.success) {
                alert('Gagal: ' + result.error);
                setIsSubmitting(false);
                return;
            }
        }
        setIsAddScheduleOpen(false);
        setScheduleForm({ bank_id: '', subject_id: '', class_ids: [], scheduled_date: '', session_id: '', duration_minutes: 90, room: '' });
        await loadData();
        setIsSubmitting(false);
    };

    const handleRemoveSchedule = async (scheduleId: string) => {
        if (!confirm('Hapus jadwal ini?')) return;
        const result = await removePASScheduleAction(scheduleId);
        if (result.success) await loadData();
        else alert(result.error);
    };

    const toggleScheduleSelect = (id: string) => {
        setSelectedScheduleIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const handleGenerateExams = async () => {
        if (selectedScheduleIds.length === 0) { alert('Pilih jadwal terlebih dahulu.'); return; }
        if (!confirm(`Generate ${selectedScheduleIds.length} ujian?`)) return;
        setIsGenerating(true);
        const result = await generateExamsFromSchedulesAction(selectedScheduleIds);
        if (result.success) {
            alert(`${result.created} ujian berhasil dibuat.`);
            setSelectedScheduleIds([]);
            await loadData();
        } else { alert(result.error || 'Gagal generate'); }
        setIsGenerating(false);
    };

    const formatDate = (dateStr: string) => {
        if (!dateStr) return '-';
        return new Date(dateStr).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
    };

    const getBankTitle = (bankId: string, sc?: any) => {
        if (sc?.question_banks?.title) return sc.question_banks.title;
        return qBanks.find((b: any) => b.id === bankId)?.title || 'Bank soal dihapus';
    };

    const getSchedulesByDateAndTime = (filteredSchedules: any[]) => {
        const grouped: Record<string, Record<string, any[]>> = {};
        for (const sc of filteredSchedules) {
            const dateStr = sc.scheduled_date || 'Tanpa Tanggal';
            const timeStr = sc.scheduled_time || 'Tanpa Waktu';
            
            if (!grouped[dateStr]) grouped[dateStr] = {};
            if (!grouped[dateStr][timeStr]) grouped[dateStr][timeStr] = [];
            
            grouped[dateStr][timeStr].push(sc);
        }
        
        // Sort dates
        const sortedDates = Object.keys(grouped).sort();
        const result: Array<{ date: string; sessions: Array<{ time: string; schedules: any[] }> }> = [];
        
        for (const date of sortedDates) {
            const sortedTimes = Object.keys(grouped[date]).sort();
            result.push({
                date,
                sessions: sortedTimes.map(t => ({
                    time: t,
                    schedules: grouped[date][t]
                }))
            });
        }
        return result;
    };

    if (isLoading) {
        return (
            <div className="flex justify-center py-20">
                <Loader2 size={48} className="text-primary animate-spin" />
            </div>
        );
    }

    if (!period) {
        return (
            <div className="max-w-2xl mx-auto py-20 text-center">
                <AlertTriangle size={48} className="text-amber-400 mx-auto mb-4" />
                <h2 className="text-xl font-bold text-slate-700 mb-2">Periode Tidak Ditemukan</h2>
                <button onClick={() => router.push('/dashboard/admin/exams')} className="px-6 py-2 bg-primary text-white rounded-xl mt-4">Kembali ke Pengaturan</button>
            </div>
        );
    }

    const schedules = period?.pas_class_schedules || [];
    
    // Live Today filter
    const todayStr = new Date().toISOString().split('T')[0];
    const liveSchedules = schedules.filter((s: any) => s.scheduled_date === todayStr);

    const groupedSchedules = getSchedulesByDateAndTime(activeTab === 'live_today' ? liveSchedules : schedules);

    return (
        <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {/* ── Hero Header — Navy Gradient ── */}
            <div className="relative overflow-hidden rounded-2xl acca-hero-gradient shadow-xl shadow-[#0038A8]/20">
                {/* Decorative blobs */}
                <div className="absolute -top-12 -right-12 w-72 h-72 bg-[#0038A8]/10 rounded-full blur-3xl pointer-events-none" />
                <div className="absolute -bottom-12 -left-12 w-56 h-56 bg-white/5 rounded-full blur-2xl pointer-events-none" />

                <div className="relative z-10 px-6 py-4 flex items-start gap-4">
                    <Link href="/dashboard/admin/pas" className="mt-1 p-2 text-white hover:text-white hover:bg-white/10 rounded-xl transition-all border border-transparent hover:border-white/20">
                        <ArrowLeft size={20} />
                    </Link>
                    <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2 flex-wrap">
                            <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wider ${
                                period.is_locked ? 'bg-red-500/20 text-white border border-red-500/30' : 'bg-emerald-500/20 text-white border border-emerald-500/30'
                            }`}>
                                {period.type?.toUpperCase()} {period.semester === 'ganjil' ? 'GANJIL' : 'GENAP'}
                            </span>
                            <span className="px-2.5 py-0.5 bg-white/10 text-white text-[10px] font-bold tracking-wider rounded-full border border-white/20">{period.school_year}</span>
                            {period.is_locked && <span className="px-2.5 py-0.5 bg-red-500/20 text-white border border-red-500/30 text-[10px] font-bold tracking-wider rounded-full flex items-center gap-1"><Lock size={10} /> TERKUNCI</span>}
                        </div>
                        <h1 className="text-2xl font-bold text-white mb-1.5">{period.name}</h1>
                        <p className="text-white text-sm font-semibold flex items-center gap-1.5">
                            <Calendar size={14} />
                            {formatDate(period.start_date)} — {formatDate(period.end_date)}
                        </p>
                    </div>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex flex-wrap gap-1 p-1 bg-slate-100 rounded-xl w-max">
                <button onClick={() => setActiveTab('schedules')}
                    className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-medium transition-all ${
                        activeTab === 'schedules' ? 'bg-white text-primary shadow-sm' : 'text-slate-500 hover:text-slate-700'
                    }`}>
                    <Calendar size={15} /> Semua Jadwal
                    <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${activeTab === 'schedules' ? 'bg-primary/10 text-primary' : 'bg-slate-200 text-slate-500'}`}>
                        {schedules.length}
                    </span>
                </button>
                <button onClick={() => setActiveTab('live_today')}
                    className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-medium transition-all ${
                        activeTab === 'live_today' ? 'bg-white text-primary shadow-sm' : 'text-slate-500 hover:text-slate-700'
                    }`}>
                    <Zap size={15} className={activeTab === 'live_today' ? 'text-amber-500' : ''} /> Live Hari Ini
                    {liveSchedules.length > 0 && (
                        <span className="flex h-2 w-2 relative ml-1">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                        </span>
                    )}
                </button>
                <button onClick={() => setActiveTab('detail')}
                    className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-medium transition-all ${
                        activeTab === 'detail' ? 'bg-white text-primary shadow-sm' : 'text-slate-500 hover:text-slate-700'
                    }`}>
                    <Settings size={15} /> Detail
                </button>
            </div>

            {/* ─── SCHEDULES & LIVE TAB ─── */}
            {(activeTab === 'schedules' || activeTab === 'live_today') && (
                <div className="space-y-6">
                    {!period.is_locked && activeTab === 'schedules' && !isBulkInputOpen && (
                        <div className="flex justify-end gap-3 flex-wrap">
                            <button onClick={() => setIsRoomManagementOpen(true)}
                                className="px-4 py-2 text-sm bg-slate-100 text-slate-700 border border-slate-200 rounded-xl hover:bg-slate-200 flex items-center gap-2 font-medium">
                                <Settings size={16} /> Pengaturan Sesi & Ruang
                            </button>
                            <button onClick={() => setIsBulkInputOpen(true)}
                                className="px-4 py-2 text-sm bg-primary text-white rounded-xl hover:bg-primary/90 flex items-center gap-2 shadow-lg shadow-primary/20 font-medium">
                                <Calendar size={16} /> Atur Jadwal
                            </button>
                        </div>
                    )}

                    {isBulkInputOpen && (
                        <BulkScheduleGrid
                            periodId={periodId}
                            period={period}
                            classes={classes}
                            subjects={subjects}
                            qBanks={qBanks}
                            sessions={sessions}
                            onComplete={() => { setIsBulkInputOpen(false); loadData(); }}
                            onCancel={() => setIsBulkInputOpen(false)}
                        />
                    )}

                    {(!isBulkInputOpen && activeTab === 'live_today' && liveSchedules.length === 0) && (
                        <div className="py-16 text-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
                            <Calendar size={40} className="mx-auto mb-3 opacity-40" />
                            <p className="font-medium text-slate-600">Tidak ada jadwal ujian hari ini</p>
                            <p className="text-sm mt-1">Ujian PAS untuk hari ini belum dijadwalkan atau Anda sedang salah hari.</p>
                        </div>
                    )}

                    {(!isBulkInputOpen && activeTab === 'schedules' && schedules.length === 0) && (
                        <div className="py-16 text-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl">
                            <Calendar size={40} className="mx-auto mb-3 opacity-40" />
                            <p className="font-medium">Belum ada jadwal</p>
                            <p className="text-sm mt-1">Tambahkan jadwal ujian per kelas</p>
                        </div>
                    )}

                    {!isBulkInputOpen && groupedSchedules.map((dayGroup) => (
                        <div key={dayGroup.date} className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
                            {/* Header Tanggal */}
                            <div className="bg-slate-800 p-4 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-lg bg-slate-700 flex flex-col items-center justify-center text-white">
                                        <span className="text-xs font-bold -mb-1">{new Date(dayGroup.date).toLocaleDateString('id-ID', { weekday: 'short' })}</span>
                                        <span className="text-sm font-black">{new Date(dayGroup.date).getDate()}</span>
                                    </div>
                                    <div>
                                        <h3 className="text-white font-bold text-lg leading-tight">{formatDate(dayGroup.date)}</h3>
                                        <p className="text-slate-400 text-xs">{dayGroup.sessions.length} Sesi Ujian</p>
                                    </div>
                                </div>
                            </div>

                            {/* Daftar Sesi dalam Tanggal tersebut */}
                            <div className="p-4 sm:p-6 space-y-6">
                                {dayGroup.sessions.map((session, sIdx) => (
                                    <div key={session.time} className="relative">
                                        {/* Connector line between sessions if not last */}
                                        {sIdx !== dayGroup.sessions.length - 1 && (
                                            <div className="absolute left-[5.5rem] top-10 bottom-[-1.5rem] w-px bg-slate-200 hidden sm:block" />
                                        )}
                                        
                                        <div className="flex flex-col sm:flex-row gap-4 sm:gap-6">
                                            {/* Jam Sesi */}
                                            <div className="sm:w-20 shrink-0 flex items-start sm:justify-end mt-1">
                                                <div className="flex items-center gap-2 text-slate-700 font-bold bg-slate-100 px-3 py-1.5 rounded-lg">
                                                    <Clock size={14} className="text-primary" />
                                                    {session.time}
                                                </div>
                                            </div>

                                            {/* Daftar Ujian di Sesi tersebut */}
                                            <div className="flex-1 space-y-3">
                                                {session.schedules.map((sc: any) => (
                                                    <div key={sc.id} className={`flex flex-col sm:flex-row gap-3 p-4 rounded-xl border transition-all ${
                                                        sc.status === 'active' ? 'bg-green-50 border-green-200 shadow-sm' : 
                                                        sc.status === 'finished' ? 'bg-slate-50 border-slate-100 opacity-70' : 
                                                        'bg-white border-slate-200 hover:border-primary/30 hover:shadow-md'
                                                    }`}>
                                                        <div className="flex items-start gap-3 flex-1 min-w-0">
                                                            <div className="pt-1">
                                                                <input type="checkbox" checked={selectedScheduleIds.includes(sc.id)} onChange={() => toggleScheduleSelect(sc.id)} className="w-4 h-4 rounded text-primary" />
                                                            </div>
                                                            <div className="flex-1 min-w-0">
                                                                <div className="flex items-center gap-2 mb-1 flex-wrap">
                                                                    <span className="font-bold text-slate-800 text-base">{getBankTitle(sc.bank_id, sc)}</span>
                                                                    <span className="px-2 py-0.5 bg-slate-100 text-slate-600 text-[10px] font-bold rounded-md">
                                                                        {sc.classes?.name || 'Semua Kelas'}
                                                                    </span>
                                                                    {sc.room && <span className="px-2 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-bold rounded-md">R. {sc.room}</span>}
                                                                </div>
                                                                
                                                                <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-slate-500">
                                                                    <span className="flex items-center gap-1.5"><Clock size={12}/> {sc.duration_minutes} mnt</span>
                                                                    <span className="flex items-center gap-1.5"><AlertTriangle size={12}/> Tutup {sc.window_end_time}</span>
                                                                </div>
                                                            </div>
                                                        </div>

                                                        {/* Status & Actions */}
                                                        <div className="flex sm:flex-col items-center sm:items-end justify-between sm:justify-center gap-2 shrink-0 border-t sm:border-t-0 sm:border-l border-slate-100 pt-3 sm:pt-0 sm:pl-4">
                                                            <div className="flex flex-col items-start sm:items-end gap-1">
                                                                <span className={`text-[10px] font-bold px-2.5 py-1 rounded-full uppercase tracking-wider ${
                                                                    sc.status === 'active' ? 'bg-green-100 text-green-700' : 
                                                                    sc.status === 'finished' ? 'bg-slate-200 text-slate-500' : 
                                                                    'bg-slate-100 text-slate-600'
                                                                }`}>
                                                                    {sc.status === 'scheduled' ? 'TERJADWAL' : sc.status === 'active' ? 'SEDANG UJIAN' : 'SELESAI'}
                                                                </span>
                                                                <div className="flex items-center gap-1 mt-0.5">
                                                                    {sc.exam_id ? (
                                                                        <span className="flex items-center gap-1 text-[10px] text-emerald-500 font-medium"><Check size={10}/> Siap Ujian</span>
                                                                    ) : (
                                                                        <span className="text-[10px] text-amber-500 font-medium italic">Belum digenerate</span>
                                                                    )}
                                                                </div>
                                                            </div>

                                                            {!period.is_locked && (
                                                                <button onClick={() => handleRemoveSchedule(sc.id)} className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-rose-500 hover:bg-rose-50 transition-all">
                                                                    <Trash2 size={14} />
                                                                </button>
                                                            )}
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}

                    {/* Bar Aksi Generate Ujian untuk jadwal yang di-check */}
                    {selectedScheduleIds.length > 0 && (
                        <div className="sticky bottom-4 flex items-center gap-3 p-4 bg-amber-50 border border-amber-200 shadow-xl rounded-xl mt-6 z-10">
                            <Zap size={20} className="text-amber-600 shrink-0" />
                            <div className="flex-1">
                                <p className="text-sm font-semibold text-amber-800">{selectedScheduleIds.length} jadwal dipilih</p>
                                <p className="text-xs text-amber-600">Akan dibuat record ujian untuk dikerjakan siswa</p>
                            </div>
                            <button onClick={handleGenerateExams} disabled={isGenerating} className="px-5 py-2.5 bg-amber-500 text-white text-xs font-bold rounded-lg hover:bg-amber-600 disabled:opacity-50 flex items-center gap-1.5 shadow-md">
                                {isGenerating ? <Loader2 size={13} className="animate-spin" /> : <Zap size={13} />}
                                {isGenerating ? 'Generating...' : 'Generate Ujian'}
                            </button>
                        </div>
                    )}
                </div>
            )}

            {/* ─── DETAIL TAB ─── */}
            {activeTab === 'detail' && (
                <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div>
                            <p className="text-xs text-slate-400 font-medium mb-1">Nama</p>
                            <p className="text-sm font-semibold text-slate-900">{period.name}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-400 font-medium mb-1">Tipe</p>
                            <p className="text-sm font-semibold text-slate-900 uppercase">{period.type}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-400 font-medium mb-1">Tahun Ajaran</p>
                            <p className="text-sm font-semibold text-slate-900">{period.school_year}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-400 font-medium mb-1">Semester</p>
                            <p className="text-sm font-semibold text-slate-900">{period.semester === 'ganjil' ? 'Ganjil' : 'Genap'}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-400 font-medium mb-1">Tanggal Mulai</p>
                            <p className="text-sm font-semibold text-slate-900">{formatDate(period.start_date)}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-400 font-medium mb-1">Tanggal Selesai</p>
                            <p className="text-sm font-semibold text-slate-900">{formatDate(period.end_date)}</p>
                        </div>
                    </div>
                    <div className="pt-4 border-t border-slate-100">
                        <p className="text-xs text-slate-400 font-medium mb-2">Status</p>
                        <span className={`px-3 py-1.5 text-xs font-bold rounded-full ${period.is_locked ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}>
                            {period.is_locked ? 'TERKUNCI' : 'AKTIF'}
                        </span>
                    </div>
                </div>
            )}

            {/* ─── ADD SCHEDULE MODAL ─── */}
            <AnimatePresence>
                {isAddScheduleOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/30" onClick={() => setIsAddScheduleOpen(false)} />
                        <motion.div initial={{ scale: 0.95 }} animate={{ scale: 1 }} exit={{ scale: 0.95 }} className="bg-white w-full max-w-md rounded-2xl p-6 relative z-10 max-h-[90vh] overflow-y-auto">
                            <button onClick={() => setIsAddScheduleOpen(false)} className="absolute top-4 right-4 text-slate-400"><X size={20} /></button>
                            <div className="flex items-center gap-3 mb-1">
                                <Calendar size={20} className="text-primary" />
                                <h3 className="text-lg font-semibold text-slate-900">Tambah Jadwal Ujian</h3>
                            </div>
                            <p className="text-xs text-slate-500 mb-5">Bank soal + kelas + waktu ujian</p>
                            <form onSubmit={handleAddSchedule} className="space-y-4">
                                <div>
                                    <label className="text-xs font-medium text-slate-600 mb-1.5 block">Bank Soal</label>
                                    <select required value={scheduleForm.bank_id} onChange={e => setScheduleForm(p => ({ ...p, bank_id: e.target.value }))} className="w-full border border-slate-200 rounded-xl p-3 text-sm">
                                        <option value="">Pilih Bank Soal</option>
                                        {qBanks.map((b: any) => (
                                            <option key={b.id} value={b.id}>{b.title} — {b.subject} ({b.question_count} soal)</option>
                                        ))}
                                    </select>
                                </div>
                                <div>
                                    <label className="text-xs font-medium text-slate-600 mb-1.5 block">Mata Pelajaran</label>
                                    <select required value={scheduleForm.subject_id} onChange={e => setScheduleForm(p => ({ ...p, subject_id: e.target.value }))} className="w-full border border-slate-200 rounded-xl p-3 text-sm">
                                        <option value="">Pilih Mata Pelajaran</option>
                                        {subjects.map((s: any) => (
                                            <option key={s.id} value={s.id}>{s.name}</option>
                                        ))}
                                    </select>
                                </div>
                                <div>
                                    <label className="text-xs font-medium text-slate-600 mb-1.5 block">Kelas ({scheduleForm.class_ids.length} dipilih)</label>
                                    <div className="flex flex-wrap gap-2 max-h-36 overflow-y-auto p-2 bg-slate-50 rounded-xl border border-slate-200">
                                        {classes.map((c: any) => (
                                            <button key={c.id} type="button" onClick={() => toggleClass(c.id)}
                                                className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all ${scheduleForm.class_ids.includes(c.id) ? 'bg-primary text-white border-primary' : 'bg-white text-slate-600 border-slate-200 hover:border-primary/40'}`}>
                                                {c.name}
                                            </button>
                                        ))}
                                        {classes.length === 0 && <p className="text-xs text-slate-400">Belum ada kelas</p>}
                                    </div>
                                </div>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className="text-xs font-medium text-slate-600 mb-1.5 block">Tanggal</label>
                                        <input type="date" required value={scheduleForm.scheduled_date} onChange={e => setScheduleForm(p => ({ ...p, scheduled_date: e.target.value }))} className="w-full border border-slate-200 rounded-xl p-3 text-sm" />
                                    </div>
                                    <div>
                                        <label className="text-xs font-medium text-slate-600 mb-1.5 block">Sesi Ujian</label>
                                        <select required value={scheduleForm.session_id} onChange={e => setScheduleForm(p => ({ ...p, session_id: e.target.value }))} className="w-full border border-slate-200 rounded-xl p-3 text-sm">
                                            <option value="">Pilih Sesi</option>
                                            {sessions.map((s: any) => (
                                                <option key={s.id} value={s.id}>{s.name} ({s.start_time.substring(0, 5)} - {s.end_time.substring(0, 5)})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                                <p className="text-xs text-slate-400 -mt-1">Siswa bebas buka kapan saja dalam window. Durasi mulai saat siswa klik mulai.</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    <div>
                                        <label className="text-xs font-medium text-slate-600 mb-1.5 block">Durasi (menit)</label>
                                        <input type="number" value={scheduleForm.duration_minutes} onChange={e => setScheduleForm(p => ({ ...p, duration_minutes: parseInt(e.target.value) }))} className="w-full border border-slate-200 rounded-xl p-3 text-sm" />
                                    </div>
                                    <div>
                                        <label className="text-xs font-medium text-slate-600 mb-1.5 block">Ruang (opsional)</label>
                                        <input type="text" value={scheduleForm.room} onChange={e => setScheduleForm(p => ({ ...p, room: e.target.value }))} placeholder="101" className="w-full border border-slate-200 rounded-xl p-3 text-sm" />
                                    </div>
                                </div>
                                <button type="submit" disabled={isSubmitting} className="w-full py-3 bg-primary text-white rounded-xl font-medium disabled:opacity-50 flex items-center justify-center gap-2">
                                    {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                                    {isSubmitting ? 'Menyimpan...' : `Simpan — ${scheduleForm.class_ids.length} kelas`}
                                </button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* ─── ROOM & SESSION MANAGEMENT MODAL ─── */}
            <AnimatePresence>
                {isRoomManagementOpen && orgId && (
                    <RoomManagementModal
                        period={period}
                        orgId={orgId}
                        onClose={() => {
                            setIsRoomManagementOpen(false);
                            loadData(); // Reload sessions in case they changed
                        }}
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";
import React, { useEffect, useState, useMemo } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Loader2, ArrowLeft, Save, User, CheckCircle2,
    Shield, Clock, Calendar, BarChart3, AlertTriangle,
    CheckCircle, XCircle, HelpCircle, Activity,
    Link as LinkIcon, ExternalLink, RotateCcw, MousePointerClick
} from 'lucide-react';
import { getAttemptFullDetailsAction } from '@/lib/api/proctor';
import { submitEssayGrades } from '@/lib/api/teachers';
import { resetExamAttempt } from '@/lib/api/proctoring';
import { QuestionRenderer } from '@/app/components/questions/QuestionRenderer';
import { LatexRenderer } from '@/app/components/questions/LatexRenderer';
import { useMemoryState } from '@/lib/useMemoryState';

export default function AttemptAnalyticsPage() {
    const params = useParams();
    const router = useRouter();
    const attemptId = params.attemptId as string;

    // Key cache HARUS memuat attemptId — key statis membuat detail siswa B
    // menampilkan data siswa A yang ter-cache saat berpindah antar attempt.
    // Prefix admin_ agar tidak berbagi cache dengan halaman proktor.
    const [loading, setLoading] = useMemoryState(`admin_monitoring_${attemptId}_loading`, true);
    const [submitting, setSubmitting] = useState(false);
    const [resetting, setResetting] = useState(false);
    const [data, setData] = useMemoryState<any>(`admin_monitoring_${attemptId}_data`, null);
    const [grades, setGrades] = useState<Record<string, number>>({});
    const [activeTab, setActiveTab] = useState<'questions' | 'security'>('questions');

    useEffect(() => {
        async function load() {
            setLoading(true);
            const res = await getAttemptFullDetailsAction(attemptId);
            if (res) {
                setData(res);
                const initialGrades: Record<string, number> = {};
                res.answers.forEach((a: any) => {
                    if (['essay', 'esay', 'uraian'].includes(a.bank_questions?.type)) {
                        initialGrades[a.id] = a.score || 0;
                    }
                });
                setGrades(initialGrades);
            }
            setLoading(false);
        }
        load();
    }, [attemptId]);

    const handleGradeChange = (answerId: string, val: string) => {
        setGrades(prev => ({
            ...prev,
            [answerId]: parseFloat(val) || 0
        }));
    };

    const handleResetAttempt = async () => {
        if (!confirm(
            `Yakin ingin mereset ujian siswa "${studentName}"?\n\n` +
            `Siswa akan bisa melanjutkan ujian dengan jawaban yang sudah tersimpan sebelumnya.\n\n` +
            `Peringatan: Pastikan perangkat siswa sudah dalam kondisi baik.`
        )) return;

        setResetting(true);
        const res = await resetExamAttempt(attemptId);
        if (res.success) {
            alert(`Ujian "${studentName}" berhasil di-reset.`);
            router.push('/dashboard/admin/monitoring');
        } else {
            alert('Gagal mereset: ' + res.error);
        }
        setResetting(false);
    };

    const handleSave = async () => {
        if (!confirm('Simpan perubahan nilai? Total nilai akhir akan dihitung kembali.')) return;
        setSubmitting(true);
        const res = await submitEssayGrades(attemptId, grades);
        if (res.success) {
            alert('Berhasil menyimpan nilai!');
            // Reload data
            const updated = await getAttemptFullDetailsAction(attemptId);
            if (updated) setData(updated);
        } else {
            alert('Gagal: ' + res.error);
        }
        setSubmitting(false);
    };

    const stats = useMemo(() => {
        if (!data) return null;
        const total = data.answers.length;
        const correct = data.answers.filter((a: any) => a.is_correct).length;
        const wrong = total - correct - data.answers.filter((a: any) => ['essay', 'esay', 'uraian'].includes(a.bank_questions?.type)).length;
        const essays = data.answers.filter((a: any) => ['essay', 'esay', 'uraian'].includes(a.bank_questions?.type)).length;

        return { total, correct, wrong, essays };
    }, [data]);

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-screen">
                <Loader2 size={48} className="text-[#030C4D] animate-spin" />
            </div>
        );
    }

    if (!data) {
        return (
            <div className="py-20 text-center bg-white border border-[#030C4D]/20 rounded-lg shadow-sm">
                <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-4">
                    <AlertTriangle size={24} />
                </div>
                <h3 className="text-lg font-bold text-slate-800 mb-1">Data Tidak Ditemukan</h3>
                <p className="text-slate-500 text-sm mb-6">Kami tidak dapat menemukan rekaman pengerjaan untuk ID tersebut.</p>
                <button onClick={() => router.back()} className="px-6 py-2.5 bg-[#030C4D] hover:bg-[#1a246b] text-white rounded-lg text-sm font-semibold transition-all">
                    Kembali Ke Monitoring
                </button>
            </div>
        );
    }

    const { attempt, answers, securityLogs } = data;
    const studentName = attempt.profiles?.full_name || 'Tanpa Nama';
    const examTitle = attempt.exams?.title || 'Ujian';

    return (
        <div className="max-w-7xl mx-auto pb-24">
            {/* Header Area */}
            <div className="relative overflow-hidden rounded-lg acca-hero-gradient mb-6 shadow-xl shadow-[#0038A8]/20">
                <div className="absolute -top-12 -right-12 w-72 h-72 bg-[#0038A8]/10 rounded-full blur-3xl" />
                <div className="absolute -bottom-12 -left-12 w-56 h-56 bg-white/5 rounded-full blur-2xl" />

                <div className="relative px-8 py-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                    <div>
                        <button
                            onClick={() => router.back()}
                            className="group flex items-center gap-2 text-white hover:text-white transition-all text-xs font-semibold mb-3"
                        >
                            <ArrowLeft size={14} className="group-hover:-translate-x-1 transition-transform" /> Kembali ke Monitor
                        </button>
                        <h1 className="text-xl md:text-2xl font-bold text-white mb-2 flex flex-wrap items-center gap-3">
                            Detail Analitik <span className="px-2.5 py-1 bg-white/20 border border-white/30 text-white rounded text-xs">ID: {attempt.id.split('-')[0]}</span>
                        </h1>
                        <p className="text-white text-sm flex flex-wrap items-center gap-2">
                            <User size={14} /> {studentName} <span className="mx-1">•</span> <Activity size={14} /> {examTitle}
                        </p>
                    </div>

                    <div className="flex flex-col sm:flex-row items-end gap-3">
                        {['auto_submitted', 'submitted'].includes(attempt.status) && (
                            <button
                                onClick={handleResetAttempt}
                                disabled={resetting}
                                className="px-4 py-2 bg-amber-500 hover:bg-amber-600 text-white rounded-lg text-sm font-semibold flex items-center gap-2 transition-all shadow-sm"
                            >
                                {resetting ? <Loader2 size={16} className="animate-spin" /> : <RotateCcw size={16} />}
                                Reset Ujian
                            </button>
                        )}
                        {attempt.needs_manual_grading && (
                            <div className="px-4 py-2 bg-white/20 border border-white/40 text-white rounded-lg text-sm font-semibold flex items-center gap-2 animate-pulse">
                                <AlertTriangle size={16} /> Menunggu Penilaian Uraian
                            </div>
                        )}
                        {Object.keys(grades).length > 0 && (
                            <button
                                onClick={handleSave}
                                disabled={submitting}
                                className="bg-[#0038A8] hover:bg-[#0038A8] text-white font-semibold px-5 py-2.5 rounded-lg flex items-center gap-2 transition-all shadow-lg shadow-[#0038A8]/20 disabled:opacity-50 text-sm"
                            >
                                {submitting ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                                Simpan Perubahan
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                {/* Score Card */}
                <div className="bg-white p-5 rounded-lg border border-[#030C4D]/20 shadow-sm relative overflow-hidden">
                    <div className="flex justify-between items-start mb-2">
                        <span className="text-sm font-bold text-slate-500">Nilai Akhir</span>
                        <div className="w-8 h-8 bg-[#030C4D]/10 rounded-lg flex items-center justify-center text-[#030C4D]">
                            <BarChart3 size={16} />
                        </div>
                    </div>
                    <div className="flex items-baseline gap-1">
                        <span className="text-3xl font-bold text-[#0038A8]">
                            {Number(attempt.total_score || 0).toFixed(0)}
                        </span>
                        <span className="text-sm font-semibold text-slate-400">/100</span>
                    </div>
                    <div className="mt-3 flex items-center gap-2">
                        <div className="flex-1 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                            <motion.div
                                initial={{ width: 0 }}
                                animate={{ width: `${Number(attempt.total_score || 0)}%` }}
                                transition={{ duration: 1.5, ease: "easeOut" }}
                                className="h-full bg-[#030C4D]"
                            />
                        </div>
                        <span className="text-xs font-bold text-[#030C4D]">{Number(attempt.total_score || 0).toFixed(1)}%</span>
                    </div>
                </div>

                {/* Timing Info */}
                <div className="bg-white p-5 rounded-lg border border-[#030C4D]/20 shadow-sm relative overflow-hidden">
                    <div className="flex justify-between items-start mb-4">
                        <span className="text-sm font-bold text-slate-500">Waktu</span>
                        <div className="w-8 h-8 bg-[#0038A8]/10 rounded-lg flex items-center justify-center text-[#0038A8]">
                            <Clock size={16} />
                        </div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500 font-medium">Mulai</span>
                            <span className="font-bold text-slate-700">
                                {attempt.started_at ? new Date(attempt.started_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-'}
                            </span>
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500 font-medium">Selesai</span>
                            <span className="font-bold text-slate-700">
                                {attempt.finished_at ? new Date(attempt.finished_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-'}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Security Shield */}
                <div className="bg-white p-5 rounded-lg border border-[#030C4D]/20 shadow-sm relative overflow-hidden">
                    <div className="flex justify-between items-start mb-2">
                        <span className="text-sm font-bold text-slate-500">Keamanan</span>
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${attempt.warning_count > 0 ? 'bg-red-100 text-red-500' : 'bg-emerald-100 text-emerald-600'}`}>
                            <Shield size={16} />
                        </div>
                    </div>
                    <div className="flex items-baseline gap-2 mb-2">
                        <span className="text-2xl font-bold text-slate-800">{attempt.warning_count || 0}</span>
                        <span className="text-xs font-semibold text-slate-400">pelanggaran</span>
                    </div>
                    <div className="flex items-center gap-1">
                        {Array.from({ length: 3 }).map((_, i) => (
                            <div
                                key={i}
                                className={`h-1.5 flex-1 rounded-full ${i < (attempt.warning_count || 0) ? 'bg-red-500' : 'bg-slate-100'}`}
                            />
                        ))}
                    </div>
                </div>

                {/* Answer Summary */}
                <div className="bg-white p-5 rounded-lg border border-[#030C4D]/20 shadow-sm relative overflow-hidden">
                    <div className="flex justify-between items-start mb-4">
                        <span className="text-sm font-bold text-slate-500">Statistik Jawaban</span>
                        <div className="w-8 h-8 bg-[#030C4D]/10 rounded-lg flex items-center justify-center text-[#030C4D]">
                            <Activity size={16} />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-y-3 gap-x-2">
                        <div>
                            <p className="text-lg font-bold text-emerald-600 leading-none mb-0.5">{stats?.correct}</p>
                            <p className="text-[10px] text-slate-400 uppercase font-bold">Benar</p>
                        </div>
                        <div>
                            <p className="text-lg font-bold text-red-500 leading-none mb-0.5">{stats?.wrong}</p>
                            <p className="text-[10px] text-slate-400 uppercase font-bold">Salah</p>
                        </div>
                        <div>
                            <p className="text-lg font-bold text-[#0038A8] leading-none mb-0.5">{stats?.essays}</p>
                            <p className="text-[10px] text-slate-400 uppercase font-bold">Esai</p>
                        </div>
                        <div>
                            <p className="text-lg font-bold text-[#030C4D] leading-none mb-0.5">{stats?.total}</p>
                            <p className="text-[10px] text-slate-400 uppercase font-bold">Total</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Content Tabs */}
            <div className="space-y-4">
                <div className="flex gap-1 bg-white border border-[#0038A8]/30 p-1 rounded-lg w-fit shadow-sm">
                    <button
                        onClick={() => setActiveTab('questions')}
                        className={`relative flex items-center gap-2 px-6 py-2 rounded-lg text-xs font-bold transition-all ${
                            activeTab === 'questions' ? 'bg-[#030C4D] text-white shadow-sm' : 'text-slate-500 hover:text-slate-800 hover:bg-slate-50'
                        }`}
                    >
                        <BarChart3 size={14} /> Analisis Jawaban
                    </button>
                    <button
                        onClick={() => setActiveTab('security')}
                        className={`relative flex items-center gap-2 px-6 py-2 rounded-lg text-xs font-bold transition-all ${
                            activeTab === 'security' ? 'bg-red-50 text-red-600 shadow-sm border border-red-100' : 'text-slate-500 hover:text-slate-800 hover:bg-slate-50'
                        }`}
                    >
                        <Shield size={14} /> Log Keamanan
                        {securityLogs.length > 0 && (
                            <span className="ml-1 w-4 h-4 bg-red-500 text-white text-[9px] rounded-full flex items-center justify-center animate-pulse">
                                {securityLogs.length}
                            </span>
                        )}
                    </button>
                </div>

                <div className="bg-white border border-[#030C4D]/20 rounded-lg p-6 lg:p-8 shadow-sm">
                    <AnimatePresence mode="wait">
                        {activeTab === 'questions' && (
                            <motion.div key="questions" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="space-y-8">
                                {answers.map((answer: any, index: number) => {
                                    const q = answer.bank_questions;
                                    if (!q) return null;
                                    const isEssay = ['essay', 'esay', 'uraian'].includes(q.type);

                                    return (
                                        <div key={answer.id} className="relative flex gap-4 md:gap-6">
                                            {index < answers.length - 1 && (
                                                <div className="absolute top-10 bottom-0 left-[19px] w-0.5 bg-slate-100 z-0" />
                                            )}

                                            {/* Status Marker */}
                                            <div className="relative z-10 flex flex-col items-center shrink-0">
                                                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-4 border-white shadow-sm transition-all
                                                    ${isEssay
                                                        ? (answer.needs_manual_grading ? 'bg-[#0038A8] text-white' : 'bg-[#030C4D] text-white')
                                                        : (answer.is_correct ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white')
                                                    }`}>
                                                    {isEssay
                                                        ? (answer.needs_manual_grading ? <HelpCircle size={16} /> : <CheckCircle size={16} />)
                                                        : (answer.is_correct ? <CheckCircle size={16} /> : <XCircle size={16} />)
                                                    }
                                                </div>
                                                <span className="mt-2 text-[10px] font-bold text-slate-400">#{index + 1}</span>
                                            </div>

                                            {/* Card Content */}
                                            <div className="flex-1 bg-slate-50 border border-slate-200 rounded-lg p-4 md:p-6 hover:border-[#030C4D]/30 transition-colors">
                                                <div className="flex flex-wrap gap-4 justify-between items-center mb-4 pb-4 border-b border-slate-200">
                                                    <div className="flex gap-2">
                                                        <span className="px-2.5 py-1 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-500">
                                                            {q.type.toUpperCase()}
                                                        </span>
                                                        <span className="px-2.5 py-1 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-500">
                                                            Max: {q.score_default || 1} Pts
                                                        </span>
                                                    </div>
                                                    <div className="flex items-center gap-2">
                                                        <span className="text-xs font-semibold text-slate-500">Points:</span>
                                                        <span className={`text-lg font-bold ${answer.is_correct ? 'text-emerald-600' : (answer.score > 0 ? 'text-amber-500' : (isEssay ? 'text-[#0038A8]' : 'text-red-500'))}`}>
                                                            {isEssay ? (Number(grades[answer.id]) || answer.score || 0) : (answer.score ?? (answer.is_correct ? q.score_default : 0))}
                                                        </span>
                                                    </div>
                                                </div>


                                                <div className="bg-white p-4 rounded border border-slate-200 shadow-sm">
                                                    <QuestionRenderer
                                                        question={q}
                                                        answer={q.type === 'mcq' ? answer.selected_option_id : answer.essay_answer}
                                                        onAnswerChange={() => { }} // Read-only
                                                        showFeedback={true}
                                                    />
                                                </div>

                                                {/* Essay Grading UI */}
                                                {isEssay && (
                                                    <div className="bg-white border-2 border-dashed border-[#0038A8]/40 rounded-lg p-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                                                        <div className="flex items-start sm:items-center gap-3 text-[#0038A8]">
                                                            <div className="w-8 h-8 bg-[#0038A8]/10 rounded flex items-center justify-center shrink-0">
                                                                <BarChart3 size={16} />
                                                            </div>
                                                            <div>
                                                                <h4 className="text-sm font-bold text-slate-800">Penilaian Manual</h4>
                                                                <p className="text-xs text-slate-500">Masukkan poin untuk jawaban esai ini</p>
                                                            </div>
                                                        </div>
                                                        <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-lg border border-slate-200">
                                                            <input
                                                                type="number"
                                                                min="0"
                                                                max={q.score_default || 1}
                                                                step="0.5"
                                                                value={grades[answer.id] === undefined ? 0 : grades[answer.id]}
                                                                onChange={(e) => handleGradeChange(answer.id, e.target.value)}
                                                                className="w-16 bg-white border border-slate-300 focus:border-[#030C4D] rounded px-2 py-1.5 text-center text-sm font-bold text-slate-800 outline-none"
                                                            />
                                                            <span className="text-slate-400 font-bold text-sm pr-2">/ {q.score_default || 1}</span>
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </motion.div>
                        )}

                        {activeTab === 'security' && (
                            <motion.div key="security" initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }} className="space-y-6">
                                <div className="p-6 bg-red-50 border border-red-100 rounded-lg flex flex-col sm:flex-row items-center gap-4 text-center sm:text-left">
                                    <div className="w-12 h-12 bg-red-500 text-white rounded-lg flex items-center justify-center shadow-lg shadow-red-500/20 shrink-0">
                                        <Shield size={24} />
                                    </div>
                                    <div className="flex-1">
                                        <h3 className="text-lg font-bold text-red-900">Security Audit Trail</h3>
                                        <p className="text-sm text-red-700">Log aktivitas pelanggaran sistem keamanan.</p>
                                    </div>
                                    <div className="sm:ml-auto">
                                        <p className="text-3xl font-black text-red-600 leading-none mb-1">{securityLogs.length}</p>
                                        <p className="text-[10px] font-bold text-red-500 uppercase tracking-wider">Total Event</p>
                                    </div>
                                </div>

                                {securityLogs.length === 0 ? (
                                    <div className="py-16 text-center">
                                        <div className="w-16 h-16 bg-emerald-50 border border-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4">
                                            <CheckCircle size={32} />
                                        </div>
                                        <h4 className="text-lg font-bold text-slate-800">Aman Terkendali</h4>
                                        <p className="text-slate-500 text-sm">Tidak ada pelanggaran yang tercatat untuk siswa ini.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-3">
                                        {securityLogs.map((log: any) => (
                                            <div key={log.id} className="flex items-center gap-4 p-4 bg-white border border-slate-200 rounded-lg hover:border-red-300 transition-colors">
                                                <div className="w-10 h-10 bg-red-50 rounded-lg flex items-center justify-center text-red-500 shrink-0">
                                                    {log.event_type === 'tab_close' ? <MousePointerClick size={18} /> : <AlertTriangle size={18} />}
                                                </div>
                                                <div className="flex-1">
                                                    <p className="text-sm font-bold text-slate-800 uppercase tracking-tight">{log.event_type.replace('_', ' ')}</p>
                                                    <p className="text-xs font-medium text-slate-500 mt-0.5">
                                                        {new Date(log.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                                                    </p>
                                                </div>
                                                {(log.metadata?.duration || log.metadata?.duration_seconds) && (
                                                    <span className="px-3 py-1 bg-amber-50 text-amber-600 border border-amber-100 rounded text-xs font-bold whitespace-nowrap">
                                                        Ditutup {log.metadata?.duration || log.metadata?.duration_seconds}s
                                                    </span>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            {/* Bottom Actions */}
            <div className="mt-8 bg-white border border-[#030C4D]/20 p-6 rounded-lg shadow-sm flex flex-col sm:flex-row justify-between items-center gap-4">
                <div>
                    <h4 className="text-sm font-bold text-slate-800 mb-1">Aksi Halaman</h4>
                    <p className="text-xs text-slate-500">Pastikan untuk menyimpan jika ada perubahan nilai uraian.</p>
                </div>
                <div className="flex gap-3 w-full sm:w-auto">
                    <button
                        onClick={() => router.back()}
                        className="flex-1 sm:flex-none px-6 py-2.5 bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200 rounded-lg font-semibold transition-all text-sm text-center"
                    >
                        Kembali
                    </button>
                    {Object.keys(grades).length > 0 && (
                        <button
                            onClick={handleSave}
                            disabled={submitting}
                            className="flex-1 sm:flex-none bg-[#030C4D] hover:bg-[#1a246b] text-white font-semibold px-6 py-2.5 rounded-lg transition-all shadow-md active:scale-95 text-sm flex items-center justify-center gap-2"
                        >
                            {submitting ? <Loader2 size={16} className="animate-spin" /> : <CheckCircle2 size={16} />}
                            Simpan Perubahan
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
}

