                                                        <span className="text-sm font-semibold text-slate-800">{s.name}</span>
                                                        <span className="text-xs text-slate-500">NISN: <span className="font-mono">{s.identity_number || '-'}</span></span>
                                                    </div>
                                                </div>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
}

