        bank_id: '', class_ids: [] as string[],
        scheduled_date: '', scheduled_time: '', window_end_time: ''
    });
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        examType: 'daily' as 'daily' | 'pas' | 'pat' | 'assignment' | 'lainnya',
        duration: 60,
