        bankId: '',
        startTime: '',
        endTime: '',
        selectedClassIds: [] as string[],
        scoringTypes: ['classical'] as string[],
        isForever: false,
        isPublic: false,
        documentUrl: '',
        videoUrl: '',
        // Assignment-specific fields
        assignmentDescription: '',
        allowFileUpload: false,
        allowedFileTypes: ['pdf'] as string[],
        requireBank: true,
