                    setQBanks(bankList || []);
                    setClasses(classList || []);
                    setExamConfigs(pasPeriodList || []);
                    setConfigBanks(bankList || []);
                    setClasses(classList || []);
                    setLabels(labelList || []);
                    setSubjects(subjectList || []);
                    setSchoolYears(schoolYearList || []);
                    setExamAssignments(assignmentMap);

