"use client";
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
    ClipboardCheck, Users, Clock, BookOpen, CheckCircle2,
    ArrowRight, Activity, Layers, Eye, ChevronRight, AlertCircle
} from 'lucide-react';
import { listOrganizationExams, getRecentLogins, getProctorOrganization } from '@/lib/api/proctor';
import { getGuruOrganizationStats } from '@/lib/api/teachers';
import { getSetting, pickAnnouncements, type Announcement } from '@/lib/api/settings';
import { getSessionUser } from '@/lib/session';
import { REFRESH_INTERVAL, useAutoRefresh } from '@/lib/useAutoRefresh';
import { useRouter } from 'next/navigation';
import { RecentLoginsCard } from '../proktor/RecentLoginsCard';
import { useMemoryState } from '@/lib/useMemoryState';
import { linkifyText } from '@/lib/text-format';

export default function GuruDashboard() {
    const router = useRouter();
    const [org, setOrg] = useState<any>(null);
    const [stats, setStats] = useMemoryState('guru_stats', {
        totalMembers: 0,
        totalBanks: 0,
        ongoingExams: 0,
        draftExams: 0,
        finishedExams: 0
    });
    const [exams, setExams] = useMemoryState<any[]>('guru_dashboard_exams', []);
    const [logins, setLogins] = useMemoryState<any[]>('guru_logins', []);
    const [loading, setLoading] = useMemoryState('guru_loading', true);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);
    const [announcements, setAnnouncements] = useMemoryState<any[]>('guru_announcements', []);
    const [showAnnouncementsPopup, setShowAnnouncementsPopup] = useState(false);
    const [showMembersModal, setShowMembersModal] = useState(false);
    const [membersList, setMembersList] = useState<any[]>([]);
    const [membersLoading, setMembersLoading] = useState(false);
    const [fullName, setFullName] = useState<string>('');

    const loadData = useCallback(async () => {
        try {
            const user = await getSessionUser();

            const organization = user ? await getProctorOrganization() : null;

            if (!organization) {
                setErrorMsg('Organisasi tidak ditemukan. Silakan hubungi admin.');
                setLoading(false);
                return;
            }

            const orgId = organization.id;
            setOrg({ id: organization.id, name: organization.name });

            const [statData, examData, loginData, announcementConfig] = await Promise.all([
                getGuruOrganizationStats(orgId),
                listOrganizationExams(orgId),
                getRecentLogins(orgId, 10),
                getSetting<Announcement | Announcement[]>('announcement_config'),
            ]);
            setStats(statData);
            // Guru cannot see ASAS/ASAT exams
            setExams((examData || []).filter((e: any) => e.exam_type !== 'pas' && e.exam_type !== 'pat'));
            setLogins(loginData);
            
            setFullName(user?.fullName ?? '');
            
            setAnnouncements(pickAnnouncements(announcementConfig, 'show_proktor'));
        } catch (error: any) {
            console.error('Load data error:', error);
            setErrorMsg(error.message || 'Terjadi kesalahan saat memuat data');
        } finally {
            setLoading(false);
        }
    }, [router]);

    useAutoRefresh(loadData, REFRESH_INTERVAL.dashboard);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const getDay = () => {
        const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
        const now = new Date();
        return `${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]} ${now.getFullYear()}`;
    };

    const openMembers = async () => {
        if (!org?.id) return;
        setShowMembersModal(true);
        setMembersLoading(true);
        try {
            const all = await getRecentLogins(org.id, 500);
            setMembersList((all || []).filter((m: any) => m.lastLoginAt));
        } catch (e) {
            console.error('Load members error:', e);
            setMembersList([]);
        } finally {
            setMembersLoading(false);
        }
    };

    const formatLoginTime = (iso: string | null) => {
        if (!iso) return '-';
        try {
            return new Date(iso).toLocaleString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
        } catch { return '-'; }
    };

    const statCards = [
        {
            label: 'Total Anggota',
            value: stats.totalMembers,
            icon: Users,
            gradient: 'from-[#030C4D] to-[#1a246b]',
            iconBg: 'bg-[#030C4D]/10',
            iconColor: 'text-[#030C4D]',
            borderColor: 'border-[#030C4D]/40',
            valueColor: 'text-[#0038A8]',
            description: 'Guru & Siswa aktif',
            onClick: openMembers,
        },
        {
            label: 'Bank Soal Anda',
            value: stats.totalBanks,
            icon: BookOpen,
            gradient: 'from-[#0038A8] to-[#0038A8]',
            iconBg: 'bg-[#030C4D]/10',
            iconColor: 'text-[#030C4D]',
            borderColor: 'border-[#030C4D]/40',
            valueColor: 'text-[#0038A8]',
            description: 'Koleksi bank soal Anda',
            onClick: () => router.push('/dashboard/guru/questions'),
        },
        {
            label: 'Ujian Mendatang',
            value: stats.draftExams,
            icon: Layers,
            gradient: 'from-[#030C4D] to-[#1a246b]',
            iconBg: 'bg-[#030C4D]/10',
            iconColor: 'text-[#030C4D]',
            borderColor: 'border-[#030C4D]/40',
            valueColor: 'text-[#0038A8]',
            description: 'Ujian terjadwal',
            onClick: () => router.push('/dashboard/guru/exams'),
        },
        {
            label: 'Ujian Aktif',
            value: stats.ongoingExams,
            icon: Clock,
            gradient: 'from-[#0038A8] to-[#0038A8]',
            iconBg: 'bg-[#030C4D]/10',
            iconColor: 'text-[#030C4D]',
            borderColor: 'border-[#030C4D]/40',
            valueColor: 'text-[#0038A8]',
            description: 'Sedang berlangsung',
            onClick: () => router.push('/dashboard/guru/exams'),
        },
        {
            label: 'Selesai',
            value: stats.finishedExams,
            icon: CheckCircle2,
            gradient: 'from-[#030C4D] to-[#020510]',
            iconBg: 'bg-[#030C4D]/10',
            iconColor: 'text-[#030C4D]',
            borderColor: 'border-[#030C4D]/40',
            valueColor: 'text-[#0038A8]',
            description: 'Telah selesai dikerjakan',
            onClick: () => router.push('/dashboard/guru/exams'),
        },
    ];

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[60vh]">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#030C4D]"></div>
            </div>
        );
    }

    if (errorMsg) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh]">
                <div className="p-4 bg-red-50 text-red-600 rounded-lg max-w-md w-full border border-red-200">
                    <h3 className="font-bold mb-2 flex items-center gap-2">
                        <AlertCircle size={20} />
                        Gagal Memuat Dashboard
                    </h3>
                    <p className="text-sm">{errorMsg}</p>
                    <button onClick={() => window.location.reload()} className="mt-4 px-4 py-2 bg-red-100 hover:bg-red-200 rounded text-sm font-semibold transition-colors">
                        Coba Lagi
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-7xl mx-auto pb-24">

            {/* ── Hero Header ── */}
            <div className="relative overflow-hidden rounded-lg acca-hero-gradient mb-8 shadow-xl shadow-[#0038A8]/20">
                <div className="absolute -top-12 -right-12 w-72 h-72 bg-[#0038A8]/10 rounded-full blur-3xl" />
                <div className="absolute -bottom-12 -left-12 w-56 h-56 bg-white/5 rounded-full blur-2xl" />

                <div className="relative px-8 py-6 flex flex-col md:flex-row md:items-center md:justify-between gap-6">
                    <div>
                        <h1 className="text-xl md:text-2xl font-bold text-white mb-2">
                            Selamat datang, <span className="text-white font-bold">{fullName || 'Guru'}</span>
                        </h1>
                        <p className="text-white text-sm max-w-xl">
                            {org?.name || 'Dashboard Guru'} • {getDay()}
                        </p>
                    </div>
                </div>
            </div>

            {/* ── Stats Grid ── */}
            <div className="grid grid-cols-2 md:grid-cols-5 gap-x-2 mb-8">
                {statCards.map((item, i) => (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: i * 0.06, duration: 0.4 }}
                        whileTap={{ scale: 0.97 }}
                        key={i}
                        role="button"
                        tabIndex={0}
                        aria-label={`${item.label}: ${item.value} — ${item.description}`}
                        onClick={() => item.onClick?.()}
                        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); item.onClick?.(); } }}
                        className="group relative bg-white rounded-lg px-4 py-4 border border-[#030C4D]/20 hover:border-[#030C4D] hover:shadow-lg hover:shadow-[#030C4D]/10 transition-all duration-300 cursor-pointer overflow-hidden text-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#030C4D] focus-visible:ring-offset-2"
                    >
                        <div className={`absolute top-0 left-0 right-0 h-1 bg-gradient-to-r ${item.gradient} opacity-0 group-hover:opacity-100 transition-opacity duration-300`} />
                        <ChevronRight size={14} className="absolute top-2.5 right-2.5 text-[#030C4D]/0 group-hover:text-[#030C4D]/40 transition-colors duration-300" />

                        <div className="relative flex flex-col items-center">
                            <div className="flex items-center gap-2 mb-3">
                                <div className={`w-8 h-8 ${item.iconBg} rounded-lg flex items-center justify-center ${item.borderColor} group-hover:scale-110 transition-transform duration-300`}>
                                    <item.icon size={16} className={item.iconColor} />
                                </div>
                                <p className="text-sm font-semibold text-slate-700">{item.label}</p>
                            </div>
                            <div className="space-y-0.5">
                                <p className={`text-3xl font-extrabold ${item.valueColor} leading-none tabular-nums tracking-tight`}>{(item.value ?? 0).toLocaleString('id-ID')}</p>
                                <p className="text-xs text-slate-400">{item.description}</p>
                            </div>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* ── Layout: Ujian (3 card width) dan Ringkasan (2 card width) ── */}
            <div className="grid grid-cols-1 md:grid-cols-5 gap-4">

                {/* ── Left: Exam List (3/5 width) ── */}
                <div className="md:col-span-3 bg-white rounded-lg border border-[#0038A8]/30 overflow-hidden shadow-sm">
                    <div className="px-6 py-4 border-b border-[#0038A8]/20 bg-gradient-to-r from-[#030C4D]/[.02] to-transparent">
                        <div>
                            <h2 className="text-base font-bold text-slate-900">Ujian</h2>
                            <p className="text-xs text-slate-400 mt-0.5">{exams.length} total ujian</p>
                        </div>
                    </div>

                    {exams.length > 0 ? (
                        <div className="divide-y divide-slate-50">
                            {exams.slice(0, 6).map((exam, idx) => {
                                const isPublished = !!exam.is_published;
                                const isDraft = !isPublished;
                                const now = new Date();
                                const isFinished = exam.status === 'finished' ||
                                    (isPublished && exam.status === 'active' && exam.end_time && new Date(exam.end_time) < now);
                                const isOngoing = isPublished && exam.status === 'active' &&
                                    (!exam.start_time || new Date(exam.start_time) <= now) &&
                                    (!exam.end_time || new Date(exam.end_time) >= now);

                                return (
                                    <motion.div
                                        initial={{ opacity: 0, x: -10 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        transition={{ delay: idx * 0.05 }}
                                        key={exam.id}
                                        className="group px-6 py-4 flex items-center gap-4 hover:bg-slate-50/80 transition-colors cursor-pointer"
                                        onClick={() => router.push('/dashboard/guru/monitoring?exam=' + exam.id)}
                                    >
                                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 transition-all ${
                                            isOngoing
                                                ? 'bg-[#0038A8]/10 group-hover:bg-[#0038A8]/15'
                                                : isPublished
                                                ? 'bg-[#030C4D]/10 group-hover:bg-[#030C4D]/15'
                                                : 'bg-slate-50 group-hover:bg-slate-100'
                                        }`}>
                                            <ClipboardCheck size={18} className={
                                                isOngoing ? 'text-[#0038A8]'
                                                : isPublished ? 'text-[#030C4D]' : 'text-slate-400'
                                            } />
                                        </div>

                                        <div className="flex-1 min-w-0">
                                            <p className="text-sm font-semibold text-slate-800 truncate group-hover:text-[#030C4D] transition-colors">{exam.title}</p>
                                            <div className="flex flex-wrap items-center gap-2 mt-1.5">
                                                <span className="text-[11px] font-medium text-slate-600 flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                                                    <Clock size={12} />
                                                    {exam.duration_minutes} mnt
                                                </span>
                                                {exam.exam_type && exam.exam_type !== 'daily' && (
                                                    <span className="text-[10px] text-[#030C4D] font-bold bg-[#030C4D]/10 px-2 py-1 rounded-md">
                                                        {exam.exam_type.toUpperCase()}
                                                    </span>
                                                )}
                                                {exam.start_time && (
                                                    <span className="text-[11px] font-medium text-slate-600 bg-slate-100 px-2 py-1 rounded-md whitespace-nowrap">
                                                        {new Date(exam.start_time).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })} • {new Date(exam.start_time).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                                    </span>
                                                )}
                                            </div>
                                        </div>

                                        <div className="shrink-0 flex flex-col items-end justify-center">
                                            <div className="flex items-center gap-3">
                                                <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                                                    isOngoing
                                                        ? 'bg-[#0038A8]/10 text-[#0038A8] border-[#0038A8]/30'
                                                        : isDraft
                                                        ? 'bg-[#030C4D]/5 text-[#030C4D] border-[#030C4D]/20'
                                                        : isFinished
                                                        ? 'bg-emerald-100 text-emerald-700 border-emerald-200'
                                                        : 'bg-[#030C4D]/10 text-[#030C4D] border-[#030C4D]/20'
                                                }`}>
                                                    <span className={`w-1.5 h-1.5 rounded-full ${
                                                        isOngoing ? 'bg-[#0038A8] animate-pulse'
                                                        : isDraft ? 'bg-[#030C4D]'
                                                        : isFinished ? 'bg-emerald-500' : 'bg-[#030C4D]'
                                                    }`} />
                                                    {isOngoing ? 'Aktif' : isDraft ? 'Draft' : isFinished ? 'Selesai' : 'Terjadwal'}
                                                </span>
                                                <ArrowRight size={14} className="text-slate-300 group-hover:text-[#030C4D] group-hover:translate-x-0.5 transition-all" />
                                            </div>
                                            
                                            {exam.creatorName && exam.creatorName !== 'Unknown' && (
                                                <span className="text-[10px] text-slate-400 mt-1.5 mr-6 pr-1">
                                                    oleh: <span className="font-semibold text-slate-600">{exam.creatorName}</span>
                                                </span>
                                            )}
                                        </div>
                                    </motion.div>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="py-16 text-center">
                            <div className="w-16 h-16 bg-[#030C4D]/5 rounded-2xl flex items-center justify-center mx-auto mb-4">
                                <Activity size={22} className="text-[#030C4D]/40" />
                            </div>
                            <p className="font-bold text-slate-700 mb-1 font-sans">Belum Ada Ujian</p>
                            <p className="text-xs text-slate-400 mb-4 font-semibold font-sans">Tanyakan ke Proktor atau koordinasikan jadwal ujian Anda</p>
                        </div>
                    )}
                </div>

                {/* ── Right: Login Activity & Announcements ── */}
                <div className="md:col-span-2 space-y-4">
                    <RecentLoginsCard initialLogins={logins} orgId={org?.id} />

                    {announcements.length > 0 && (
                        <div className="bg-white rounded-lg border border-blue-200 overflow-hidden shadow-sm">
                            <div className="px-5 py-4 border-b border-blue-100 bg-gradient-to-r from-blue-50 to-transparent flex justify-between items-center">
                                <h2 className="text-sm font-bold text-[#030C4D] flex items-center gap-2">
                                    <AlertCircle size={16} /> Informasi
                                </h2>
                                {announcements.length > 2 && (
                                    <button 
                                        onClick={() => setShowAnnouncementsPopup(true)}
                                        className="text-xs font-semibold text-blue-600 hover:text-blue-800 flex items-center gap-1 transition-colors bg-blue-50 hover:bg-blue-100 px-2.5 py-1.5 rounded-lg"
                                    >
                                        <Eye size={14} /> Lihat Semua
                                    </button>
                                )}
                            </div>
                            <div className="p-3">
                                <div className="space-y-3">
                                    {announcements.slice(0, 2).map((ann, idx) => (
                                        <div key={ann.id || idx} className="bg-blue-50/50 border border-blue-100 rounded-lg p-3">
                                            <div className="flex justify-between items-start gap-2 mb-1">
                                                <h3 className="font-semibold text-[#030C4D] text-xs line-clamp-1">{ann.title}</h3>
                                                {ann.created_at && (
                                                    <span className="text-[9px] text-slate-400 shrink-0 whitespace-nowrap">
                                                        {new Date(ann.created_at).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })}
                                                    </span>
                                                )}
                                            </div>
                                            <p className="text-[11px] text-slate-600 line-clamp-2" dangerouslySetInnerHTML={{ __html: linkifyText(ann.content) }}></p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Popup Modal Informasi */}
            {showAnnouncementsPopup && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm transition-opacity">
                    <motion.div 
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                        className="bg-white rounded-2xl shadow-xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden"
                    >
                        <div className="px-6 py-5 border-b border-slate-100 flex justify-between items-center bg-[#f8fafc]">
                            <div>
                                <h2 className="text-lg font-bold text-[#030C4D] flex items-center gap-2">
                                    <AlertCircle size={20} className="text-blue-600" /> Pusat Informasi
                                </h2>
                                <p className="text-xs text-slate-500 mt-0.5">Semua pengumuman yang sedang tayang.</p>
                            </div>
                            <button 
                                onClick={() => setShowAnnouncementsPopup(false)}
                                className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-100 text-slate-500 hover:bg-slate-200 hover:text-slate-700 transition-colors"
                            >
                                ✕
                            </button>
                        </div>
                        <div className="p-6 overflow-y-auto bg-slate-50 flex-1 space-y-4">
                            {announcements.map((ann, idx) => (
                                <div key={ann.id || idx} className="bg-white border border-blue-100 rounded-xl p-5 shadow-sm">
                                    <div className="flex items-start gap-3">
                                        <div className="bg-blue-50 text-blue-600 p-2 rounded-lg shrink-0 mt-0.5">
                                            <AlertCircle size={18} />
                                        </div>
                                        <div className="flex-1">
                                            <div className="flex justify-between items-start gap-2 mb-2">
                                                <h3 className="font-bold text-[#030C4D] text-sm">{ann.title}</h3>
                                                {ann.created_at && (
                                                    <span className="text-xs text-slate-400 shrink-0 bg-slate-50 px-2 py-1 rounded-md border border-slate-100">
                                                        {new Date(ann.created_at).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
                                                    </span>
                                                )}
                                            </div>
                                            <p className="text-sm text-slate-600 whitespace-pre-wrap leading-relaxed" dangerouslySetInnerHTML={{ __html: linkifyText(ann.content, 'text-blue-600 underline font-semibold hover:text-blue-800 transition-colors') }}></p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="p-4 border-t border-slate-100 bg-white flex justify-end">
                            <button 
                                onClick={() => setShowAnnouncementsPopup(false)}
                                className="px-5 py-2.5 bg-[#030C4D] text-white text-sm font-semibold rounded-xl hover:bg-[#0a1a6e] transition-colors"
                            >
                                Tutup
                            </button>
                        </div>
                    </motion.div>
                </div>
            )}

            {/* Modal: Anggota yang sudah pernah login */}
            {showMembersModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowMembersModal(false)}>
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        onClick={(e) => e.stopPropagation()}
                        className="bg-white rounded-2xl shadow-xl w-full max-w-lg max-h-[85vh] flex flex-col overflow-hidden"
                    >
                        <div className="px-6 py-5 border-b border-slate-100 flex justify-between items-center bg-[#f8fafc]">
                            <div>
                                <h2 className="text-lg font-bold text-[#030C4D] flex items-center gap-2">
                                    <Users size={20} className="text-[#030C4D]" /> Anggota Pernah Login
                                </h2>
                                <p className="text-xs text-slate-500 mt-0.5">{membersList.length} anggota sudah pernah masuk ke ACCA CBT.</p>
                            </div>
                            <button
                                onClick={() => setShowMembersModal(false)}
                                className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-100 text-slate-500 hover:bg-slate-200 hover:text-slate-700 transition-colors"
                            >
                                ✕
                            </button>
                        </div>
                        <div className="p-4 overflow-y-auto bg-slate-50 flex-1">
                            {membersLoading ? (
                                <div className="py-12 flex justify-center">
                                    <div className="w-8 h-8 border-4 border-[#030C4D] border-t-transparent rounded-full animate-spin" />
                                </div>
                            ) : membersList.length === 0 ? (
                                <div className="py-12 text-center text-sm text-slate-400">Belum ada anggota yang login.</div>
                            ) : (
                                <div className="space-y-2">
                                    {membersList.map((m) => (
                                        <div key={m.id} className="flex items-center gap-3 bg-white border border-slate-100 rounded-xl p-3">
                                            <div className="w-9 h-9 rounded-full bg-[#030C4D]/10 text-[#030C4D] flex items-center justify-center font-bold shrink-0 uppercase">
                                                {(m.fullName?.[0] || 'U')}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="text-sm font-semibold text-slate-800 truncate">{m.fullName}</p>
                                                <p className="text-[11px] text-slate-400">{m.role}</p>
                                            </div>
                                            <div className="text-right shrink-0">
                                                <p className="text-[10px] text-slate-400 uppercase tracking-wider">Login terakhir</p>
                                                <p className="text-xs font-medium text-slate-600">{formatLoginTime(m.lastLoginAt)}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { getProctorOrganization } from '@/lib/api/proctor';
import { getBankQuestions, getQuestionBankAction, QuestionType, saveQuestionAction } from '@/lib/api/questions';
import { getSessionUser } from '@/lib/session';
import { X, ArrowLeft, Loader2, Save, Eye, Check, ListChecks, ToggleLeft, Layers, Edit3, FileQuestion, CheckCircle2, ArrowRightLeft } from 'lucide-react';
import { LatexRenderer } from '@/app/components/questions/LatexRenderer';
import { TipTapEditor } from '@/app/components/questions/TipTapEditor';
import PreviewModal from '@/app/components/questions/PreviewModal';
import { MCQForm } from '@/app/components/questions/forms/MCQForm';
import { TrueFalseForm } from '@/app/components/questions/forms/TrueFalseForm';
import { MatchingForm } from '@/app/components/questions/forms/MatchingForm';
import { CategorizationForm } from '@/app/components/questions/forms/CategorizationForm';
import { ShortAnswerForm } from '@/app/components/questions/forms/ShortAnswerForm';
import { EssayForm } from '@/app/components/questions/forms/EssayForm';
import { useMemoryState } from '@/lib/useMemoryState';


const QUESTION_TYPES = [
    { value: 'mcq', label: 'Pilihan Ganda', icon: ListChecks },
    { value: 'mcq_complex', label: 'PG Kompleks', icon: CheckCircle2 },
    { value: 'true_false', label: 'Benar / Salah', icon: ToggleLeft },
    { value: 'matching', label: 'Penjodohan', icon: ArrowRightLeft },
    { value: 'categorization', label: 'Kategori', icon: Layers },
    { value: 'short_answer', label: 'Isian Singkat', icon: Edit3 },
    { value: 'essay', label: 'Essay / Uraian', icon: FileQuestion },
];

// Strip $ delimiters from LaTeX text before saving
function stripLatexDelimiters(text: string): string {
    if (!text) return text;
    // Remove inline math delimiters: $...$ or $$...$$
    return text.replace(/\$\$[\s\S]*?\$\$/g, (match) => {
        // Extract content between $$...$$
        return match.slice(2, -2).trim();
    }).replace(/(?<!\$)\$(?!\$)[^$]*\$(?!\$)/g, (match) => {
        // Extract content between $...$ (not $$)
        return match.slice(1, -1).trim();
    });
}

// Strip delimiters for Quill HTML content
function stripHtmlLatexDelimiters(html: string): string {
    if (!html) return html;
    // Process text nodes inside HTML
    return html.replace(/\$\$([\s\S]*?)\$\$/g, (_, content) => content.trim())
                .replace(/(?<!\$)\$(?!\$)([^$]*)\$(?!\$)/g, (_, content) => content.trim());
}

export default function QuestionEditPage() {
    const params = useParams();
    const router = useRouter();
    const bankId = params.bankId as string;
    const questionId = params.questionId as string;
    const isNewQuestion = !questionId || questionId === 'new';

    const [org, setOrg] = useState<any>(null);
    const [bankInfo, setBankInfo] = useState<any>(null);
    const [isLoading, setIsLoading] = useMemoryState(`guru_questions_${bankId}_edit_isLoading`, true);

    // Editor state
    const [editingQuestion, setEditingQuestion] = useState<any>(null);
    const [questionText, setQuestionText] = useState('');
    const [options, setOptions] = useMemoryState<any[]>(`guru_questions_${bankId}_edit_options`, []);
    const [selectedType, setSelectedType] = useState<QuestionType>('mcq');
    const [scoreDefault, setScoreDefault] = useState(1);
    const [metadata, setMetadata] = useState<any>({});
    const [categories, setCategories] = useMemoryState<string[]>(`guru_questions_${bankId}_edit_categories`, []);
    const [kisiKisi, setKisiKisi] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showTypeDropdown, setShowTypeDropdown] = useState(false);
    const [validationErrors, setValidationErrors] = useMemoryState<string[]>(`guru_questions_${bankId}_edit_validationErrors`, []);

    // Preview modal
    const [isViewModalOpen, setIsViewModalOpen] = useState(false);
    const [viewingQuestion, setViewingQuestion] = useState<any>(null);
    const [matchingAnswers, setMatchingAnswers] = useState<Record<string, string>>({});

    // Deduplicate options by id
    const deduplicateOptions = (opts: any[]) => {
        const seen = new Set<string>();
        return opts.filter(o => {
            if (!o.id) return true;
            if (seen.has(o.id)) return false;
            seen.add(o.id);
            return true;
        });
    };

    const addOption = () => {
        if (selectedType === 'true_false') {
            setOptions([...options, { text: '', isCorrect: false, order: options.length }]);
        } else {
            setOptions([...options, { text: '', isCorrect: false, order: options.length }]);
        }
    };

    const removeOption = (idx: number) => {
        setOptions(options.filter((_, i) => i !== idx));
    };

    const updateOption = (idx: number, fields: any) => {
        const newOpts = [...options];
        newOpts[idx] = { ...newOpts[idx], ...fields };
        setOptions(newOpts);
    };

    const validateQuestion = (): boolean => {
        const errors: string[] = [];
        const cleanQuestionText = stripHtmlLatexDelimiters(questionText);
        if (!cleanQuestionText || cleanQuestionText.trim() === '' || cleanQuestionText === '<p></p>' || cleanQuestionText === '<p><br></p>') {
            errors.push('Pertanyaan tidak boleh kosong');
        }
        if (selectedType === 'mcq' || selectedType === 'mcq_complex') {
            const emptyOptions = options.filter(o => !o.text || o.text.trim() === '');
            if (emptyOptions.length > 0) errors.push('Semua opsi jawaban harus diisi');
            const hasCorrect = options.some(o => o.isCorrect === true);
            if (!hasCorrect) errors.push('Pilih jawaban yang benar');
        }
        if (selectedType === 'true_false') {
            const emptyOptions = options.filter(o => !o.text || o.text.trim() === '');
            if (emptyOptions.length > 0) errors.push('Semua pernyataan harus diisi');
        }
        if (selectedType === 'short_answer' || selectedType === 'essay') {
            // OK
        }
        if (!scoreDefault || scoreDefault <= 0) {
            errors.push('Poin harus lebih dari 0');
        }
        setValidationErrors(errors);
        return errors.length === 0;
    };

    const handleSave = async () => {
        if (!validateQuestion()) return;
        if (!org) return;
        setIsSubmitting(true);

        // Strip $ delimiters from question text HTML
        const cleanQuestionText = stripHtmlLatexDelimiters(questionText);
        // Strip $ delimiters from option texts
        const cleanOptions = options.map((opt, i) => ({
            id: opt.id,
            text: stripLatexDelimiters(opt.text || ''),
            isCorrect: opt.isCorrect,
            order: i,
            weight: opt.weight ?? 1,
            metadata: {
                match_texts: opt.match_texts || [],
                category_names: opt.category_names || []
            }
        }));

        const result = await saveQuestionAction({
            id: editingQuestion?.id,
            bankId: bankId,
            type: selectedType,
            questionText: cleanQuestionText,
            difficulty: 'medium',
            scoreDefault: scoreDefault,
            metadata: {
                ...metadata,
                categories: selectedType === 'categorization' ? categories : [],
                kisi_kisi: kisiKisi
            },
            options: (selectedType === 'short_answer' || (selectedType === 'essay' && !metadata?.is_multi_topic)) ? [] : cleanOptions
        });

        if (result.success) {
            router.push(`/dashboard/guru/questions/${bankId}`);
        } else {
            alert('Gagal menyimpan: ' + result.error);
        }
        setIsSubmitting(false);
    };

    const handleOpenPreview = () => {
        const tempQ = {
            id: editingQuestion?.id || 'preview',
            type: selectedType,
            question_text: questionText,
            metadata: { ...metadata, categories },
            bank_question_options: deduplicateOptions(options).map((opt, i) => ({
                id: opt.id || `temp-${i}`,
                option_text: stripLatexDelimiters(opt.text || ''),
                is_correct: opt.isCorrect,
                order: i,
                metadata: {
                    match_texts: opt.match_texts || [],
                    category_names: opt.category_names || []
                }
            }))
        };
        setViewingQuestion(tempQ);
        setIsViewModalOpen(true);
    };

    const handleTypeChange = (type: QuestionType) => {
        setSelectedType(type);
        if (type === 'true_false') {
            setOptions([
                { text: '', isCorrect: true, order: 0, weight: 1 },
                { text: '', isCorrect: false, order: 1, weight: 0 }
            ]);
        } else if (type === 'mcq') {
            setOptions([
                { text: '', isCorrect: true, order: 0, weight: 1 },
                { text: '', isCorrect: false, order: 1, weight: 0 },
                { text: '', isCorrect: false, order: 2, weight: 0 },
                { text: '', isCorrect: false, order: 3, weight: 0 }
            ]);
        } else if (type === 'matching') {
            setOptions([
                { text: '', isCorrect: false, order: 0, weight: 0, match_texts: [] },
                { text: '', isCorrect: false, order: 1, weight: 0, match_texts: [] }
            ]);
        } else if (type === 'categorization') {
            setOptions([
                { text: '', isCorrect: false, order: 0, weight: 0, metadata: { category_names: [] } }
            ]);
        } else {
            setOptions([]);
        }
    };

    // Load initial data
    useEffect(() => {
        async function loadData() {
            try {
                const user = await getSessionUser();
                if (!user) { router.push('/'); return; }

                const orgData = await getProctorOrganization();
                if (!orgData) { router.push('/'); return; }
                setOrg(orgData);

                const bankData = await getQuestionBankAction(bankId);
                setBankInfo(bankData);

                if (!isNewQuestion) {
                    const questionsData = await getBankQuestions(bankId);
                    const existingQuestion = (questionsData || []).find((q: any) => q.id === questionId);
                    if (existingQuestion) {
                        setEditingQuestion(existingQuestion);
                        setQuestionText(existingQuestion.question_text || '');
                        setSelectedType(existingQuestion.type || 'mcq');
                        setScoreDefault(existingQuestion.score_default || 1);
                        setMetadata(existingQuestion.metadata || {});
                        setCategories(existingQuestion.metadata?.categories || []);
                        setKisiKisi(existingQuestion.metadata?.kisi_kisi || '');

                        const loadedOpts = deduplicateOptions(
                            (existingQuestion.bank_question_options || []).map((o: any) => ({
                                id: o.id,
                                text: o.option_text || o.text || '',
                                isCorrect: o.is_correct,
                                order: o.order,
                                weight: o.weight,
                                match_texts: o.metadata?.match_texts || [],
                                category_names: o.metadata?.category_names || []
                            }))
                        );

                        if (existingQuestion.type === 'true_false') {
                            setOptions(loadedOpts);
                        } else if (existingQuestion.type === 'matching') {
                            setMetadata((prev: any) => ({
                                ...prev,
                                right_items: existingQuestion.metadata?.right_items || []
                            }));
                            setOptions(loadedOpts);
                        } else if (existingQuestion.type === 'short_answer') {
                            setMetadata((prev: any) => ({
                                ...prev,
                                blanks: existingQuestion.metadata?.blanks || [{}, {}, {}]
                            }));
                            setOptions([]);
                        } else if (existingQuestion.type === 'categorization') {
                            setOptions(loadedOpts);
                        } else {
                            setOptions(loadedOpts);
                        }
                    }
                } else {
                    setOptions([
                        { text: '', isCorrect: true, order: 0, weight: 1 },
                        { text: '', isCorrect: false, order: 1, weight: 0 },
                        { text: '', isCorrect: false, order: 2, weight: 0 },
                        { text: '', isCorrect: false, order: 3, weight: 0 }
                    ]);
                }
            } catch (error) {
                console.error('Error loading data:', error);
            } finally {
                setIsLoading(false);
            }
        }
        loadData();
        // Auto-injected smart sync (Window Focus)
        const handleFocus = () => { if (typeof loadData === 'function') loadData(); };
        window.addEventListener('focus', handleFocus);
        return () => window.removeEventListener('focus', handleFocus);
    }, [bankId, questionId, isNewQuestion, router]);

    const selectedTypeInfo = QUESTION_TYPES.find(t => t.value === selectedType) || QUESTION_TYPES[0];

    // Right item management (for matching)
    const addRightItem = () => {
        setMetadata((prev: any) => ({
            ...prev,
            right_items: [...(prev.right_items || []), '']
        }));
    };

    const removeRightItem = (idx: number) => {
        setMetadata((prev: any) => ({
            ...prev,
            right_items: (prev.right_items || []).filter((_: any, i: number) => i !== idx)
        }));
    };

    const updateRightItem = (idx: number, value: string) => {
        setMetadata((prev: any) => {
            const newItems = [...(prev.right_items || [])];
            newItems[idx] = value;
            return { ...prev, right_items: newItems };
        });
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-8 h-8 animate-spin text-primary" />
                    <p className="text-sm text-slate-500">Memuat data...</p>
                </div>
            </div>
        );
    }

    const letters = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];

    return (
        <div className="min-h-screen bg-slate-50 flex flex-col">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-4">
                    <button
                        onClick={() => router.push(`/dashboard/guru/questions/${bankId}`)}
                        className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
                    >
                        <ArrowLeft size={20} className="text-slate-600" />
                    </button>
                    <div>
                        <h1 className="text-lg font-semibold text-slate-900">
                            {isNewQuestion ? 'Tambah Soal Baru' : 'Edit Soal'}
                        </h1>
                        <p className="text-sm text-slate-500">{bankInfo?.title || 'Bank Soal'}</p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={handleOpenPreview}
                        className="flex items-center gap-2 px-4 py-2 text-sm font-medium border border-slate-200 rounded-xl bg-white text-slate-600 hover:bg-slate-50 transition-all"
                    >
                        <Eye size={16} />
                        Preview
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={isSubmitting}
                        className="flex items-center gap-2 px-5 py-2 text-sm font-semibold bg-gradient-to-r from-amber-500 to-pink-500 text-white rounded-xl hover:from-amber-600 hover:to-pink-600 transition-all shadow-lg shadow-pink-500/25 disabled:opacity-50"
                    >
                        {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                        Simpan
                    </button>
                </div>
            </div>

            {/* Validation Errors */}
            {validationErrors.length > 0 && (
                <div className="px-6 py-3 bg-rose-50 border-b border-rose-200 shrink-0">
                    <div className="flex items-center gap-2 max-w-5xl mx-auto">
                        <p className="text-xs font-semibold text-rose-700">Mohon perbaiki:</p>
                        <div className="flex gap-3">
                            {validationErrors.map((error, idx) => (
                                <span key={idx} className="text-xs text-rose-600">• {error}</span>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Main Content */}
            <div className="flex-1 overflow-y-auto">
                <div className="max-w-5xl mx-auto p-6 space-y-6">
                    {/* Question Text Editor */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                        <div className="mb-4">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Pertanyaan</label>
                        </div>
                        <TipTapEditor
                            content={questionText}
                            onChange={setQuestionText}
                            placeholder="Tuliskan pertanyaan di sini..."
                            minHeight="200px"
                        />
                    </div>

                    {/* Options Area */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                        {/* Header row */}
                        <div className="flex items-center justify-between pb-4 border-b border-slate-100">
                            <div className="flex items-center gap-2">
                                <span className="text-sm font-semibold text-slate-700">
                                    {selectedType === 'essay' ? 'Opsi Topik' : 'Opsi Jawaban'}
                                </span>
                            </div>
                            {(selectedType !== 'short_answer' && (selectedType !== 'essay' || (metadata as any)?.is_multi_topic)) && (
                                <button
                                    type="button"
                                    onClick={addOption}
                                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-blue-600 bg-blue-50 rounded-lg hover:bg-blue-100 transition-colors"
                                >
                                    <span>+</span> Tambah Opsi
                                </button>
                            )}
                        </div>

                        {/* True/False Options */}
                        {selectedType === 'true_false' && (
                            <TrueFalseForm
                                options={deduplicateOptions(options)}
                                onAddOption={addOption}
                                onInsertOption={(idx) => {}}
                                onRemoveOption={removeOption}
                                onUpdateOption={updateOption}
                            />
                        )}

                        {/* MCQ / MCQ Complex / Essay Options */}
                        {(selectedType === 'mcq' || selectedType === 'mcq_complex' || (selectedType === 'essay' && (metadata as any)?.is_multi_topic)) && (
                            <MCQForm
                                options={deduplicateOptions(options)}
                                isComplex={selectedType === 'mcq_complex' || selectedType === 'essay'}
                                onAddOption={addOption}
                                onInsertOption={(idx) => {}}
                                onRemoveOption={removeOption}
                                onUpdateOption={updateOption}
                                onSetAllCorrect={(idx) => {
                                    if (selectedType === 'essay') return; // no correct option for essay topics
                                    const newOpts = options.map((o, i) => ({ ...o, isCorrect: i === idx }));
                                    setOptions(newOpts);
                                }}
                                onToggleCorrect={(idx) => {
                                    if (selectedType === 'essay') return;
                                    updateOption(idx, { isCorrect: !options[idx].isCorrect });
                                }}
                            />
                        )}

                        {/* Matching Options */}
                        {selectedType === 'matching' && (
                            <MatchingForm
                                options={deduplicateOptions(options)}
                                rightItems={(metadata as any).right_items || []}
                                onAddLeftItem={addOption}
                                onRemoveLeftItem={removeOption}
                                onUpdateLeftItem={(idx, text) => updateOption(idx, { text })}
                                onAddRightItem={addRightItem}
                                onRemoveRightItem={removeRightItem}
                                onUpdateRightItem={updateRightItem}
                                onSetLeftMatch={(optIndex, rightTexts) => updateOption(optIndex, { match_texts: rightTexts })}
                            />
                        )}

                        {/* Categorization Options */}
                        {selectedType === 'categorization' && (
                            <CategorizationForm
                                options={deduplicateOptions(options)}
                                categories={categories}
                                onAddItem={addOption}
                                onInsertItem={(idx) => {}}
                                onRemoveItem={removeOption}
                                onUpdateItem={(idx, text) => updateOption(idx, { text })}
                                onSetCategories={setCategories}
                                onSetItemCategory={(optIndex, cats) => updateOption(optIndex, { category_names: cats })}
                            />
                        )}

                        {/* Short Answer */}
                        {selectedType === 'short_answer' && (
                            <ShortAnswerForm
                                blanks={(metadata as any).blanks || []}
                                onAddBlank={() => {
                                    const blanks = [...((metadata as any).blanks || []), { answer: '', variations: [] }];
                                    setMetadata((prev: any) => ({ ...prev, blanks }));
                                }}
                                onRemoveBlank={(idx) => {
                                    const blanks = ((metadata as any).blanks || []).filter((_: any, i: number) => i !== idx);
                                    setMetadata((prev: any) => ({ ...prev, blanks }));
                                }}
                                onUpdateBlank={(idx, fields) => {
                                    const blanks = [...((metadata as any).blanks || [])];
                                    blanks[idx] = { ...blanks[idx], ...fields };
                                    setMetadata((prev: any) => ({ ...prev, blanks }));
                                }}
                            />
                        )}

                        {/* Essay */}
                        {selectedType === 'essay' && (
                            <EssayForm 
                                metadata={metadata} 
                                onUpdateMetadata={(updates) => setMetadata((prev: any) => ({ ...prev, ...updates }))} 
                            />
                        )}
                    </div>

                    {/* Kisi-kisi */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                        <div className="mb-3">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Kisi-kisi</label>
                        </div>
                        <textarea
                            value={kisiKisi}
                            onChange={(e) => setKisiKisi(e.target.value)}
                            placeholder="Kisi-kisi soal (opsional)..."
                            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-400 resize-none"
                            rows={3}
                        />
                    </div>
                </div>
            </div>

            {/* Preview Modal */}
            {isViewModalOpen && (
                <PreviewModal
                    isOpen={isViewModalOpen}
                    onClose={() => setIsViewModalOpen(false)}
                    bankInfo={bankInfo}
                    viewingQuestion={viewingQuestion}
                    setViewingQuestion={setViewingQuestion}
                    filteredQuestions={[]}
                    currentPreviewIndex={0}
                    setCurrentPreviewIndex={() => {}}
                    matchingAnswers={matchingAnswers}
                    setMatchingAnswers={setMatchingAnswers}
                    setQuestions={() => {}}
                    onFinish={() => setIsViewModalOpen(false)}
                />
            )}
        </div>
    );
}

