                    </div>
                )}
            </AnimatePresence>

            {/* Move to Folder Modal */}
            <AnimatePresence>
                {isMoveModalOpen && bankToMove && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/30" onClick={() => setIsMoveModalOpen(false)} />
                        <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="bg-white w-full max-w-sm rounded-2xl p-6 relative z-10">
                            <button onClick={() => setIsMoveModalOpen(false)} className="absolute top-4 right-4 text-slate-400"><X size={20} /></button>
                            <h3 className="text-lg font-semibold text-slate-900 mb-2">Pindahkan Bank Soal</h3>
                            <p className="text-sm text-slate-500 mb-4">Pilih folder untuk "{bankToMove.title}"</p>
                            <div className="space-y-2 mb-4">
                                <button
                                    onClick={() => handleMoveBank(null)}
                                    className={`w-full text-left px-4 py-3 rounded-xl border transition-all ${!bankToMove.folder_id ? 'border-primary bg-primary/5 text-primary' : 'border-slate-200 hover:border-primary/40'}`}
                                >
                                    <div className="flex items-center gap-2">
                                        <Folder size={14} /> Tanpa Folder
                                    </div>
                                </button>
                                {folders.map(folder => (
                                    <button
                                        key={folder.id}
                                        onClick={() => handleMoveBank(folder.id)}
                                        className={`w-full text-left px-4 py-3 rounded-xl border transition-all ${bankToMove.folder_id === folder.id ? 'border-primary bg-primary/5 text-primary' : 'border-slate-200 hover:border-primary/40'}`}
                                    >
                                        <div className="flex items-center gap-2">
                                            <Folder size={14} /> {folder.name}
                                        </div>
                                    </button>
                                ))}
                                {folders.length === 0 && (
                                    <p className="text-xs text-slate-400 text-center py-4">Belum ada folder. Buat folder terlebih dahulu.</p>
                                )}
                            </div>
                            <button onClick={() => setIsMoveModalOpen(false)} className="w-full py-2.5 bg-slate-100 text-slate-700 rounded-xl font-medium">Batal</button>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* Add Existing Banks to Folder Modal */}
            <AnimatePresence>
                {isAddToFolderModalOpen && targetFolder && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/30" onClick={() => setIsAddToFolderModalOpen(false)} />
                        <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="bg-white w-full max-w-lg rounded-2xl p-6 relative z-10 max-h-[80vh] flex flex-col">
                            <button onClick={() => setIsAddToFolderModalOpen(false)} className="absolute top-4 right-4 text-slate-400"><X size={20} /></button>
                            <h3 className="text-lg font-semibold text-slate-900 mb-1">Tambah ke "{targetFolder.name}"</h3>
                            <p className="text-sm text-slate-500 mb-4">Pilih bank soal untuk ditambahkan:</p>
                            <div className="flex-1 overflow-y-auto space-y-2 mb-4">
                                {banks.filter(b => !b.folder_id || b.folder_id !== targetFolder.id).length === 0 ? (
                                    <div className="text-center text-slate-400 py-8">
                                        <BookOpen size={24} className="mx-auto mb-2 opacity-50" />
                                        <p className="text-sm">Semua bank soal sudah ada di folder ini</p>
                                        <p className="text-xs mt-1">atau belum ada bank soal</p>
                                    </div>
                                ) : (
                                    banks
                                        .filter(b => !b.folder_id || b.folder_id !== targetFolder.id)
                                        .map(bank => (
                                            <div
                                                key={bank.id}
                                                onClick={() => {
                                                    setSelectedAddToFolderIds(prev => {
                                                        const next = new Set(prev);
                                                        if (next.has(bank.id)) next.delete(bank.id);
                                                        else next.add(bank.id);
                                                        return next;
                                                    });
                                                }}
                                                className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${selectedAddToFolderIds.has(bank.id) ? 'border-primary bg-primary/5' : 'border-slate-200 hover:border-primary/40'}`}
                                            >
                                                <input
                                                    type="checkbox"
                                                    checked={selectedAddToFolderIds.has(bank.id)}
                                                    onChange={() => {}}
                                                    className="w-4 h-4 text-primary border-slate-300 rounded"
                                                />
                                                <div className="flex-1 min-w-0">
                                                    <p className="font-medium text-slate-800 text-sm truncate">{bank.title}</p>
                                                    <div className="flex items-center gap-2 mt-0.5">
                                                        <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-medium ${bank.is_published ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                                                            {bank.is_published ? 'Published' : 'Draft'}
                                                        </span>
                                                        <span className="text-xs text-slate-400">{bank.question_count || 0} soal</span>
                                                        {bank.subject && <span className="text-xs text-slate-400">• {bank.subject}</span>}
                                                        {bank.class_level && <span className="text-xs text-slate-400">• {bank.class_level}</span>}
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                )}
                            </div>
                            <div className="flex gap-3">
                                <button onClick={() => setIsAddToFolderModalOpen(false)} className="flex-1 py-2.5 bg-slate-100 text-slate-700 rounded-xl font-medium">Batal</button>
                                <button
                                    onClick={handleAddBanksToFolder}
                                    disabled={selectedAddToFolderIds.size === 0 || isSubmitting}
                                    className="flex-1 py-2.5 bg-primary text-white rounded-xl font-medium disabled:opacity-50 flex items-center justify-center gap-2"
                                >
                                    {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} />}
                                    Tambah {selectedAddToFolderIds.size > 0 ? `(${selectedAddToFolderIds.size})` : ''}
                                </button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* Bulk Move to Folder Modal */}
            <AnimatePresence>
                {isBulkMoveModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/30" onClick={() => setIsBulkMoveModalOpen(false)} />
                        <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="bg-white w-full max-w-sm rounded-2xl p-6 relative z-10">
                            <button onClick={() => setIsBulkMoveModalOpen(false)} className="absolute top-4 right-4 text-slate-400"><X size={20} /></button>
                            <h3 className="text-lg font-semibold text-slate-900 mb-2">Pindahkan {selectedBankIds.size} Bank Soal</h3>
                            <p className="text-sm text-slate-500 mb-4">Pilih folder tujuan:</p>
                            <div className="space-y-2 mb-4">
                                <button
                                    onClick={() => handleBulkMove(null)}
                                    className="w-full text-left px-4 py-3 rounded-xl border transition-all border-slate-200 hover:border-primary/40"
                                >
                                    <div className="flex items-center gap-2">
                                        <Folder size={14} /> Hapus dari Folder (Tanpa Folder)
                                    </div>
                                </button>
                                {folders.map(folder => (
                                    <button
                                        key={folder.id}
                                        onClick={() => handleBulkMove(folder.id)}
                                        className="w-full text-left px-4 py-3 rounded-xl border transition-all border-slate-200 hover:border-primary/40"
                                    >
                                        <div className="flex items-center gap-2">
                                            <Folder size={14} /> {folder.name}
                                        </div>
                                    </button>
                                ))}
                                {folders.length === 0 && (
                                    <p className="text-xs text-slate-400 text-center py-4">Belum ada folder. Buat folder terlebih dahulu.</p>
                                )}
                            </div>
                            <button onClick={() => setIsBulkMoveModalOpen(false)} className="w-full py-2.5 bg-slate-100 text-slate-700 rounded-xl font-medium">Batal</button>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* Add/Edit Modal */}
            <AnimatePresence>
                {isAddModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/30" onClick={() => { setIsAddModalOpen(false); setEditingBank(null); }} />
                        <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="bg-white w-full max-w-md rounded-2xl p-6 relative z-10">
                            <button onClick={() => { setIsAddModalOpen(false); setEditingBank(null); }} className="absolute top-4 right-4 text-slate-400"><X size={20} /></button>
                            <h3 className="text-lg font-semibold text-slate-900 mb-4">{editingBank ? 'Edit Bank Soal' : 'Buat Bank Soal Baru'}</h3>
                            <form onSubmit={handleSaveBank} className="space-y-4">
                                <input required type="text" placeholder="Judul Bank Soal" value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none" />
                                <input
                                        type="text"
                                        list="subject-suggestions"
                                        placeholder="Ketik nama mapel..."
                                        value={formData.subject}
                                        onChange={e => setFormData({ ...formData, subject: e.target.value })}
                                        className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none"
                                    />
                                    <datalist id="subject-suggestions">
                                        {orgSubjects.map((sub, idx) => (
                                            <option key={idx} value={sub.name} />
                                        ))}
                                    </datalist>
                                {folders.length > 0 && (
                                    <select
                                        value={formData.folderId || ''}
                                        onChange={e => setFormData({ ...formData, folderId: e.target.value || undefined })}
                                        className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none"
                                    >
                                        <option value="">Pilih Folder (opsional)</option>
                                        {folders.map(folder => (
                                            <option key={folder.id} value={folder.id}>{folder.name}</option>
                                        ))}
                                    </select>
                                )}
                                <select value={formData.classLevel} onChange={e => setFormData({ ...formData, classLevel: e.target.value })} className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none">
                                    <option value="">Pilih Tingkat</option>
                                    <option value="Kelas 10">Kelas 10 (SMA)</option>
                                    <option value="Kelas 11">Kelas 11 (SMA)</option>
                                    <option value="Kelas 12">Kelas 12 (SMA)</option>
                                    <option value="Umum">Umum (Guru/Trainer)</option>
                                </select>
                                <textarea placeholder="Deskripsi (opsional)" value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })} className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none min-h-[80px]" />
                                <label className="flex items-center gap-3 p-4 border border-dashed border-slate-200 rounded-xl cursor-pointer hover:border-primary/40">
                                    <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                                    <Upload size={18} className="text-slate-400" />
                                    <span className="text-sm text-slate-500">{formData.imageUrl ? 'Ganti Cover' : 'Upload Cover'}</span>
                                </label>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-2">Label</label>
                                    <div className="flex flex-wrap gap-2 mb-2">
                                        {labels.map(label => (
                                            <button
                                                key={label.id}
                                                type="button"
                                                onClick={() => toggleTag(label.name)}
                                                className={`px-3 py-1 rounded-full text-xs font-medium border transition-all ${formData.tags.includes(label.name) ? 'text-white' : 'bg-white text-slate-600 border-slate-200 hover:border-primary/40'}`}
                                                style={formData.tags.includes(label.name) ? { backgroundColor: label.color, borderColor: label.color } : {}}
                                            >
                                                {label.name}
                                            </button>
                                        ))}
                                    </div>
                                    <div className="flex gap-2 mt-3">
                                        <input
                                            type="text"
                                            placeholder="Tulis & tambah label baru..."
                                            value={newCustomLabel}
                                            onChange={e => setNewCustomLabel(e.target.value)}
                                            onKeyDown={e => {
                                                if (e.key === 'Enter') {
                                                    e.preventDefault();
                                                    handleCreateCustomLabel();
                                                }
                                            }}
                                            className="flex-1 border border-slate-200 rounded-xl px-3 py-2 text-xs focus:ring-2 focus:ring-primary/10 outline-none"
                                        />
                                        <button
                                            type="button"
                                            onClick={handleCreateCustomLabel}
                                            className="px-3 py-2 bg-primary text-white text-xs font-medium rounded-xl hover:bg-primary-hover transition-colors"
                                        >
                                            Tambah
                                        </button>
                                    </div>
                                </div>
                                <button type="submit" disabled={isSubmitting || uploadingImage} className="w-full py-3 bg-primary text-white rounded-xl font-medium flex items-center justify-center gap-2 disabled:opacity-50">
                                    {isSubmitting ? <Loader2 size={18} className="animate-spin" /> : <Check size={18} />}
                                    {editingBank ? 'Simpan' : 'Buat Bank Soal'}
                                </button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* Delete Modal */}
            <AnimatePresence>
                {isDeleteModalOpen && bankToDelete && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/30" onClick={() => setIsDeleteModalOpen(false)} />
                        <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="bg-white w-full max-w-sm rounded-2xl p-6 relative z-10">
                            <button onClick={() => setIsDeleteModalOpen(false)} className="absolute top-4 right-4 text-slate-400"><X size={20} /></button>
                            <h3 className="text-lg font-semibold text-slate-900 mb-2">Hapus Bank Soal</h3>
                            <p className="text-sm text-slate-500 mb-4">Yakin ingin menghapus "{bankToDelete.title}"? Tindakan ini tidak dapat dibatalkan.</p>
                            <div className="flex gap-3">
                                <button onClick={() => setIsDeleteModalOpen(false)} className="flex-1 py-2.5 bg-slate-100 text-slate-700 rounded-xl font-medium">Batal</button>
                                <button onClick={handleDeleteBank} disabled={isSubmitting} className="flex-1 py-2.5 bg-red-500 text-white rounded-xl font-medium disabled:opacity-50">Hapus</button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";
import React, { useState, useEffect, useCallback } from 'react';
import { useMemoryState } from '@/lib/useMemoryState';
import { motion } from 'framer-motion';
import {
     Bell,
    Check,
    CheckCheck,
    Trash2,
    Filter,
    Clock,
    CheckCircle2,
    AlertCircle,
    Loader2,
    Settings,
    Calendar,
    Award,
    UserPlus,
    FileText,
    ChevronRight,
    Sparkles
} from 'lucide-react';
import { getSessionUser } from '@/lib/session';
import {
    getUserNotifications,
    getUnreadNotificationCount,
    markNotificationRead,
    markAllNotificationsRead,
    deleteNotification,
    deleteAllReadNotifications
} from '@/lib/api/notifications';
import type { Notification, NotificationType } from '@/app/types/notification';
import {
    NOTIFICATION_TYPE_LABELS,
    NOTIFICATION_TYPE_COLORS,
    getNotificationTimeAgo
} from '@/app/types/notification';

type FilterType = 'all' | 'unread' | NotificationType;

export default function NotificationsPage() {
    const [user, setUser] = useState<any>(null);
    const [notifications, setNotifications] = useMemoryState<Notification[]>('notifications_notifications', []);
    const [unreadCount, setUnreadCount] = useState(0);
    const [isLoading, setIsLoading] = useMemoryState('notifications_isLoading', true);
    const [filter, setFilter] = useState<FilterType>('all');
    const [selectedNotifications, setSelectedNotifications] = useState<Set<string>>(new Set());
    const [isProcessing, setIsProcessing] = useState(false);
    const [fullName, setFullName] = useState<string>('');

    // Fetch user
    useEffect(() => {
        async function fetchUser() {
            const user = await getSessionUser();
            setUser(user);
            if (user) {
                setFullName(user.fullName ?? '');
            }
        }
        fetchUser();
    }, []);

    // Fetch notifications
    const fetchNotifications = useCallback(async () => {
        if (!user) return;
        setIsLoading(true);
        try {
            const [notifs, count] = await Promise.all([
                getUserNotifications({ limit: 50 }),
                getUnreadNotificationCount()
            ]);
            setNotifications(notifs);
            setUnreadCount(count);
        } catch (error) {
            console.error('[Notifications] Fetch error:', error);
        }
        setIsLoading(false);
    }, [user]);

    useEffect(() => {
        fetchNotifications();
    }, [fetchNotifications]);

    // Filter notifications
    const filteredNotifications = notifications.filter(notif => {
        if (filter === 'all') return true;
        if (filter === 'unread') return !notif.is_read;
        return notif.type === filter;
    });

    // Get notification icon
    const getNotificationIcon = (type: NotificationType) => {
        switch (type) {
            case 'exam_reminder': return '🔔';
            case 'exam_result': return '📊';
            case 'exam_available': return '✅';
            case 'exam_graded': return '📝';
            case 'exam_submitted': return '📤';
            case 'class_invite': return '👋';
            case 'class_update': return '🔄';
            case 'achievement': return '🏆';
            case 'announcement': return '📢';
            case 'system': return '⚙️';
            default: return '📌';
        }
    };

    // Handle mark as read
    const handleMarkAsRead = async (id: string) => {
        await markNotificationRead(id);
        fetchNotifications();
    };

    // Handle mark all as read
    const handleMarkAllAsRead = async () => {
        setIsProcessing(true);
        await markAllNotificationsRead();
        fetchNotifications();
        setIsProcessing(false);
    };

    // Handle delete
    const handleDelete = async (id: string) => {
        await deleteNotification(id);
        fetchNotifications();
    };

    // Handle delete all read
    const handleDeleteAllRead = async () => {
        setIsProcessing(true);
        await deleteAllReadNotifications();
        fetchNotifications();
        setIsProcessing(false);
    };

    // Handle bulk selection
    const toggleSelect = (id: string) => {
        const newSelected = new Set(selectedNotifications);
        if (newSelected.has(id)) {
            newSelected.delete(id);
        } else {
            newSelected.add(id);
        }
        setSelectedNotifications(newSelected);
    };

    // Handle bulk mark as read
    const handleBulkMarkAsRead = async () => {
        setIsProcessing(true);
        for (const id of selectedNotifications) {
            await markNotificationRead(id);
        }
        setSelectedNotifications(new Set());
        fetchNotifications();
        setIsProcessing(false);
    };

    // Handle bulk delete
    const handleBulkDelete = async () => {
        setIsProcessing(true);
        for (const id of selectedNotifications) {
            await deleteNotification(id);
        }
        setSelectedNotifications(new Set());
        fetchNotifications();
        setIsProcessing(false);
    };

    // Filter options
    const filterOptions: { value: FilterType; label: string; count?: number }[] = [
        { value: 'all', label: 'Semua' },
        { value: 'unread', label: 'Belum Dibaca', count: unreadCount },
        { value: 'exam_reminder', label: 'Pengingat Ujian' },
        { value: 'exam_result', label: 'Hasil Ujian' },
        { value: 'class_invite', label: 'Undangan Kelas' },
        { value: 'achievement', label: 'Pencapaian' },
    ];

    return (
        <div className="max-w-7xl mx-auto pb-24 space-y-6">
            {/* ── Hero Header — Compact acca-hero-gradient ── */}
            <div className="relative overflow-hidden rounded-2xl acca-hero-gradient shadow-xl shadow-[#0038A8]/15 mt-4 md:mt-0 p-6 md:p-8">
                {/* Decorative Glowing Orbs */}
                <div className="absolute -top-12 -right-12 w-72 h-72 bg-white/10 rounded-full blur-3xl pointer-events-none" />
                <div className="absolute -bottom-12 -left-12 w-56 h-56 bg-white/5 rounded-full blur-2xl pointer-events-none" />

                <div className="relative flex flex-col md:flex-row md:items-center md:justify-between gap-5 z-10">
                    <div className="space-y-2">
                        <h1 className="text-2xl md:text-3xl font-extrabold text-white tracking-tight leading-tight">
                            Halo, <span className="text-amber-200">{fullName || 'Siswa'}</span>! 👋
                        </h1>
                        <p className="text-white/80 text-xs md:text-sm max-w-xl font-medium leading-relaxed">
                            {unreadCount > 0
                                ? `Anda memiliki ${unreadCount} notifikasi baru yang belum dibaca.`
                                : 'Semua notifikasi sudah dibaca. Anda sudah up-to-date!'}
                        </p>
                    </div>
                    
                    <div className="flex items-center gap-3 self-start md:self-center shrink-0">
                        {/* Compact Stat Badge */}
                        <div className="flex items-center gap-2 bg-white/10 backdrop-blur-md px-4 py-2.5 rounded-xl border border-white/15 shadow-lg">
                            <span className="text-xs font-bold text-white/95">Belum Dibaca:</span>
                            <span className="text-base font-black text-white font-mono bg-white/20 px-2.5 py-0.5 rounded-lg leading-none">{unreadCount}</span>
                        </div>

                        {selectedNotifications.size > 0 && (
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={handleBulkMarkAsRead}
                                    disabled={isProcessing}
                                    className="px-4 py-2.5 text-xs font-bold text-[#0038A8] bg-white hover:bg-slate-50 rounded-xl transition-all flex items-center gap-1.5 shadow-sm active:scale-95"
                                >
                                    <CheckCheck size={14} />
                                    Tandai Baca
                                </button>
                                <button
                                    onClick={handleBulkDelete}
                                    disabled={isProcessing}
                                    className="px-4 py-2.5 text-xs font-bold text-white bg-rose-600 hover:bg-rose-700 rounded-xl transition-all flex items-center gap-1.5 shadow-sm active:scale-95"
                                >
                                    <Trash2 size={14} />
                                    Hapus
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Filter Tabs (Detached) */}
            <div className="flex items-center gap-2 overflow-x-auto scrollbar-hide pb-2 px-1">
                {filterOptions.map((option) => (
                    <button
                        key={option.value}
                        onClick={() => setFilter(option.value)}
                        className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-2 border ${
                            filter === option.value
                                ? 'bg-[#0038A8] text-white border-[#0038A8] shadow-md shadow-[#0038A8]/10'
                                : 'bg-white text-slate-600 border-slate-100 hover:border-slate-200 hover:bg-slate-50'
                        }`}
                    >
                        {option.label}
                        {option.count !== undefined && option.count > 0 && (
                            <span className={`px-2 py-0.5 rounded-full text-[10px] ${
                                filter === option.value
                                    ? 'bg-white/20 text-white'
                                    : 'bg-rose-100 text-rose-600'
                            }`}>
                                {option.count}
                            </span>
                        )}
                    </button>
                ))}
            </div>

            {/* Content */}
            <div className="space-y-4">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 space-y-3">
                        <Loader2 size={36} className="animate-spin text-[#0038A8]" />
                        <p className="text-slate-400 font-bold text-xs tracking-wider uppercase font-sans">Memuat notifikasi...</p>
                    </div>
                ) : filteredNotifications.length === 0 ? (
                    <div className="py-20 px-6 text-center bg-white border border-dashed border-slate-200 rounded-2xl max-w-xl mx-auto w-full flex flex-col items-center">
                        <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center mb-4 border border-slate-100">
                            <Bell size={28} className="text-slate-300" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-700 mb-1">
                            {filter === 'unread' ? 'Tidak Ada Notifikasi Belum Dibaca' : 'Tidak Ada Notifikasi'}
                        </h3>
                        <p className="text-slate-500 text-sm max-w-sm mb-0">
                            {filter === 'all'
                                ? 'Semua notifikasi terbaru Anda akan muncul di halaman ini.'
                                : 'Coba ubah opsi filter pencarian Anda di atas.'}
                        </p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {filteredNotifications.map((notif, index) => {
                            const colors = NOTIFICATION_TYPE_COLORS[notif.type] || { bg: 'bg-slate-100', text: 'text-slate-600' };
                            
                            return (
                                <motion.div
                                    key={notif.id}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: index * 0.02 }}
                                    className={`group relative bg-white rounded-2xl border transition-all duration-300 hover:shadow-md ${
                                        !notif.is_read 
                                            ? 'border-indigo-100/80 shadow-[0_2px_12px_rgba(99,102,241,0.04)]' 
                                            : 'border-slate-100/50 opacity-80 hover:opacity-100'
                                    }`}
                                >
                                    {/* Unread Indicator Bar */}
                                    {!notif.is_read && (
                                        <div className="absolute top-0 left-0 w-1 h-full bg-[#0038A8] rounded-l-2xl"></div>
                                    )}

                                    <div className="p-4 sm:p-5 flex items-start gap-4 pl-5">
                                        {/* Checkbox */}
                                        <button
                                            onClick={() => toggleSelect(notif.id)}
                                            className={`mt-1 w-5 h-5 rounded-lg border flex items-center justify-center shrink-0 transition-all duration-200 ${
                                                selectedNotifications.has(notif.id)
                                                    ? 'bg-[#0038A8] border-[#0038A8] shadow-inner text-white'
                                                    : 'border-slate-200 bg-slate-50/50 opacity-0 group-hover:opacity-100 hover:border-[#0038A8]'
                                            }`}
                                        >
                                            {selectedNotifications.has(notif.id) && (
                                                <Check size={12} className="stroke-[3]" />
                                            )}
                                        </button>

                                        {/* Icon */}
                                        <div className={`w-10 h-10 rounded-xl ${colors.bg} flex items-center justify-center text-lg shrink-0 border border-white`}>
                                            {getNotificationIcon(notif.type)}
                                        </div>

                                        {/* Content */}
                                        <div className="flex-1 min-w-0">
                                            <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3">
                                                <div className="space-y-1">
                                                    <h4 className={`text-sm font-bold tracking-tight ${!notif.is_read ? 'text-slate-900' : 'text-slate-700'}`}>
                                                        {notif.title}
                                                    </h4>
                                                    {notif.message && (
                                                        <p className="text-sm text-slate-500 leading-relaxed pr-4 font-sans font-medium">
                                                            {notif.message}
                                                        </p>
                                                    )}
                                                    <div className="flex items-center gap-3 pt-2">
                                                        <span className="text-[11px] font-medium text-slate-400 flex items-center gap-1.5">
                                                            <Clock size={12} />
                                                            {getNotificationTimeAgo(notif.created_at)}
                                                        </span>
                                                        <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                                                        <span className={`text-[9px] font-bold tracking-wider uppercase ${colors.text}`}>
                                                            {NOTIFICATION_TYPE_LABELS[notif.type] || 'Notifikasi'}
                                                        </span>
                                                    </div>
                                                </div>

                                                {/* Actions */}
                                                <div className="flex items-center gap-1.5 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    {!notif.is_read && (
                                                        <button
                                                            onClick={() => handleMarkAsRead(notif.id)}
                                                            className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-100 transition-colors"
                                                            title="Tandai sudah dibaca"
                                                        >
                                                            <CheckCircle2 size={15} />
                                                        </button>
                                                    )}
                                                    <button
                                                        onClick={() => handleDelete(notif.id)}
                                                        className="p-1.5 rounded-lg bg-rose-50 text-rose-600 hover:bg-rose-100 transition-colors"
                                                        title="Hapus"
                                                    >
                                                        <Trash2 size={15} />
                                                    </button>
                                                </div>
                                            </div>

                                            {/* Action Button */}
                                            {notif.action_url && (
                                                <div className="mt-3.5 flex">
                                                    <button
                                                        onClick={() => {
                                                            if (notif.action_url) {
                                                                window.location.href = notif.action_url;
                                                            }
                                                        }}
                                                        className="inline-flex items-center gap-1 px-3.5 py-1.5 bg-blue-50 hover:bg-blue-100 text-[#0038A8] rounded-xl text-xs font-bold transition-colors"
                                                    >
                                                        Lihat Detail
                                                        <ChevronRight size={13} />
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </motion.div>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* Quick Actions Floating */}
            {selectedNotifications.size === 0 && (unreadCount > 0 || notifications.some(n => n.is_read)) && (
                <motion.div
                    initial={{ y: 100, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/90 backdrop-blur-md rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.08)] border border-slate-200/50 px-2.5 py-2 flex items-center gap-1.5 z-50"
                >
                    {unreadCount > 0 && (
                        <button
                            onClick={handleMarkAllAsRead}
                            disabled={isProcessing}
                            className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-600 hover:text-emerald-600 hover:bg-emerald-50 rounded-full transition-all active:scale-95"
                        >
                            <CheckCheck size={16} />
                            <span className="hidden sm:inline">Tandai Semua Dibaca</span>
                            <span className="sm:hidden">Semua Dibaca</span>
                        </button>
                    )}
                    {unreadCount > 0 && notifications.some(n => n.is_read) && (
                        <div className="w-px h-4 bg-slate-200 mx-1" />
                    )}
                    {notifications.some(n => n.is_read) && (
                        <button
                            onClick={handleDeleteAllRead}
                            disabled={isProcessing}
                            className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-600 hover:text-rose-600 hover:bg-rose-50 rounded-full transition-all active:scale-95"
                        >
                            <Trash2 size={16} />
                            <span className="hidden sm:inline">Hapus Semua Terbaca</span>
                            <span className="sm:hidden">Hapus Terbaca</span>
                        </button>
                    )}
                </motion.div>
            )}
        </div>
    );
}

"use client";
import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
    Bell,
    Mail,
    Smartphone,
    Clock,
    Check,
    AlertCircle,
    Loader2,
    Save,
    RefreshCw
} from 'lucide-react';
import { getSessionUser } from '@/lib/session';
import {
    getNotificationPreferences,
    updateNotificationPreferences
} from '@/lib/api/notifications';
import type { NotificationPreferences } from '@/app/types/notification';
import { DEFAULT_NOTIFICATION_PREFERENCES } from '@/app/types/notification';
import { useMemoryState } from '@/lib/useMemoryState';

export default function NotificationSettingsPage() {
    const [user, setUser] = useState<any>(null);
    const [preferences, setPreferences] = useState<Partial<NotificationPreferences>>({});
    const [isLoading, setIsLoading] = useMemoryState('notifications_settings_isLoading', true);
    const [isSaving, setIsSaving] = useState(false);
    const [saveSuccess, setSaveSuccess] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Fetch user and preferences
    const fetchData = useCallback(async () => {
        const user = await getSessionUser();
        setUser(user);

        if (user) {
            const prefs = await getNotificationPreferences();
            if (prefs) {
                setPreferences(prefs);
            } else {
                setPreferences(DEFAULT_NOTIFICATION_PREFERENCES);
            }
        }
        setIsLoading(false);
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // Handle toggle
    const handleToggle = (key: keyof NotificationPreferences) => {
        setPreferences(prev => ({
            ...prev,
            [key]: !prev[key]
        }));
    };

    // Handle minutes change
    const handleMinutesChange = (value: number) => {
        setPreferences(prev => ({
            ...prev,
            exam_reminder_minutes: value
        }));
    };

    // Handle save
    const handleSave = async () => {
        if (!user) return;

        setIsSaving(true);
        setError(null);
        setSaveSuccess(false);

        try {
            const result = await updateNotificationPreferences(preferences);
            if (result.success) {
                setSaveSuccess(true);
                setTimeout(() => setSaveSuccess(false), 3000);
            } else {
                setError(result.error || 'Gagal menyimpan pengaturan');
            }
        } catch (err: any) {
            setError(err.message || 'Terjadi kesalahan');
        }

        setIsSaving(false);
    };

    // Quick time options
    const timeOptions = [
        { value: 15, label: '15 menit' },
        { value: 30, label: '30 menit' },
        { value: 60, label: '1 jam' },
        { value: 120, label: '2 jam' },
        { value: 1440, label: '1 hari' },
    ];

    if (isLoading) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <Loader2 size={32} className="animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50">
            {/* Header */}
            <div className="bg-white border-b border-slate-200">
                <div className="max-w-2xl mx-auto px-4 py-6">
                    <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <Bell size={22} className="text-primary" />
                        Pengaturan Notifikasi
                    </h1>
                    <p className="text-sm text-slate-500 mt-1">
                        Atur bagaimana Anda menerima notifikasi
                    </p>
                </div>
            </div>

            {/* Content */}
            <div className="max-w-2xl mx-auto px-4 py-6 space-y-6">
                {/* Success/Error Messages */}
                {saveSuccess && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="bg-emerald-50 border border-emerald-200 text-emerald-700 px-4 py-3 rounded-xl flex items-center gap-3"
                    >
                        <Check size={20} />
                        Pengaturan berhasil disimpan
                    </motion.div>
                )}

                {error && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl flex items-center gap-3"
                    >
                        <AlertCircle size={20} />
                        {error}
                    </motion.div>
                )}

                {/* Channel Preferences */}
                <div className="bg-white rounded-2xl border shadow-sm overflow-hidden">
                    <div className="px-6 py-4 border-b border-slate-100">
                        <h2 className="font-bold text-slate-800">Saluran Notifikasi</h2>
                        <p className="text-sm text-slate-500 mt-1">Pilih bagaimana Anda ingin menerima notifikasi</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {/* Email */}
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-blue-100 flex items-center justify-center">
                                    <Mail size={20} className="text-blue-600" />
                                </div>
                                <div>
                                    <p className="font-medium text-slate-800">Email</p>
                                    <p className="text-sm text-slate-500">Terima notifikasi via email</p>
                                </div>
                            </div>
                            <button
                                onClick={() => handleToggle('email_enabled')}
                                className={`relative w-12 h-7 rounded-full transition-colors ${
                                    preferences.email_enabled ? 'bg-primary' : 'bg-slate-300'
                                }`}
                            >
                                <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                    preferences.email_enabled ? 'translate-x-6' : 'translate-x-1'
                                }`} />
                            </button>
                        </div>

                        {/* Push */}
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-emerald-100 flex items-center justify-center">
                                    <Smartphone size={20} className="text-emerald-600" />
                                </div>
                                <div>
                                    <p className="font-medium text-slate-800">Push Notification</p>
                                    <p className="text-sm text-slate-500">Terima notifikasi di browser</p>
                                </div>
                            </div>
                            <button
                                onClick={() => handleToggle('push_enabled')}
                                className={`relative w-12 h-7 rounded-full transition-colors ${
                                    preferences.push_enabled ? 'bg-primary' : 'bg-slate-300'
                                }`}
                            >
                                <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                    preferences.push_enabled ? 'translate-x-6' : 'translate-x-1'
                                }`} />
                            </button>
                        </div>
                    </div>
                </div>

                {/* Notification Types */}
                <div className="bg-white rounded-2xl border shadow-sm overflow-hidden">
                    <div className="px-6 py-4 border-b border-slate-100">
                        <h2 className="font-bold text-slate-800">Jenis Notifikasi</h2>
                        <p className="text-sm text-slate-500 mt-1">Pilih notifikasi yang ingin Anda terima</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {/* Exam Reminder */}
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-amber-100 flex items-center justify-center">
                                    <Bell size={20} className="text-amber-600" />
                                </div>
                                <div>
                                    <p className="font-medium text-slate-800">Pengingat Ujian</p>
                                    <p className="text-sm text-slate-500">Notifikasi sebelum ujian dimulai</p>
                                </div>
                            </div>
                            <button
                                onClick={() => handleToggle('exam_reminder')}
                                className={`relative w-12 h-7 rounded-full transition-colors ${
                                    preferences.exam_reminder ? 'bg-primary' : 'bg-slate-300'
                                }`}
                            >
                                <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                    preferences.exam_reminder ? 'translate-x-6' : 'translate-x-1'
                                }`} />
                            </button>
                        </div>

                        {/* Reminder Timing */}
                        {preferences.exam_reminder && (
                            <motion.div
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                className="ml-13 pl-4 border-l-2 border-primary/20"
                            >
                                <p className="text-sm text-slate-600 mb-2 flex items-center gap-2">
                                    <Clock size={14} />
                                    Kirim pengingat sebelum:
                                </p>
                                <div className="flex flex-wrap gap-2">
                                    {timeOptions.map(option => (
                                        <button
                                            key={option.value}
                                            onClick={() => handleMinutesChange(option.value)}
                                            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                                                preferences.exam_reminder_minutes === option.value
                                                    ? 'bg-primary text-white'
                                                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                                            }`}
                                        >
                                            {option.label}
                                        </button>
                                    ))}
                                </div>
                            </motion.div>
                        )}

                        <div className="border-t border-slate-100 pt-4 space-y-4">
                            {/* Class Updates */}
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-purple-100 flex items-center justify-center">
                                        <RefreshCw size={20} className="text-purple-600" />
                                    </div>
                                    <div>
                                        <p className="font-medium text-slate-800">Update Kelas</p>
                                        <p className="text-sm text-slate-500">Notifikasi perubahan di kelas</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => handleToggle('class_updates')}
                                    className={`relative w-12 h-7 rounded-full transition-colors ${
                                        preferences.class_updates ? 'bg-primary' : 'bg-slate-300'
                                    }`}
                                >
                                    <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                        preferences.class_updates ? 'translate-x-6' : 'translate-x-1'
                                    }`} />
                                </button>
                            </div>

                            {/* Results */}
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-cyan-100 flex items-center justify-center">
                                        <Bell size={20} className="text-cyan-600" />
                                    </div>
                                    <div>
                                        <p className="font-medium text-slate-800">Hasil Ujian</p>
                                        <p className="text-sm text-slate-500">Notifikasi saat hasil tersedia</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => handleToggle('results_notifications')}
                                    className={`relative w-12 h-7 rounded-full transition-colors ${
                                        preferences.results_notifications ? 'bg-primary' : 'bg-slate-300'
                                    }`}
                                >
                                    <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                        preferences.results_notifications ? 'translate-x-6' : 'translate-x-1'
                                    }`} />
                                </button>
                            </div>

                            {/* Achievements */}
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-yellow-100 flex items-center justify-center">
                                        <Bell size={20} className="text-yellow-600" />
                                    </div>
                                    <div>
                                        <p className="font-medium text-slate-800">Pencapaian</p>
                                        <p className="text-sm text-slate-500">Notifikasi prestasi dan badges</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => handleToggle('achievement_notifications')}
                                    className={`relative w-12 h-7 rounded-full transition-colors ${
                                        preferences.achievement_notifications ? 'bg-primary' : 'bg-slate-300'
                                    }`}
                                >
                                    <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                        preferences.achievement_notifications ? 'translate-x-6' : 'translate-x-1'
                                    }`} />
                                </button>
                            </div>

                            {/* Marketing */}
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-pink-100 flex items-center justify-center">
                                        <Bell size={20} className="text-pink-600" />
                                    </div>
                                    <div>
                                        <p className="font-medium text-slate-800">Promosi & Info</p>
                                        <p className="text-sm text-slate-500">Berita dan informasi terbaru</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => handleToggle('marketing_notifications')}
                                    className={`relative w-12 h-7 rounded-full transition-colors ${
                                        preferences.marketing_notifications ? 'bg-primary' : 'bg-slate-300'
                                    }`}
                                >
                                    <span className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                                        preferences.marketing_notifications ? 'translate-x-6' : 'translate-x-1'
                                    }`} />
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Save Button */}
                <div className="flex justify-end">
                    <button
                        onClick={handleSave}
                        disabled={isSaving}
                        className="px-6 py-3 bg-primary text-white rounded-xl font-medium hover:bg-primary/90 transition-colors flex items-center gap-2 shadow-lg shadow-primary/25 disabled:opacity-50"
                    >
                        {isSaving ? (
                            <Loader2 size={18} className="animate-spin" />
                        ) : (
                            <Save size={18} />
                        )}
                        Simpan Pengaturan
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Activity, Loader2, X } from 'lucide-react';
import { getRecentLogins } from '@/lib/api/proctor';

interface LoginUser {
    id: string;
    userId: string;
    fullName: string;
    role: string;
    isActive: boolean; // refers to account status
    lastLoginAt: string;
}

export function RecentLoginsCard({ initialLogins, orgId }: { initialLogins: LoginUser[], orgId: string }) {
    const [logins, setLogins] = useState<LoginUser[]>(initialLogins);
    const [showAllModal, setShowAllModal] = useState(false);
    const [allLogins, setAllLogins] = useState<LoginUser[]>([]);
    const [allLoading, setAllLoading] = useState(false);
    const [searchAll, setSearchAll] = useState('');

    useEffect(() => {
        setLogins(initialLogins);
    }, [initialLogins]);

    // Helper to format time ago for offline users
    const getTimeAgo = (dateString: string) => {
        const now = new Date();
        const past = new Date(dateString);
        const diffMs = now.getTime() - past.getTime();
        const diffMins = Math.floor(diffMs / 60000);

        if (diffMins < 1) return 'baru saja';
        if (diffMins < 60) return `${diffMins} mnt lalu`;

        const diffHours = Math.floor(diffMins / 60);
        if (diffHours < 24) return `${diffHours} jam lalu`;

        const diffDays = Math.floor(diffHours / 24);
        return `${diffDays} hari lalu`;
    };

    // Yang paling baru masuk di atas.
    //
    // Dulu pengguna yang SEDANG online diletakkan lebih dulu, memakai presence
    // realtime Supabase. Sumber itu sudah tidak ada, dan satu-satunya penanda
    // aktivitas yang tersisa adalah `last_sign_in_at` — waktu MASUK, bukan waktu
    // aktif. Menyebutnya "online" akan keliru, jadi yang ditampilkan hanya kapan
    // seseorang terakhir masuk.
    const sortByRecent = (list: LoginUser[]) =>
        [...list].sort((a, b) => {
            const ta = a.lastLoginAt ? new Date(a.lastLoginAt).getTime() : 0;
            const tb = b.lastLoginAt ? new Date(b.lastLoginAt).getTime() : 0;
            return tb - ta;
        });

    const openAllModal = async () => {
        setShowAllModal(true);
        setAllLoading(true);
        try {
            const all = await getRecentLogins(orgId, 1000);
            setAllLogins((all || []).filter((m: any) => m.lastLoginAt) as LoginUser[]);
        } catch (e) {
            console.error('Load all logins error:', e);
            setAllLogins([]);
        } finally {
            setAllLoading(false);
        }
    };

    const sortedLogins = sortByRecent(logins);
    const filteredAll = sortByRecent(allLogins).filter(l =>
        !searchAll.trim() || l.fullName.toLowerCase().includes(searchAll.trim().toLowerCase())
    );

    const renderRow = (login: LoginUser) => {
        return (
            <div
                key={login.id}
                className="flex items-center gap-3 p-2 rounded-lg hover:bg-slate-50 transition-colors"
            >
                {/* Avatar */}
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
                    login.isActive ? 'bg-[#030C4D]/10' : 'bg-slate-100'
                }`}>
                    <span className={`text-xs font-bold ${
                        login.isActive ? 'text-[#030C4D]' : 'text-slate-400'
                    }`}>
                        {login.fullName.charAt(0).toUpperCase()}
                    </span>
                </div>
                {/* Info */}
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-semibold text-slate-800 truncate">{login.fullName}</p>
                    <p className="text-[10px] text-slate-400">{login.role}</p>
                </div>
                {/* Status & Waktu */}
                <div className="shrink-0 text-right flex flex-col items-end">
                    {login.lastLoginAt ? (
                        <span className="inline-flex items-center justify-center px-2 py-0.5 rounded-lg text-[10px] font-bold border bg-slate-100 text-slate-500 border-slate-200">
                            {getTimeAgo(login.lastLoginAt)}
                        </span>
                    ) : (
                        <span className="text-[10px] text-slate-400">Belum pernah masuk</span>
                    )}
                </div>
            </div>
        );
    };

    return (
        <div className="bg-white rounded-lg border border-[#0038A8]/30 overflow-hidden shadow-sm">
            <div className="px-5 py-4 border-b border-[#0038A8]/20 bg-gradient-to-r from-[#030C4D]/[.02] to-transparent flex items-center justify-between">
                <h2 className="text-sm font-bold text-slate-900">Aktivitas Login</h2>
                <button
                    onClick={openAllModal}
                    className="text-[11px] font-bold text-[#0038A8] hover:text-[#030C4D] px-2.5 py-1 rounded-lg border border-[#0038A8]/30 hover:bg-[#0038A8]/5 transition-colors"
                >
                    Lihat Semua
                </button>
            </div>
            <div className="p-3 max-h-72 overflow-y-auto">
                {sortedLogins.length > 0 ? (
                    <div className="space-y-2">
                        {sortedLogins.map(renderRow)}
                    </div>
                ) : (
                    <div className="py-8 text-center">
                        <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-3">
                            <Activity size={20} className="text-slate-400" />
                        </div>
                        <p className="text-xs text-slate-500">Belum ada aktivitas login</p>
                    </div>
                )}
            </div>

            {/* MODAL: semua pengguna yang pernah login, terbaru paling atas */}
            {showAllModal && (
                <div
                    className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4"
                    onClick={() => setShowAllModal(false)}
                >
                    <div
                        className="bg-white rounded-xl shadow-2xl max-w-lg w-full overflow-hidden flex flex-col max-h-[85dvh]"
                        onClick={e => e.stopPropagation()}
                    >
                        <div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                            <div>
                                <h3 className="font-bold text-slate-800">Semua Aktivitas Login</h3>
                                {!allLoading && (
                                    <p className="text-[11px] text-slate-500 mt-0.5">
                                        {allLogins.length} pernah login
                                    </p>
                                )}
                            </div>
                            <button onClick={() => setShowAllModal(false)} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:bg-slate-200 rounded-lg transition-colors">
                                <X size={16} />
                            </button>
                        </div>
                        <div className="px-4 pt-3">
                            <input
                                type="text"
                                value={searchAll}
                                onChange={(e) => setSearchAll(e.target.value)}
                                placeholder="Cari nama..."
                                className="w-full bg-white border border-slate-200 text-slate-800 placeholder:text-slate-400 focus:ring-2 focus:ring-[#0038A8]/40 outline-none px-3 py-2 rounded-lg text-sm"
                            />
                        </div>
                        <div className="p-3 overflow-y-auto flex-1">
                            {allLoading ? (
                                <div className="py-10 flex items-center justify-center">
                                    <Loader2 size={24} className="text-[#0038A8] animate-spin" />
                                </div>
                            ) : filteredAll.length > 0 ? (
                                <div className="space-y-1.5">
                                    {filteredAll.map(renderRow)}
                                </div>
                            ) : (
                                <p className="py-8 text-center text-xs text-slate-400">Tidak ada data yang cocok</p>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

