"use client";
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Calendar, Plus, Search, Clock, Loader2, Lock, Unlock,
    BookOpen, AlertCircle, Check, X, Trash2,
    ChevronRight, Shield, CalendarClock, Users, BarChart3, ArrowLeft
} from 'lucide-react';
import { getProctorOrganization, getActiveSchoolYear } from '@/lib/api/proctor';
import {
    listPASPeriods,
    listSubjects,
    createPASPeriodAction,
    lockPASPeriodAction,
    deletePASPeriodAction,
} from '@/lib/api/pas';
import { getSessionUser } from '@/lib/session';
import { useRouter } from 'next/navigation';
import { useMemoryState } from '@/lib/useMemoryState';

type PeriodType = 'pas' | 'pat' | 'pts' | 'pkn';
type Semester = 'ganjil' | 'genap';

export default function ProctorPASPage({ activeTab = 'all' }: { activeTab?: string }) {
    const router = useRouter();
    const [user, setUser] = useState<any>(null);
    const [org, setOrg] = useState<any>(null);
    const [periods, setPeriods] = useMemoryState<any[]>('proktor_pas_periods', []);
    const [subjects, setSubjects] = useMemoryState<any[]>('proktor_pas_subjects', []);
    const [isLoading, setIsLoading] = useMemoryState('proktor_pas_isLoading', true);
    const [searchQuery, setSearchQuery] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isAddPeriodOpen, setIsAddPeriodOpen] = useState(false);

    const [periodForm, setPeriodForm] = useState({
        name: '',
        type: 'pas' as PeriodType,
        school_year: '',
        semester: 'ganjil' as Semester,
        start_date: '',
        end_date: '',
    });

    useEffect(() => {
        loadData();
        // Auto-injected smart sync (Window Focus)
        const handleFocus = () => { if (typeof loadData === 'function') loadData(); };
        window.addEventListener('focus', handleFocus);
        return () => window.removeEventListener('focus', handleFocus);
    }, []);

    const loadData = async () => {
        // setIsLoading(true); // Disabled for silent background sync
        const authUser = await getSessionUser();
        if (authUser) {
            setUser(authUser);
            const orgData = await getProctorOrganization();
            if (orgData) {
                setOrg(orgData);
                const [periodList, subjectList, activeYear] = await Promise.all([
                    listPASPeriods(orgData.id),
                    listSubjects(orgData.id),
                    getActiveSchoolYear(orgData.id)
                ]);
                setPeriods(periodList || []);
                setSubjects(subjectList || []);
                if (activeYear && activeYear.year) {
                    setPeriodForm(prev => ({ ...prev, school_year: activeYear.year }));
                }
            }
        }
        setIsLoading(false);
    };

    const handleCreatePeriod = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!org || !user) return;
        setIsSubmitting(true);

        const result = await createPASPeriodAction(org.id, {
            name: periodForm.name,
            type: periodForm.type,
            school_year: periodForm.school_year,
            semester: periodForm.semester,
            start_date: periodForm.start_date,
            end_date: periodForm.end_date,
        });

        if (result.success) {
            setIsAddPeriodOpen(false);
            setPeriodForm(prev => ({ ...prev, name: '', type: 'pas', semester: 'ganjil', start_date: '', end_date: '' }));
            await loadData();
        } else {
            alert(result.error || 'Gagal membuat periode');
        }
        setIsSubmitting(false);
    };

    const handleToggleLock = async (periodId: string, currentLock: boolean) => {
        if (!confirm(currentLock
            ? 'Buka kunci periode ini?'
            : 'Kunci periode ini? Tidak bisa diedit setelah dikunci.')) return;

        const result = await lockPASPeriodAction(periodId, !currentLock);
        if (result.success) await loadData();
        else alert(result.error);
    };

    const handleDeletePeriod = async (periodId: string) => {
        if (!confirm('Yakin menghapus periode ini?')) return;
        const result = await deletePASPeriodAction(periodId);
        if (result.success) await loadData();
        else alert(result.error);
    };

    const formatDate = (dateStr: string) => {
        if (!dateStr) return '-';
        return new Date(dateStr).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
    };

    const getPeriodTypeLabel = (type: string) => {
        const labels: Record<string, string> = { pas: 'PAS/ASAS', pat: 'PAT/ASAT', pts: 'PTS/UTS', pkn: 'Asesmen Lainnya' };
        return labels[type] || type.toUpperCase();
    };

    const filteredPeriods = periods.filter(p => {
        const matchesSearch = p.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                              p.school_year?.toLowerCase().includes(searchQuery.toLowerCase());

        if (!matchesSearch) return false;

        if (activeTab && activeTab !== 'all') {
            const now = new Date();
            const start = new Date(p.start_date);
            const end = new Date(p.end_date);
            const isActive = start <= now && end >= now && !p.is_locked;
            const isFinished = end < now;
            const isDraft = !isActive && !isFinished; // e.g. future or locked

            if (activeTab === 'active' && !isActive) return false;
            if (activeTab === 'finished' && !isFinished) return false;
            if (activeTab === 'draft' && !isDraft) return false;
        }

        return true;
    });

    if (isLoading) {
        return (
            <div className="flex justify-center py-20">
                <Loader2 size={48} className="text-primary animate-spin" />
            </div>
        );
    }

    return (
        <div className="max-w-6xl mx-auto space-y-6 pb-20">
            {/* Actions Bar */}
            <div className="flex flex-col sm:flex-row items-center gap-3">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input
                        type="text"
                        placeholder="Cari periode..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-white border border-slate-200 rounded-xl py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/10 outline-none"
                    />
                </div>
                <button
                    onClick={() => setIsAddPeriodOpen(true)}
                    className="w-full sm:w-auto px-6 py-3 text-sm bg-primary text-white rounded-xl hover:bg-primary/90 flex items-center justify-center gap-2 shadow-lg shadow-primary/20 font-medium transition-all"
                >
                    <Plus size={16} /> Tambah PAS
                </button>
            </div>



            {/* Period List */}
            {filteredPeriods.length === 0 ? (
                <div className="py-16 text-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl">
                    <Shield size={40} className="mx-auto mb-3 opacity-40" />
                    <p className="font-medium">Belum ada periode PAS/PAT</p>
                    <p className="text-sm mt-1">Klik "Tambah PAS" untuk memulai</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {filteredPeriods.map((period) => {
                        const now = new Date();
                        const start = new Date(period.start_date);
                        const end = new Date(period.end_date);
                        const isActive = start <= now && end >= now && !period.is_locked;
                        const isPast = end < now;
                        const subjectCount = period._count?.pas_subjects || 0;

                        return (
                            <motion.div
                                key={period.id}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className={`bg-white border rounded-lg p-5 md:p-6 transition-all hover:shadow-md ${
                                    period.is_locked ? 'border-slate-200 opacity-75' :
                                    isActive ? 'border-blue-200 shadow-sm bg-blue-50/10' :
                                    isPast ? 'border-slate-100 opacity-60' : 'border-slate-200'
                                }`}
                            >
                                <div className="flex items-start justify-between gap-4">
                                    <div className="flex items-start gap-4 flex-1">
                                        <div className={`w-12 h-12 rounded-lg flex items-center justify-center shrink-0 border ${
                                            period.is_locked ? 'bg-slate-50 text-slate-400 border-slate-200' :
                                            isActive ? 'bg-blue-50 text-blue-500 border-blue-100' : 'bg-slate-50 text-slate-500 border-slate-200'
                                        }`}>
                                            <Shield size={22} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <h3 className="font-bold text-slate-900 text-lg leading-tight mb-2">{period.name}</h3>
                                            <div className="flex flex-wrap items-center gap-2 mb-2">
                                                <span className={`px-2.5 py-0.5 rounded-md text-xs font-semibold ${
                                                    period.is_locked ? 'bg-slate-100 text-slate-500' :
                                                    isActive ? 'bg-blue-50 text-blue-600 border border-blue-200' :
                                                    isPast ? 'bg-slate-50 text-slate-400 border border-slate-200' : 'bg-slate-50 text-slate-600 border border-slate-200'
                                                }`}>
                                                    {getPeriodTypeLabel(period.type)} {period.semester === 'ganjil' ? 'Ganjil' : 'Genap'}
                                                </span>
                                                <span className="px-2 py-0.5 bg-slate-50 text-slate-500 text-xs font-semibold border border-slate-200 rounded-md">
                                                    {period.school_year}
                                                </span>
                                                {period.is_locked && (
                                                    <span className="px-2 py-0.5 bg-amber-50 text-amber-600 text-xs font-bold rounded-md border border-amber-200 flex items-center gap-1">
                                                        <Lock size={10} /> TERKUNCI
                                                    </span>
                                                )}
                                            </div>
                                            <div className="flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-slate-500 mt-1">
                                                <span className="flex items-center gap-1.5 font-medium">
                                                    <Calendar size={14} className={isActive ? 'text-blue-400' : 'text-slate-400'} />
                                                    <span className="text-slate-600">{formatDate(period.start_date)}</span> — <span className="text-slate-600">{formatDate(period.end_date)}</span>
                                                </span>
                                                <span className="flex items-center gap-1.5 font-medium">
                                                    <BookOpen size={14} className={isActive ? 'text-blue-400' : 'text-slate-400'} />
                                                    <span className="text-slate-600">{subjectCount} Mapel</span>
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2 shrink-0">
                                        <button
                                            onClick={() => router.push(`/dashboard/proktor/exams/pas/${period.id}`)}
                                            className="px-4 py-1.5 text-sm bg-white text-slate-700 hover:text-blue-600 rounded-lg transition-all font-semibold border border-slate-300 hover:border-blue-300 flex items-center gap-1 shadow-sm">
                                            Kelola <ChevronRight size={14} />
                                        </button>

                                        {!period.is_locked && (
                                            <button
                                                onClick={() => handleToggleLock(period.id, false)}
                                                className="p-2 text-slate-400 hover:text-amber-500 hover:bg-amber-50 rounded-lg transition-all"
                                                title="Kunci">
                                                <Lock size={15} />
                                            </button>
                                        )}

                                        {period.is_locked && (
                                            <button
                                                onClick={() => handleToggleLock(period.id, true)}
                                                className="p-2 text-slate-400 hover:text-emerald-500 hover:bg-emerald-50 rounded-lg transition-all"
                                                title="Buka Kunci">
                                                <Unlock size={15} />
                                            </button>
                                        )}

                                        {!period.is_locked && (
                                            <button
                                                onClick={() => handleDeletePeriod(period.id)}
                                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all">
                                                <Trash2 size={15} />
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        );
                    })}
                </div>
            )}

            {/* CREATE PERIOD MODAL */}
            <AnimatePresence>
                {isAddPeriodOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60">
                        <motion.div
                            initial={{ scale: 0.95, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.95, opacity: 0 }}
                            className="bg-white w-full max-w-lg rounded-2xl p-6 relative max-h-[90vh] overflow-y-auto">
                            <button onClick={() => setIsAddPeriodOpen(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600">
                                <X size={20} />
                            </button>
                            <div className="flex items-center gap-2 mb-4">
                                <div className="w-10 h-10 bg-primary/10 rounded-xl flex items-center justify-center">
                                    <Shield size={20} className="text-primary" />
                                </div>
                                <div>
                                    <h3 className="text-lg font-bold text-slate-900">Tambah PAS Baru</h3>
                                    <p className="text-xs text-slate-400">Periode ujian akhir semester/sekolah</p>
                                </div>
                            </div>
                            <form onSubmit={handleCreatePeriod} className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1.5">Nama Periode *</label>
                                    <input required type="text" placeholder="Contoh: PAS Ganjil 2025/2026"
                                        value={periodForm.name}
                                        onChange={e => setPeriodForm({ ...periodForm, name: e.target.value })}
                                        className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none" />
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Tipe</label>
                                        <select value={periodForm.type}
                                            onChange={e => setPeriodForm({ ...periodForm, type: e.target.value as PeriodType })}
                                            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none">
                                            <option value="pas">PAS/ASAS</option>
                                            <option value="pat">PAT/ASAT</option>
                                            <option value="pts">PTS/UTS</option>
                                            <option value="pkn">Asesmen Lainnya</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Semester</label>
                                        <select value={periodForm.semester}
                                            onChange={e => setPeriodForm({ ...periodForm, semester: e.target.value as Semester })}
                                            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none">
                                            <option value="ganjil">Ganjil</option>
                                            <option value="genap">Genap</option>
                                        </select>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1.5">Tahun Ajaran *</label>
                                    <input required type="text" placeholder="Data tahun ajaran aktif tidak ditemukan"
                                        value={periodForm.school_year}
                                        disabled
                                        className="w-full border border-slate-200 rounded-xl p-3 text-sm bg-slate-50 text-slate-500 cursor-not-allowed outline-none" />
                                    <p className="text-[11px] text-slate-400 mt-1">Tahun ajaran diambil dari Pengaturan {'>'} Tahun Ajaran yang sedang aktif.</p>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Tanggal Mulai</label>
                                        <input required type="date"
                                            value={periodForm.start_date}
                                            onChange={e => setPeriodForm({ ...periodForm, start_date: e.target.value })}
                                            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none" />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Tanggal Selesai</label>
                                        <input required type="date"
                                            value={periodForm.end_date}
                                            onChange={e => setPeriodForm({ ...periodForm, end_date: e.target.value })}
                                            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary/10 outline-none" />
                                    </div>
                                </div>
                                <button type="submit" disabled={isSubmitting}
                                    className="w-full py-3 bg-primary text-white rounded-xl font-semibold flex items-center justify-center gap-2 disabled:opacity-50">
                                    {isSubmitting ? <Loader2 size={18} className="animate-spin" /> : <Check size={18} />}
                                    Simpan
                                </button>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { getProctorOrganization } from '@/lib/api/proctor';
import { getBankQuestions, getQuestionBankAction, QuestionType, saveQuestionAction } from '@/lib/api/questions';
import { getSessionUser } from '@/lib/session';
import { X, ArrowLeft, Loader2, Save, Eye, Check, ListChecks, ToggleLeft, Layers, Edit3, FileQuestion, CheckCircle2, ArrowRightLeft } from 'lucide-react';
import { LatexRenderer } from '@/app/components/questions/LatexRenderer';
import { TipTapEditor } from '@/app/components/questions/TipTapEditor';
import PreviewModal from '@/app/components/questions/PreviewModal';
import { MCQForm } from '@/app/components/questions/forms/MCQForm';
import { TrueFalseForm } from '@/app/components/questions/forms/TrueFalseForm';
import { MatchingForm } from '@/app/components/questions/forms/MatchingForm';
import { CategorizationForm } from '@/app/components/questions/forms/CategorizationForm';
import { ShortAnswerForm } from '@/app/components/questions/forms/ShortAnswerForm';
import { EssayForm } from '@/app/components/questions/forms/EssayForm';
import { useMemoryState } from '@/lib/useMemoryState';


const QUESTION_TYPES = [
    { value: 'mcq', label: 'Pilihan Ganda', icon: ListChecks },
    { value: 'mcq_complex', label: 'PG Kompleks', icon: CheckCircle2 },
    { value: 'true_false', label: 'Benar / Salah', icon: ToggleLeft },
    { value: 'matching', label: 'Penjodohan', icon: ArrowRightLeft },
    { value: 'categorization', label: 'Kategori', icon: Layers },
    { value: 'short_answer', label: 'Isian Singkat', icon: Edit3 },
    { value: 'essay', label: 'Essay / Uraian', icon: FileQuestion },
];

// Strip $ delimiters from LaTeX text before saving
function stripLatexDelimiters(text: string): string {
    if (!text) return text;
    // Remove inline math delimiters: $...$ or $$...$$
    return text.replace(/\$\$[\s\S]*?\$\$/g, (match) => {
        // Extract content between $$...$$
        return match.slice(2, -2).trim();
    }).replace(/(?<!\$)\$(?!\$)[^$]*\$(?!\$)/g, (match) => {
        // Extract content between $...$ (not $$)
        return match.slice(1, -1).trim();
    });
}

// Strip delimiters for Quill HTML content
function stripHtmlLatexDelimiters(html: string): string {
    if (!html) return html;
    // Process text nodes inside HTML
    return html.replace(/\$\$([\s\S]*?)\$\$/g, (_, content) => content.trim())
                .replace(/(?<!\$)\$(?!\$)([^$]*)\$(?!\$)/g, (_, content) => content.trim());
}

export default function QuestionEditPage() {
    const params = useParams();
    const router = useRouter();
    const bankId = params.bankId as string;
    const questionId = params.questionId as string;
    const isNewQuestion = !questionId || questionId === 'new';

    const [org, setOrg] = useState<any>(null);
    const [bankInfo, setBankInfo] = useState<any>(null);
    const [isLoading, setIsLoading] = useMemoryState(`proktor_questions_${bankId}_edit_isLoading`, true);

    // Editor state
    const [editingQuestion, setEditingQuestion] = useState<any>(null);
    const [questionText, setQuestionText] = useState('');
    const [options, setOptions] = useMemoryState<any[]>(`proktor_questions_${bankId}_edit_options`, []);
    const [selectedType, setSelectedType] = useState<QuestionType>('mcq');
    const [scoreDefault, setScoreDefault] = useState(1);
    const [metadata, setMetadata] = useState<any>({});
    const [categories, setCategories] = useMemoryState<string[]>(`proktor_questions_${bankId}_edit_categories`, []);
    const [kisiKisi, setKisiKisi] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showTypeDropdown, setShowTypeDropdown] = useState(false);
    const [validationErrors, setValidationErrors] = useMemoryState<string[]>(`proktor_questions_${bankId}_edit_validationErrors`, []);

    // Preview modal
    const [isViewModalOpen, setIsViewModalOpen] = useState(false);
    const [viewingQuestion, setViewingQuestion] = useState<any>(null);
    const [matchingAnswers, setMatchingAnswers] = useState<Record<string, string>>({});

    // Deduplicate options by id
    const deduplicateOptions = (opts: any[]) => {
        const seen = new Set<string>();
        return opts.filter(o => {
            if (!o.id) return true;
            if (seen.has(o.id)) return false;
            seen.add(o.id);
            return true;
        });
    };

    const addOption = () => {
        if (selectedType === 'true_false') {
            setOptions([...options, { text: '', isCorrect: false, order: options.length }]);
        } else {
            setOptions([...options, { text: '', isCorrect: false, order: options.length }]);
        }
    };

    const removeOption = (idx: number) => {
        setOptions(options.filter((_, i) => i !== idx));
    };

    const updateOption = (idx: number, fields: any) => {
        const newOpts = [...options];
        newOpts[idx] = { ...newOpts[idx], ...fields };
        setOptions(newOpts);
    };

    const validateQuestion = (): boolean => {
        const errors: string[] = [];
        const cleanQuestionText = stripHtmlLatexDelimiters(questionText);
        if (!cleanQuestionText || cleanQuestionText.trim() === '' || cleanQuestionText === '<p></p>' || cleanQuestionText === '<p><br></p>') {
            errors.push('Pertanyaan tidak boleh kosong');
        }
        if (selectedType === 'mcq' || selectedType === 'mcq_complex') {
            const emptyOptions = options.filter(o => !o.text || o.text.trim() === '');
            if (emptyOptions.length > 0) errors.push('Semua opsi jawaban harus diisi');
            const hasCorrect = options.some(o => o.isCorrect === true);
            if (!hasCorrect) errors.push('Pilih jawaban yang benar');
        }
        if (selectedType === 'true_false') {
            const emptyOptions = options.filter(o => !o.text || o.text.trim() === '');
            if (emptyOptions.length > 0) errors.push('Semua pernyataan harus diisi');
        }
        if (selectedType === 'short_answer' || selectedType === 'essay') {
            // OK
        }
        if (!scoreDefault || scoreDefault <= 0) {
            errors.push('Poin harus lebih dari 0');
        }
        setValidationErrors(errors);
        return errors.length === 0;
    };

    const handleSave = async () => {
        if (!validateQuestion()) return;
        if (!org) return;
        setIsSubmitting(true);

        // Strip $ delimiters from question text HTML
        const cleanQuestionText = stripHtmlLatexDelimiters(questionText);
        // Strip $ delimiters from option texts
        const cleanOptions = options.map((opt, i) => ({
            id: opt.id,
            text: stripLatexDelimiters(opt.text || ''),
            isCorrect: opt.isCorrect,
            order: i,
            weight: opt.weight ?? 1,
            metadata: {
                match_texts: opt.match_texts || [],
                category_names: opt.category_names || []
            }
        }));

        const result = await saveQuestionAction({
            id: editingQuestion?.id,
            bankId: bankId,
            type: selectedType,
            questionText: cleanQuestionText,
            difficulty: 'medium',
            scoreDefault: scoreDefault,
            metadata: {
                ...metadata,
                categories: selectedType === 'categorization' ? categories : [],
                kisi_kisi: kisiKisi
            },
            options: (selectedType === 'short_answer' || selectedType === 'essay') ? [] : cleanOptions
        });

        if (result.success) {
            router.push(`/dashboard/proktor/questions/${bankId}`);
        } else {
            alert('Gagal menyimpan: ' + result.error);
        }
        setIsSubmitting(false);
    };

    const handleOpenPreview = () => {
        const tempQ = {
            id: editingQuestion?.id || 'preview',
            type: selectedType,
            question_text: questionText,
            metadata: { ...metadata, categories },
            bank_question_options: deduplicateOptions(options).map((opt, i) => ({
                id: opt.id || `temp-${i}`,
                option_text: stripLatexDelimiters(opt.text || ''),
                is_correct: opt.isCorrect,
                order: i,
                metadata: {
                    match_texts: opt.match_texts || [],
                    category_names: opt.category_names || []
                }
            }))
        };
        setViewingQuestion(tempQ);
        setIsViewModalOpen(true);
    };

    const handleTypeChange = (type: QuestionType) => {
        setSelectedType(type);
        if (type === 'true_false') {
            setOptions([
                { text: '', isCorrect: true, order: 0, weight: 1 },
                { text: '', isCorrect: false, order: 1, weight: 0 }
            ]);
        } else if (type === 'mcq') {
            setOptions([
                { text: '', isCorrect: true, order: 0, weight: 1 },
                { text: '', isCorrect: false, order: 1, weight: 0 },
                { text: '', isCorrect: false, order: 2, weight: 0 },
                { text: '', isCorrect: false, order: 3, weight: 0 }
            ]);
        } else if (type === 'matching') {
            setOptions([
                { text: '', isCorrect: false, order: 0, weight: 0, match_texts: [] },
                { text: '', isCorrect: false, order: 1, weight: 0, match_texts: [] }
            ]);
        } else if (type === 'categorization') {
            setOptions([
                { text: '', isCorrect: false, order: 0, weight: 0, metadata: { category_names: [] } }
            ]);
        } else {
            setOptions([]);
        }
    };

    // Load initial data
    useEffect(() => {
        async function loadData() {
            try {
                const user = await getSessionUser();
                if (!user) { router.push('/'); return; }

                const orgData = await getProctorOrganization();
                if (!orgData) { router.push('/'); return; }
                setOrg(orgData);

                const bankData = await getQuestionBankAction(bankId);
                setBankInfo(bankData);

                if (!isNewQuestion) {
                    const questionsData = await getBankQuestions(bankId);
                    const existingQuestion = (questionsData || []).find((q: any) => q.id === questionId);
                    if (existingQuestion) {
                        setEditingQuestion(existingQuestion);
                        setQuestionText(existingQuestion.question_text || '');
                        setSelectedType(existingQuestion.type || 'mcq');
                        setScoreDefault(existingQuestion.score_default || 1);
                        setMetadata(existingQuestion.metadata || {});
                        setCategories(existingQuestion.metadata?.categories || []);
                        setKisiKisi(existingQuestion.metadata?.kisi_kisi || '');

                        const loadedOpts = deduplicateOptions(
                            (existingQuestion.bank_question_options || []).map((o: any) => ({
                                id: o.id,
                                text: o.option_text || o.text || '',
                                isCorrect: o.is_correct,
                                order: o.order,
                                weight: o.weight,
                                match_texts: o.metadata?.match_texts || [],
                                category_names: o.metadata?.category_names || []
                            }))
                        );

                        if (existingQuestion.type === 'true_false') {
                            setOptions(loadedOpts);
                        } else if (existingQuestion.type === 'matching') {
                            setMetadata((prev: any) => ({
                                ...prev,
                                right_items: existingQuestion.metadata?.right_items || []
                            }));
                            setOptions(loadedOpts);
                        } else if (existingQuestion.type === 'short_answer') {
                            setMetadata((prev: any) => ({
                                ...prev,
                                blanks: existingQuestion.metadata?.blanks || [{}, {}, {}]
                            }));
                            setOptions([]);
                        } else if (existingQuestion.type === 'categorization') {
                            setOptions(loadedOpts);
                        } else {
                            setOptions(loadedOpts);
                        }
                    }
                } else {
                    setOptions([
                        { text: '', isCorrect: true, order: 0, weight: 1 },
                        { text: '', isCorrect: false, order: 1, weight: 0 },
                        { text: '', isCorrect: false, order: 2, weight: 0 },
                        { text: '', isCorrect: false, order: 3, weight: 0 }
                    ]);
                }
            } catch (error) {
                console.error('Error loading data:', error);
            } finally {
                setIsLoading(false);
            }
        }
        loadData();
        // Auto-injected smart sync (Window Focus)
        const handleFocus = () => { if (typeof loadData === 'function') loadData(); };
        window.addEventListener('focus', handleFocus);
        return () => window.removeEventListener('focus', handleFocus);
    }, [bankId, questionId, isNewQuestion, router]);

    const selectedTypeInfo = QUESTION_TYPES.find(t => t.value === selectedType) || QUESTION_TYPES[0];

    // Right item management (for matching)
    const addRightItem = () => {
        setMetadata((prev: any) => ({
            ...prev,
            right_items: [...(prev.right_items || []), '']
        }));
    };

    const removeRightItem = (idx: number) => {
        setMetadata((prev: any) => ({
            ...prev,
            right_items: (prev.right_items || []).filter((_: any, i: number) => i !== idx)
        }));
    };

    const updateRightItem = (idx: number, value: string) => {
        setMetadata((prev: any) => {
            const newItems = [...(prev.right_items || [])];
            newItems[idx] = value;
            return { ...prev, right_items: newItems };
        });
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-8 h-8 animate-spin text-primary" />
                    <p className="text-sm text-slate-500">Memuat data...</p>
                </div>
            </div>
        );
    }

    const letters = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];

    return (
        <div className="min-h-screen bg-slate-50 flex flex-col">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-4">
                    <button
                        onClick={() => router.push(`/dashboard/proktor/questions/${bankId}`)}
                        className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
                    >
                        <ArrowLeft size={20} className="text-slate-600" />
                    </button>
                    <div>
                        <h1 className="text-lg font-semibold text-slate-900">
                            {isNewQuestion ? 'Tambah Soal Baru' : 'Edit Soal'}
                        </h1>
                        <p className="text-sm text-slate-500">{bankInfo?.title || 'Bank Soal'}</p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <button
                        onClick={handleOpenPreview}
                        className="flex items-center gap-2 px-4 py-2 text-sm font-medium border border-slate-200 rounded-xl bg-white text-slate-600 hover:bg-slate-50 transition-all"
                    >
                        <Eye size={16} />
                        Preview
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={isSubmitting}
                        className="flex items-center gap-2 px-5 py-2 text-sm font-semibold bg-gradient-to-r from-amber-500 to-pink-500 text-white rounded-xl hover:from-amber-600 hover:to-pink-600 transition-all shadow-lg shadow-pink-500/25 disabled:opacity-50"
                    >
                        {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                        Simpan
                    </button>
                </div>
            </div>

            {/* Validation Errors */}
            {validationErrors.length > 0 && (
                <div className="px-6 py-3 bg-rose-50 border-b border-rose-200 shrink-0">
                    <div className="flex items-center gap-2 max-w-5xl mx-auto">
                        <p className="text-xs font-semibold text-rose-700">Mohon perbaiki:</p>
                        <div className="flex gap-3">
                            {validationErrors.map((error, idx) => (
                                <span key={idx} className="text-xs text-rose-600">• {error}</span>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Main Content */}
            <div className="flex-1 overflow-y-auto">
                <div className="max-w-5xl mx-auto p-6 space-y-6">
                    {/* Question Text Editor */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                        <div className="mb-4">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Pertanyaan</label>
                        </div>
                        <TipTapEditor
                            content={questionText}
                            onChange={setQuestionText}
                            placeholder="Tuliskan pertanyaan di sini..."
                            minHeight="200px"
                        />
                    </div>

                    {/* Options Area */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                        {/* Header row */}
                        <div className="flex items-center justify-between pb-4 border-b border-slate-100">
                            <div className="flex items-center gap-2">
                                <span className="text-sm font-semibold text-slate-700">Opsi Jawaban</span>
                            </div>
                            {(selectedType !== 'short_answer' && selectedType !== 'essay') && (
                                <button
                                    type="button"
                                    onClick={addOption}
                                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-blue-600 bg-blue-50 rounded-lg hover:bg-blue-100 transition-colors"
                                >
                                    <span>+</span> Tambah Opsi
                                </button>
                            )}
                        </div>

                        {/* True/False Options */}
                        {selectedType === 'true_false' && (
                            <TrueFalseForm
                                options={deduplicateOptions(options)}
                                onAddOption={addOption}
                                onInsertOption={(idx) => {}}
                                onRemoveOption={removeOption}
                                onUpdateOption={updateOption}
                            />
                        )}

                        {/* MCQ / MCQ Complex Options */}
                        {(selectedType === 'mcq' || selectedType === 'mcq_complex') && (
                            <MCQForm
                                options={deduplicateOptions(options)}
                                isComplex={selectedType === 'mcq_complex'}
                                onAddOption={addOption}
                                onInsertOption={(idx) => {}}
                                onRemoveOption={removeOption}
                                onUpdateOption={updateOption}
                                onSetAllCorrect={(idx) => {
                                    const newOpts = options.map((o, i) => ({ ...o, isCorrect: i === idx }));
                                    setOptions(newOpts);
                                }}
                                onToggleCorrect={(idx) => updateOption(idx, { isCorrect: !options[idx].isCorrect })}
                            />
                        )}

                        {/* Matching Options */}
                        {selectedType === 'matching' && (
                            <MatchingForm
                                options={deduplicateOptions(options)}
                                rightItems={(metadata as any).right_items || []}
                                onAddLeftItem={addOption}
                                onRemoveLeftItem={removeOption}
                                onUpdateLeftItem={(idx, text) => updateOption(idx, { text })}
                                onAddRightItem={addRightItem}
                                onRemoveRightItem={removeRightItem}
                                onUpdateRightItem={updateRightItem}
                                onSetLeftMatch={(optIndex, rightTexts) => updateOption(optIndex, { match_texts: rightTexts })}
                            />
                        )}

                        {/* Categorization Options */}
                        {selectedType === 'categorization' && (
                            <CategorizationForm
                                options={deduplicateOptions(options)}
                                categories={categories}
                                onAddItem={addOption}
                                onInsertItem={(idx) => {}}
                                onRemoveItem={removeOption}
                                onUpdateItem={(idx, text) => updateOption(idx, { text })}
                                onSetCategories={setCategories}
                                onSetItemCategory={(optIndex, cats) => updateOption(optIndex, { category_names: cats })}
                            />
                        )}

                        {/* Short Answer */}
                        {selectedType === 'short_answer' && (
                            <ShortAnswerForm
                                blanks={(metadata as any).blanks || []}
                                onAddBlank={() => {
                                    const blanks = [...((metadata as any).blanks || []), { answer: '', variations: [] }];
                                    setMetadata((prev: any) => ({ ...prev, blanks }));
                                }}
                                onRemoveBlank={(idx) => {
                                    const blanks = ((metadata as any).blanks || []).filter((_: any, i: number) => i !== idx);
                                    setMetadata((prev: any) => ({ ...prev, blanks }));
                                }}
                                onUpdateBlank={(idx, fields) => {
                                    const blanks = [...((metadata as any).blanks || [])];
                                    blanks[idx] = { ...blanks[idx], ...fields };
                                    setMetadata((prev: any) => ({ ...prev, blanks }));
                                }}
                            />
                        )}

                        {/* Essay */}
                        {selectedType === 'essay' && (
                            <EssayForm />
                        )}
                    </div>

                    {/* Kisi-kisi */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                        <div className="mb-3">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Kisi-kisi</label>
                        </div>
                        <textarea
                            value={kisiKisi}
                            onChange={(e) => setKisiKisi(e.target.value)}
                            placeholder="Kisi-kisi soal (opsional)..."
                            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-400 resize-none"
                            rows={3}
                        />
                    </div>
                </div>
            </div>

            {/* Preview Modal */}
            {isViewModalOpen && (
                <PreviewModal
                    isOpen={isViewModalOpen}
                    onClose={() => setIsViewModalOpen(false)}
                    bankInfo={bankInfo}
                    viewingQuestion={viewingQuestion}
                    setViewingQuestion={setViewingQuestion}
                    filteredQuestions={[]}
                    currentPreviewIndex={0}
                    setCurrentPreviewIndex={() => {}}
                    matchingAnswers={matchingAnswers}
                    setMatchingAnswers={setMatchingAnswers}
                    setQuestions={() => {}}
                    onFinish={() => setIsViewModalOpen(false)}
                />
            )}
        </div>
    );
}

