                                    const topDimName = topDimEntry
                                        ? details.dimensions?.find((d: any) => d.id === topDimEntry[0])?.name
                                        : null;

                                    return (
                                        <motion.div
                                            key={ans.id}
                                            initial={{ opacity: 0, y: 12 }}
                                            animate={{ opacity: 1, y: 0 }}
