                                        </div>
                                    )}
                                </div>
                            </motion.div>
                        )
                    })}

                    {results.length === 0 && (
                        <div className="col-span-full py-20 px-6 text-center bg-white border border-dashed border-slate-200 rounded-2xl max-w-xl mx-auto w-full flex flex-col items-center">
