  ordering: { bg: 'bg-pink-50', text: 'text-pink-600', border: 'border-pink-200' },
  likert: { bg: 'bg-teal-50', text: 'text-teal-600', border: 'border-teal-200' },
  forced_choice: { bg: 'bg-fuchsia-50', text: 'text-fuchsia-600', border: 'border-fuchsia-200' },
  checklist: { bg: 'bg-sky-50', text: 'text-sky-600', border: 'border-sky-200' },
  ranking: { bg: 'bg-lime-50', text: 'text-lime-600', border: 'border-lime-200' },
  paired_comparison: { bg: 'bg-pink-50', text: 'text-pink-600', border: 'border-pink-200' },
};

export function getQuestionTypeColor(type: QuestionType | string) {
  return QUESTION_TYPE_COLORS[type as QuestionType] || { bg: 'bg-slate-50', text: 'text-slate-600', border: 'border-slate-200' };
}

// ─── Answer Types ────────────────────────────────────────────

export type AnswerValue = string | string[] | Record<string, any> | null | undefined;

export interface StudentAnswer {
  question_id: string;
  selected_option_id?: string;
  essay_answer?: string;
  is_doubtful: boolean;
  answered_at?: string;
}

// ─── Matching Answer (for matching/categorization questions) ─

export interface MatchingAnswer {
  [questionId: string]: string; // Maps option to answer
}

export interface CategorizationAnswer {
  [itemId: string]: string; // Maps item to category
}

// ─── Helpers ────────────────────────────────────────────────

export function isCorrectAnswer(question: Question, answer: AnswerValue): boolean {
  const options = question.bank_question_options || [];

  switch (question.type) {
    case 'mcq': {
      const correctOption = options.find(o => o.is_correct);
      return answer === correctOption?.id;
    }
    case 'mcq_complex': {
      const correctIds = new Set(options.filter(o => o.is_correct).map(o => o.id));
      const chosenIds = new Set(Array.isArray(answer) ? answer : []);
      if (correctIds.size !== chosenIds.size) return false;
      for (const id of correctIds) {
        if (!chosenIds.has(id)) return false;
      }
      return true;
    }
    case 'true_false': {
      const correctOption = options.find(o => o.is_correct);
      return answer === correctOption?.option_text;
    }
    case 'short_answer':
    case 'essay':
    case 'uraian': {
      return typeof answer === 'string' && answer.trim().length > 0;
    }
    case 'sjt': {
      const rawOptions = question.bank_question_options || [];
      const maxWeight = Math.max(...rawOptions.map((o) => o.weight ?? 0));
      const selectedOpt = rawOptions.find((o) => o.id === answer);
      return selectedOpt ? (selectedOpt.weight ?? 0) === maxWeight : false;
    }
    case 'ordering': {
      const correctOrder: string[] = question.metadata?.correct_order || [];
      if (!Array.isArray(answer) || answer.length !== correctOrder.length) return false;
      return answer.every((id, i) => id === correctOrder[i]);
    }
    default:
      return false;
  }
}

export function calculateScore(question: Question, answer: AnswerValue): number {
  if (!isCorrectAnswer(question, answer)) return 0;
  return question.score_default || 1;
}

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { ensureAbsoluteUrl } from '@/utils/url';
import * as XLSX from 'xlsx';

import type { FileType } from './viewer/types';
import { detectFileType } from './viewer/types';
import ViewerShell from './viewer/ViewerShell';
import PDFContent from './viewer/PDFContent';
import ImageContent from './viewer/ImageContent';
import VideoContent from './viewer/VideoContent';
import AudioContent from './viewer/AudioContent';
import ExcelContent from './viewer/ExcelContent';
import OfficeContent from './viewer/OfficeContent';

interface PDFViewerProps {
    url: string;
    title: string;
    onClose: () => void;
}

export default function PDFViewer({ url, title, onClose }: PDFViewerProps) {
    const fileUrl = ensureAbsoluteUrl(url);
    const filename = fileUrl.split('?')[0];
    const fileType: FileType = detectFileType(filename);

    const [blobUrl, setBlobUrl] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [progress, setProgress] = useState('Memuat dokumen...');
    const [excelData, setExcelData] = useState<{ sheetName: string; data: any[][] }[]>([]);
    const [useOfficeViewer, setUseOfficeViewer] = useState(false);
    const cancelledRef = useRef(false);

    const needsProxy = fileType === 'pdf' || fileType === 'excel' || fileType === 'word' || fileType === 'ppt' || fileType === 'image';

    // Load blob via proxy
    useEffect(() => {
        if (!needsProxy) return;

        cancelledRef.current = false;
        let objectUrl: string | null = null;

        const load = async () => {
            setLoading(true);
            setError('');
            setProgress('Menghubungi server...');
            try {
                const proxyUrl = `/api/pdf-proxy?url=${encodeURIComponent(fileUrl)}`;
                setProgress('Mengunduh file...');
                const res = await fetch(proxyUrl);
                if (!res.ok) throw new Error(`Gagal memuat (${res.status})`);
                if (cancelledRef.current) return;
                setProgress('Memproses...');
                const blob = await res.blob();
                if (cancelledRef.current) return;

                objectUrl = URL.createObjectURL(blob);
                setBlobUrl(objectUrl);

                if (fileType === 'excel') {
                    try {
                        const buffer = await blob.arrayBuffer();
                        const workbook = XLSX.read(buffer, { type: 'array' });
                        const allSheets = workbook.SheetNames.map(sheetName => {
                            const worksheet = workbook.Sheets[sheetName];
                            const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
                            return { sheetName, data: jsonData as any[][] };
                        });
                        setExcelData(allSheets);
                    } catch {
                        setUseOfficeViewer(true);
                    }
                } else if (fileType === 'word' || fileType === 'ppt') {
                    setUseOfficeViewer(true);
                }

                setLoading(false);
            } catch (err: any) {
                if (cancelledRef.current) return;
                setError(err.message || 'Gagal memuat dokumen');
                setLoading(false);
            }
        };

        load();
        return () => {
            cancelledRef.current = true;
            if (objectUrl) URL.revokeObjectURL(objectUrl);
        };
    }, [fileUrl, fileType, needsProxy]);

    const handleRetry = useCallback(() => {
        window.location.reload();
    }, []);

    // ── Render per type ──
    if (fileType === 'image') {
        return (
            <ViewerShell
                title={title}
                fileType="image"
                onClose={onClose}
                fileUrl={fileUrl}
                blobUrl={blobUrl}
                loading={loading}
                error={error}
                progress={progress}
                onRetry={handleRetry}
            >
                <ImageContent src={blobUrl || fileUrl} alt={title} loading={loading} progress={progress} />
            </ViewerShell>
        );
    }

    if (fileType === 'video') {
        return (
            <ViewerShell title={title} fileType="video" onClose={onClose} fileUrl={fileUrl} hideFooter>
                <VideoContent url={fileUrl} />
            </ViewerShell>
        );
    }

    if (fileType === 'audio') {
        return (
            <ViewerShell title={title} fileType="audio" onClose={onClose} fileUrl={fileUrl} hideFooter>
                <AudioContent url={fileUrl} title={title} />
            </ViewerShell>
        );
    }

    if (fileType === 'excel' && excelData.length > 0 && !loading && !error) {
        return (
            <ViewerShell
                title={title}
                fileType="excel"
                onClose={onClose}
                fileUrl={fileUrl}
                blobUrl={blobUrl}
                loading={loading}
                error={error}
                progress={progress}
                onRetry={handleRetry}
            >
                <ExcelContent sheets={excelData} />
            </ViewerShell>
        );
    }

    if ((fileType === 'word' || fileType === 'ppt' || (fileType === 'excel' && useOfficeViewer)) && !loading && !error) {
        return (
            <ViewerShell
                title={title}
                fileType={fileType}
                onClose={onClose}
                fileUrl={fileUrl}
                blobUrl={blobUrl}
            >
                <OfficeContent fileUrl={fileUrl} fileType={fileType} title={title} />
            </ViewerShell>
        );
    }

    // ── PDF / Default ──
    return (
        <ViewerShell
            title={title}
            fileType={fileType === 'pdf' ? 'pdf' : 'unknown'}
            onClose={onClose}
            fileUrl={fileUrl}
            blobUrl={blobUrl}
            loading={loading}
            error={error}
            progress={progress}
            onRetry={handleRetry}
            hideFooter={fileType === 'pdf' && !!blobUrl}
            footerContent={
                fileType === 'pdf' && blobUrl ? (
                    <div className="flex items-center justify-center py-2.5 bg-[#181b24] border-t border-white/5">
                        <span className="text-[11px] text-white/30">
                            Tekan <kbd className="px-1.5 py-0.5 rounded bg-white/10 text-white/60 text-[10px] font-mono mx-0.5">ESC</kbd> untuk menutup
                        </span>
                    </div>
                ) : undefined
            }
        >
            {blobUrl && !loading && !error && fileType === 'pdf' && (
                <PDFContent blobUrl={blobUrl} />
            )}
        </ViewerShell>
    );
}

'use client';

import { useState } from 'react';

interface SheetData {
    sheetName: string;
    data: any[][];
}

interface ExcelContentProps {
    sheets: SheetData[];
}

export default function ExcelContent({ sheets }: ExcelContentProps) {
    const [activeIndex, setActiveIndex] = useState(0);
    const activeSheet = sheets[activeIndex];

    return (
        <div className="flex flex-col h-full bg-white">
            {/* Sheet Tabs */}
            {sheets.length > 1 && (
                <div className="flex items-center gap-1 px-4 py-2.5 bg-[#f8fafc] border-b border-gray-200 overflow-x-auto shrink-0">
                    <i className="bi bi-table text-emerald-600 mr-1.5 text-sm shrink-0" />
                    {sheets.map((sheet, idx) => (
                        <button
                            key={sheet.sheetName}
                            onClick={() => setActiveIndex(idx)}
                            className={`px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all shrink-0 ${
                                idx === activeIndex
                                    ? 'bg-emerald-600 text-white shadow-sm'
                                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                            }`}
                        >
                            <i className={`bi ${idx === activeIndex ? 'bi-check-circle-fill' : 'bi-circle'} mr-1.5 text-[10px]`} />
                            {sheet.sheetName}
                            <span className={`ml-1.5 px-1.5 py-0.5 rounded text-[10px] ${
                                idx === activeIndex ? 'bg-white/20 text-white' : 'bg-gray-200 text-gray-500'
                            }`}>
                                {sheet.data.length}
                            </span>
                        </button>
                    ))}
                </div>
            )}

            {/* Table */}
            <div className="flex-1 overflow-auto p-4 bg-[#f8fafc]">
                {activeSheet && activeSheet.data.length > 0 ? (
                    <div className="overflow-x-auto">
                        <table className="w-full border-collapse text-xs bg-white rounded-xl shadow-sm overflow-hidden">
                            <tbody>
                                {activeSheet.data.map((row, rowIdx) => (
                                    <tr key={rowIdx} className={rowIdx < activeSheet.data.length - 1 ? 'border-b border-gray-100' : ''}>
                                        <td className="px-3 py-2 border-r border-gray-100 bg-gray-50 text-gray-400 text-[10px] font-semibold text-center min-w-[32px]">
                                            {rowIdx + 1}
                                        </td>
                                        {row.map((cell: any, cellIdx: number) => (
                                            <td
                                                key={cellIdx}
                                                className={`px-3 py-2 border-r border-gray-100 whitespace-pre-wrap break-words max-w-[280px] ${
                                                    rowIdx === 0 ? 'bg-green-50 font-semibold text-gray-700' : 'text-gray-600'
                                                }`}
                                            >
                                                {cell !== null && cell !== undefined ? String(cell) : ''}
                                            </td>
                                        ))}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-full text-gray-300 gap-3">
                        <i className="bi bi-inbox text-4xl opacity-40" />
                        <p className="text-sm m-0">Sheet kosong</p>
                    </div>
                )}
            </div>

            {/* Footer */}
            <div className="flex items-center justify-between px-4 py-2.5 bg-white border-t border-gray-100 shrink-0">
                <span className="text-[11px] text-gray-400">
                    <i className="bi bi-file-earmark-excel text-emerald-600 mr-1.5" />
                    {activeSheet?.sheetName}
                </span>
                <span className="text-[11px] text-gray-400">
                    {activeSheet?.data.length || 0} baris &times; {activeSheet?.data[0]?.length || 0} kolom
                </span>
            </div>
        </div>
    );
}

