'use client';

import { createPortal } from 'react-dom';
import { useEffect, useState } from 'react';
import type { FileType } from './types';
import { getFileIcon, getFileColor } from './types';

interface ViewerShellProps {
    title: string;
    fileType: FileType;
    onClose: () => void;
    children: React.ReactNode;
    /** Optional: URL for opening in new tab */
    fileUrl?: string;
    /** Optional: Blob URL for downloading */
    blobUrl?: string | null;
    /** Loading state */
    loading?: boolean;
    /** Error state */
    error?: string;
    /** Progress message during loading */
    progress?: string;
    /** Callback for retry */
    onRetry?: () => void;
    /** Extra header actions */
    headerActions?: React.ReactNode;
    /** Hide footer hint */
    hideFooter?: boolean;
    /** Custom footer content */
    footerContent?: React.ReactNode;
}

export default function ViewerShell({
    title,
    fileType,
    onClose,
    children,
    fileUrl,
    blobUrl,
    loading,
    error,
    progress = 'Memuat...',
    onRetry,
    headerActions,
    hideFooter,
    footerContent,
}: ViewerShellProps) {
    const [mounted, setMounted] = useState(false);

    useEffect(() => setMounted(true), []);

    useEffect(() => {
        const handleKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleKey);
        return () => window.removeEventListener('keydown', handleKey);
    }, [onClose]);

    if (!mounted) return null;

    const icon = getFileIcon(fileType);
    const color = getFileColor(fileType);
    const fileLabel: Record<FileType, string> = {
        pdf: 'PDF Document',
        image: 'Image',
        video: 'Video',
        audio: 'Audio',
        excel: 'Spreadsheet',
        word: 'Word Document',
        ppt: 'Presentation',
        unknown: 'File',
    };

    const handleDownload = () => {
        const a = document.createElement('a');
        a.href = blobUrl || fileUrl || '';
        a.download = title || 'dokumen';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    };

    return createPortal(
        <>
            {/* Backdrop */}
            <div
                onClick={onClose}
                className="fixed inset-0 z-[99990] bg-black/80 backdrop-blur-sm"
            />

            {/* Modal */}
            <div className="fixed inset-0 z-[99999] flex flex-col bg-[#0f1117] animate-[viewerIn_0.25s_ease-out]">
                {/* ── Header ── */}
                <header className="flex items-center justify-between px-4 py-3 bg-[#181b24] border-b border-white/5 shrink-0 select-none">
                    <div className="flex items-center gap-3 min-w-0 flex-1">
                        <div
                            className="w-9 h-9 rounded-lg flex items-center justify-center text-lg shrink-0"
                            style={{ background: `${color}22`, color }}
                        >
                            <i className={`bi ${icon}`} />
                        </div>
                        <div className="min-w-0 overflow-hidden">
                            <h2 className="text-sm font-semibold text-white truncate m-0">
                                {title}
                            </h2>
                            <p className="text-[11px] text-white/40 truncate m-0">
                                {loading
                                    ? progress
                                    : error
                                        ? 'Gagal memuat'
                                        : fileLabel[fileType]}
                            </p>
                        </div>
                    </div>

                    <div className="flex items-center gap-1.5 shrink-0">
                        {headerActions}

                        {fileUrl && (
                            <a
                                href={fileUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="w-9 h-9 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 transition-colors text-white/70 hover:text-white no-underline"
                                title="Buka di tab baru"
                            >
                                <i className="bi bi-box-arrow-up-right text-sm" />
                            </a>
                        )}

                        {(blobUrl || fileUrl) && (
                            <button
                                onClick={handleDownload}
                                className="w-9 h-9 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 transition-colors text-white/70 hover:text-white"
                                title="Download"
                            >
                                <i className="bi bi-download text-sm" />
                            </button>
                        )}

                        <button
                            onClick={onClose}
                            className="w-9 h-9 flex items-center justify-center rounded-lg bg-white/5 hover:bg-white/15 transition-colors text-white/50 hover:text-white"
                            title="Tutup (ESC)"
                        >
                            <i className="bi bi-x-lg text-sm" />
                        </button>
                    </div>
                </header>

                {/* ── Content ── */}
                <div className="flex-1 overflow-hidden relative">
                    {loading && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 text-white/60">
                            <div className="w-9 h-9 border-2 border-white/10 border-t-white/60 rounded-full animate-spin" />
                            <span className="text-sm font-medium">{progress}</span>
                        </div>
                    )}

                    {error && !loading && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 text-center p-8">
                            <div className="w-14 h-14 rounded-full bg-red-500/10 flex items-center justify-center">
                                <i className="bi bi-exclamation-triangle text-2xl text-red-400" />
                            </div>
                            <div>
                                <p className="text-red-400 text-sm font-medium m-0">{error}</p>
                                <p className="text-white/30 text-xs mt-1 m-0">Gagal memuat dokumen</p>
                            </div>
                            {onRetry && (
                                <button
                                    onClick={onRetry}
                                    className="px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-white text-sm font-medium transition-colors"
                                >
                                    <i className="bi bi-arrow-clockwise mr-2" />
                                    Coba Lagi
                                </button>
                            )}
                            {(blobUrl || fileUrl) && (
                                <button
                                    onClick={handleDownload}
                                    className="px-4 py-2 bg-blue-600 hover:bg-blue-500 rounded-lg text-white text-sm font-medium transition-colors"
                                >
                                    <i className="bi bi-download mr-2" />
                                    Download File
                                </button>
                            )}
                        </div>
                    )}

                    {!loading && !error && children}
                </div>

                {/* ── Footer ── */}
                {!hideFooter && !loading && !error && (
                    <footer className="shrink-0">
                        {footerContent || (
                            <div className="flex items-center justify-center py-2.5 bg-[#181b24] border-t border-white/5">
                                <span className="text-[11px] text-white/30">
                                    Tekan <kbd className="px-1.5 py-0.5 rounded bg-white/10 text-white/60 text-[10px] font-mono mx-0.5">ESC</kbd> untuk menutup
                                </span>
                            </div>
                        )}
                    </footer>
                )}
            </div>

            <style>{`
                @keyframes viewerIn {
                    from { opacity: 0; transform: scale(0.97); }
                    to { opacity: 1; transform: scale(1); }
                }
                button:active { transform: scale(0.92) !important; }
            `}</style>
        </>,
        document.body
    );
}

/**
 * Format jawaban siswa & kunci jawaban menjadi daftar baris teks yang mudah
 * dibaca, untuk panel perbandingan "Respons Anda vs Kunci Jawaban" (detail
 * hasil siswa) dan tampilan analisis guru.
 *
 * Konvensi penyimpanan (lihat ExamPage.handleAnswerSelect / submitExamAction):
 * - mcq / sjt / forced_choice / paired_comparison → selected_option_id (uuid)
 * - tipe kompleks (mcq_complex, true_false, matching, categorization,
 *   short_answer, checklist, ordering, ranking, likert, essay) → essay_answer
 *   berisi teks atau JSON.
 */

export interface DisplayOption {
    id: string;
    option_text?: string;
    text?: string;
    is_correct?: boolean;
    weight?: number;
    order?: number;
    metadata?: any;
    category_names?: string[];
}

export interface DisplayQuestion {
    type: string;
    question_text?: string;
    metadata?: any;
    options?: DisplayOption[];
}

const LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];

/** Buang tag HTML agar teks opsi aman ditampilkan sebagai baris ringkas. */
export function stripHtml(html: string): string {
    return (html || '')
        .replace(/<br\s*\/?>/gi, ' ')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/\s+/g, ' ')
        .trim();
}

function parseMaybeJson(value: any): any {
    if (value === null || value === undefined) return null;
    if (typeof value !== 'string') return value;
    const s = value.trim();
    if (s === '') return null;
    if (s.startsWith('{') || s.startsWith('[')) {
        try { return JSON.parse(s); } catch { return s; }
    }
    return s;
}

function optionText(opt: DisplayOption | undefined): string {
    if (!opt) return '';
    return stripHtml(opt.option_text || opt.text || '');
}

function optionLabel(options: DisplayOption[], opt: DisplayOption): string {
    const idx = options.findIndex(o => o.id === opt.id);
    const letter = idx >= 0 && idx < LETTERS.length ? `${LETTERS[idx]}. ` : '';
    return `${letter}${optionText(opt)}`;
}

function normalizedMetadata(q: DisplayQuestion): any {
    const raw = q?.metadata;
    if (!raw) return {};
    if (typeof raw === 'string') {
        try { return JSON.parse(raw); } catch { return {}; }
    }
    return raw;
}

/**
 * Jawaban yang DIPILIH / DIKETIK siswa sebagai daftar baris teks.
 * Mengembalikan [] jika tidak menjawab.
 */
export function formatStudentAnswer(
    question: DisplayQuestion,
    selectedOptionId?: string | null,
    essayAnswer?: any
): string[] {
    const type = (question?.type || '').toLowerCase();
    const options = question?.options || [];

    // Tipe berbasis satu opsi terpilih
    if (selectedOptionId) {
        const opt = options.find(o => o.id === selectedOptionId);
        if (opt) return [optionLabel(options, opt)];
        return ['(Opsi yang dipilih sudah tidak tersedia)'];
    }

    const parsed = parseMaybeJson(essayAnswer);
    if (parsed === null || parsed === undefined || parsed === '') return [];

    if (['essay', 'esay', 'uraian'].includes(type)) {
        if (typeof parsed === 'object' && !Array.isArray(parsed)) {
            const lines: string[] = [];
            if (parsed.text) lines.push(String(parsed.text));
            const fileCount = Array.isArray(parsed.fileUrls) ? parsed.fileUrls.length : 0;
            if (fileCount > 0) lines.push(`📎 ${fileCount} lampiran file`);
            if (parsed.videoUrl) lines.push(`🎥 Link video: ${parsed.videoUrl}`);
            return lines;
        }
        return [String(parsed)];
    }

    if (type === 'mcq_complex') {
        const ids: string[] = Array.isArray(parsed) ? parsed : [];
        return ids.map(id => {
            const opt = options.find(o => o.id === id);
            return opt ? optionLabel(options, opt) : '(Opsi tidak tersedia)';
        });
    }

    if (type === 'true_false' || type === 'checklist') {
        if (typeof parsed !== 'object' || Array.isArray(parsed)) return [String(parsed)];
        return options
            .filter(o => parsed[o.id] !== undefined && parsed[o.id] !== '')
            .map(o => `${optionText(o)} → ${String(parsed[o.id]).toUpperCase()}`);
    }

    if (type === 'matching' || type === 'categorization') {
        if (typeof parsed !== 'object' || Array.isArray(parsed)) return [String(parsed)];
        return options
            .filter(o => Array.isArray(parsed[o.id]) && parsed[o.id].length > 0)
            .map(o => `${optionText(o)} → ${parsed[o.id].join(', ')}`);
    }

    if (type === 'short_answer') {
        const arr: any[] = Array.isArray(parsed) ? parsed : [parsed];
        return arr
            .map((v, i) => ({ v: String(v ?? '').trim(), i }))
            .filter(x => x.v !== '')
            .map(x => (arr.length > 1 ? `Isian ${x.i + 1}: ${x.v}` : x.v));
    }

    if (type === 'ordering' || type === 'ranking') {
        if (Array.isArray(parsed)) {
            return parsed.map((id: string, i: number) => {
                const opt = options.find(o => o.id === id);
                return `${i + 1}. ${optionText(opt)}`;
            });
        }
        if (typeof parsed === 'object') {
            return options
                .filter(o => parsed[o.id] !== undefined && String(parsed[o.id]).trim() !== '')
                .map(o => `${optionText(o)} → urutan ${parsed[o.id]}`);
        }
        return [String(parsed)];
    }

    if (type === 'likert') {
        return [`Skala: ${String(parsed)} / 5`];
    }

    if (typeof parsed === 'object') return [JSON.stringify(parsed)];
    return [String(parsed)];
}

/**
 * Kunci jawaban sebagai daftar baris teks. Mengembalikan [] untuk tipe yang
 * tidak punya kunci objektif (esai, tipe kepribadian).
 */
export function formatAnswerKey(question: DisplayQuestion): string[] {
    const type = (question?.type || '').toLowerCase();
    const options = question?.options || [];
    const metadata = normalizedMetadata(question);

    if (['essay', 'esay', 'uraian', 'likert', 'forced_choice', 'paired_comparison', 'checklist', 'ranking'].includes(type)) {
        return [];
    }

    if (type === 'mcq') {
        return options.filter(o => o.is_correct).map(o => optionLabel(options, o));
    }

    if (type === 'sjt') {
        const maxWeight = Math.max(...options.map(o => o.weight ?? 0));
        return options.filter(o => (o.weight ?? 0) === maxWeight).map(o => optionLabel(options, o));
    }

    if (type === 'mcq_complex') {
        return options.filter(o => o.is_correct).map(o => optionLabel(options, o));
    }

    if (type === 'true_false') {
        return options.map(o => `${optionText(o)} → ${o.is_correct ? 'BENAR' : 'SALAH'}`);
    }

    if (type === 'matching') {
        return options
            .map(o => {
                const matches: string[] = o.metadata?.match_texts || (o.metadata?.match_text ? [o.metadata.match_text] : []);
                return matches.length > 0 ? `${optionText(o)} → ${matches.join(', ')}` : '';
            })
            .filter(Boolean);
    }

    if (type === 'categorization') {
        return options
            .map(o => {
                const cats: string[] = o.category_names || o.metadata?.category_names || (o.metadata?.category_name ? [o.metadata.category_name] : []);
                return cats.length > 0 ? `${optionText(o)} → ${cats.join(', ')}` : '';
            })
            .filter(Boolean);
    }

    if (type === 'short_answer') {
        const blanks: any[] = metadata?.blanks || [];
        return blanks
            .map((b, i) => {
                const vars: string[] = b?.variations || [];
                return vars.length > 0 ? (blanks.length > 1 ? `Isian ${i + 1}: ${vars.join(' / ')}` : vars.join(' / ')) : '';
            })
            .filter(Boolean);
    }

    if (type === 'ordering') {
        return [...options]
            .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
            .map((o, i) => `${i + 1}. ${optionText(o)}`);
    }

    return [];
}

/**
 * Utility function to safely parse answer values
 * Used across exam, results, and review pages
 */

export type AnswerValue = string | string[] | Record<string, any> | null | undefined;

/**
 * Safely parse JSON answer with fallback
 * @param val - The answer value (can be string, object, array, null, undefined)
 * @param fallback - Fallback value if parsing fails
 * @returns Parsed value or fallback
 */
export function parseAnswer<T>(val: AnswerValue, fallback: T): T {
    if (val === null || val === undefined || val === '') return fallback;
    if (typeof val !== 'string') return val as unknown as T;
    try {
        return JSON.parse(val);
    } catch {
        return fallback;
    }
}

/**
 * Parse answer for MCQ (single selection)
 */
export function parseMCQAnswer(val: AnswerValue): string | null {
    return parseAnswer<string | null>(val, null);
}

/**
 * Parse answer for MCQ Complex (multiple selections).
 *
 * Toleran terhadap dua bentuk warisan yang kalau di-fallback ke [] akan
 * MENGHAPUS jawaban siswa dari layar (dan dari centang berikutnya):
 * - id tunggal telanjang di kolom selected_option_id, sisa dari soal yang dulu
 *   bertipe `mcq` lalu diubah menjadi `mcq_complex`;
 * - string gabungan dipisah koma dari klien lama.
 */
export function parseMCQComplexAnswer(val: AnswerValue): string[] {
    if (val === null || val === undefined || val === '') return [];
    if (Array.isArray(val)) return val.map(String);

    if (typeof val === 'string') {
        const trimmed = val.trim();
        if (trimmed === '') return [];
        try {
            const parsed = JSON.parse(trimmed);
            if (Array.isArray(parsed)) return parsed.map(String);
            // JSON valid tapi bukan array (mis. sebuah id ber-tanda-kutip).
            return String(parsed).trim() === '' ? [] : [String(parsed)];
        } catch {
            return trimmed.split(',').map(s => s.trim()).filter(Boolean);
        }
    }

    return parseAnswer<string[]>(val, []);
}

/**
 * Parse answer for True/False
 */
export function parseTrueFalseAnswer(val: AnswerValue): Record<string, boolean> {
    return parseAnswer<Record<string, boolean>>(val, {});
}

/**
 * Parse answer for Categorization
 */
export function parseCategorizationAnswer(val: AnswerValue): Record<string, string[]> {
    return parseAnswer<Record<string, string[]>>(val, {});
}

/**
 * Parse answer for Matching
 */
export function parseMatchingAnswer(val: AnswerValue): Record<string, string[]> {
    return parseAnswer<Record<string, string[]>>(val, {});
}

/**
 * Parse answer for Short Answer (fill in the blanks)
 */
export function parseShortAnswer(val: AnswerValue): string[] {
    const parsed = parseAnswer<string[] | string>(val, []);
    // Handle legacy single string answers
    if (typeof parsed === 'string') {
        return [parsed];
    }
    return parsed;
}

/**
 * Normalize a short-answer string for comparison.
 *
 * Pencocokan sengaja PERSIS: hanya trim (buang spasi tepi) + lowercase.
 * Spasi di tengah TIDAK diubah — "x+y" dan "x + y" tetap dianggap berbeda.
 * Pembuat soal yang menuliskan sendiri setiap variasi jawaban yang diterima.
 * Fungsi ini dipakai baik oleh grading server maupun feedback client agar
 * alternatif yang terdaftar dinilai sama persis di kedua sisi.
 */
export function normalizeShortAnswer(val: string | null | undefined): string {
    return (val || '').trim().toLowerCase();
}

/**
 * Parse answer for Essay
 */
export function parseEssayAnswer(val: AnswerValue): string {
    return parseAnswer<string>(val, '');
}

/**
 * Parse answer for SJT — single selected option ID
 */
export function parseSJTAnswer(val: AnswerValue): string | null {
    return parseAnswer<string | null>(val, null);
}

/**
 * Parse answer for Ordering — ordered array of option IDs
 */
export function parseOrderingAnswer(val: AnswerValue): string[] {
    const parsed = parseAnswer<string[] | string>(val, []);
    if (typeof parsed === 'string') {
        try { return JSON.parse(parsed); } catch { return [parsed]; }
    }
    return parsed;
}

